// Modelo ActividadAgenda - Actividades/tareas en la agenda del supervisor
class ActividadAgenda {
  constructor({
    id = '',
    supervisorId = '',
    supervisorNombre = '',
    titulo = '',
    descripcion = '',
    fecha = Date.now(), // Fecha de la actividad (día específico)
    completada = false,
    fechaCompletada = null, // Timestamp cuando se marcó como completada
    createdAt = Date.now(),
    updatedAt = Date.now()
  } = {}) {
    this.id = id;
    this.supervisorId = supervisorId;
    this.supervisorNombre = supervisorNombre;
    this.titulo = titulo;
    this.descripcion = descripcion;
    this.fecha = fecha;
    this.completada = completada;
    this.fechaCompletada = fechaCompletada;
    this.createdAt = createdAt;
    this.updatedAt = updatedAt;
  }

  toMap() {
    return {
      id: this.id,
      supervisorId: this.supervisorId,
      supervisorNombre: this.supervisorNombre,
      titulo: this.titulo,
      descripcion: this.descripcion,
      fecha: this.fecha,
      completada: this.completada,
      fechaCompletada: this.fechaCompletada,
      createdAt: this.createdAt,
      updatedAt: this.updatedAt
    };
  }

  static fromMap(map) {
    return new ActividadAgenda({
      id: map.id || '',
      supervisorId: map.supervisorId || '',
      supervisorNombre: map.supervisorNombre || '',
      titulo: map.titulo || '',
      descripcion: map.descripcion || '',
      fecha: map.fecha || Date.now(),
      completada: map.completada || false,
      fechaCompletada: map.fechaCompletada || null,
      createdAt: map.createdAt || Date.now(),
      updatedAt: map.updatedAt || Date.now()
    });
  }
}

export default ActividadAgenda;

