import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CardActions,
  Button,
  Grid,
  Chip,
  Fab,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  CircularProgress,
  Divider,
} from '@mui/material';
import {
  Add,
  FilterList,
  Delete,
  Inventory,
  Schedule,
  LocationOn,
  CameraAlt,
  PhotoCamera,
} from '@mui/icons-material';
import ArqueoRepository from '../../repositories/ArqueoRepository';
import LocalRepository from '../../repositories/LocalRepository';
import ImagenRepository from '../../repositories/ImagenRepository';
import { getCurrentUser } from '../../services/auth';
import imageUploadService from '../../services/imageUploadService';
import CameraCapture from '../Common/CameraCapture';

const ArqueosTab = ({ user }) => {
  const [arqueos, setArqueos] = useState([]);
  const [locales, setLocales] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [showFilterDialog, setShowFilterDialog] = useState(false);
  const [filterState, setFilterState] = useState({
    localId: ''
  });
  const currentUser = getCurrentUser();

  // Cargar datos desde Firebase en tiempo real
  useEffect(() => {
    if (!user || !user.id) return;

    setLoading(true);

    // Suscribirse a arqueos del supervisor en tiempo real
    const unsubscribeArqueos = ArqueoRepository.subscribeToArqueosBySupervisor(user.id, (arqueos) => {
      console.log('Arqueos del supervisor recibidos de Firebase:', arqueos);
      setArqueos(arqueos);
      setLoading(false);
    });

    // Suscribirse a locales del supervisor en tiempo real
    const unsubscribeLocales = LocalRepository.subscribeToLocalesBySupervisor(user.id, (locales) => {
      console.log('Locales del supervisor recibidos de Firebase:', locales);
      setLocales(locales);
    });

    return () => {
      unsubscribeArqueos();
      unsubscribeLocales();
    };
  }, [user]);

  const handleCreateArqueo = async (formData) => {
    try {
      const local = locales.find(l => l.id === formData.localId);

      const arqueoData = {
        localId: formData.localId,
        localNombre: local?.nombre || 'Desconocido',
        supervisorId: user.id,
        supervisorNombre: user.nombre,
        imagenId: formData.imagenId || '',
        fecha: formData.fecha,
        createdAt: Date.now(),
        updatedAt: Date.now()
      };

      const result = await ArqueoRepository.createArqueo(arqueoData);
      if (result.success) {
        setShowCreateDialog(false);
      } else {
        console.error('Error creando arqueo:', result.error);
        alert('Error al crear el arqueo: ' + result.error);
      }
    } catch (error) {
      console.error('Error creando arqueo:', error);
      alert('Error al crear el arqueo');
    }
  };

  const handleDeleteArqueo = async (id) => {
    if (!window.confirm('¿Estás seguro de que quieres eliminar este arqueo?')) {
      return;
    }
    
    try {
      const result = await ArqueoRepository.deleteArqueo(id);
      if (result.success) {
        // Data will update via real-time subscription
      } else {
        console.error('Error eliminando arqueo:', result.error);
        alert('Error al eliminar el arqueo');
      }
    } catch (error) {
      console.error('Error eliminando arqueo:', error);
      alert('Error al eliminar el arqueo');
    }
  };

  const getFilteredArqueos = () => {
    return arqueos.filter(arqueo => {
      const matchesLocal = filterState.localId === '' || arqueo.localId === filterState.localId;
      return matchesLocal;
    });
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Cargando arqueos...</Typography>
      </Box>
    );
  }

  const filteredArqueos = getFilteredArqueos();

  return (
    <Box sx={{ p: 2 }}>
      {/* Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5" sx={{ fontWeight: 600 }}>
          Mis Arqueos
        </Typography>
        <Box>
          <Button
            variant="outlined"
            startIcon={<FilterList />}
            onClick={() => setShowFilterDialog(true)}
            sx={{ mr: 1 }}
          >
            Filtros
          </Button>
          <Fab
            color="primary"
            size="medium"
            onClick={() => setShowCreateDialog(true)}
          >
            <Add />
          </Fab>
        </Box>
      </Box>

      {/* Filtros Activos */}
      <Box sx={{ mb: 2 }}>
        <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>Filtros activos:</Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          {filterState.localId && (
            <Chip
              label={`Local: ${locales.find(l => l.id === filterState.localId)?.nombre || 'Desconocido'}`}
              onDelete={() => setFilterState(prev => ({ ...prev, localId: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {!filterState.localId && (
            <Typography variant="body2" color="text.secondary">Ninguno</Typography>
          )}
        </Box>
      </Box>

      {/* Lista de Arqueos */}
      {filteredArqueos.length === 0 ? (
        <Card sx={{ textAlign: 'center', py: 4 }}>
          <CardContent>
            <Inventory sx={{ fontSize: 60, color: 'text.secondary', mb: 2 }} />
            <Typography variant="h6" color="text.secondary">
              No hay arqueos registrados.
            </Typography>
            <Button
              variant="contained"
              startIcon={<Add />}
              onClick={() => setShowCreateDialog(true)}
              sx={{ mt: 2 }}
            >
              Crear Nuevo Arqueo
            </Button>
          </CardContent>
        </Card>
      ) : (
        <Grid container spacing={2}>
          {filteredArqueos.map((arqueo) => (
            <Grid item xs={12} sm={6} md={4} key={arqueo.id}>
              <ArqueoCard
                arqueo={arqueo}
                onDelete={() => handleDeleteArqueo(arqueo.id)}
              />
            </Grid>
          ))}
        </Grid>
      )}

      {/* Dialog para Crear Arqueo */}
      <CreateArqueoDialog
        open={showCreateDialog}
        onClose={() => setShowCreateDialog(false)}
        onSubmit={handleCreateArqueo}
        locales={locales}
      />

      {/* Dialog para Filtros */}
      <FilterArqueosDialog
        open={showFilterDialog}
        onClose={() => setShowFilterDialog(false)}
        filterState={filterState}
        onFilterChange={setFilterState}
        locales={locales}
      />
    </Box>
  );
};

const ArqueoCard = ({ arqueo, onDelete }) => {
  const [showImage, setShowImage] = useState(false);
  const [imagen, setImagen] = useState(null);
  const [loadingImage, setLoadingImage] = useState(false);

  // Cargar imagen desde ImagenRepository cuando hay un imagenId
  useEffect(() => {
    if (arqueo.imagenId && !imagen) {
      setLoadingImage(true);
      ImagenRepository.getImagenById(arqueo.imagenId)
        .then(result => {
          if (result.success) {
            const img = result.imagen;
            // Si la URL está vacía pero hay dataBase64, construir la URL
            if (!img.url && img.dataBase64) {
              img.url = `data:${img.mimeType || 'image/jpeg'};base64,${img.dataBase64}`;
            }
            if (!img.thumbnailUrl && img.dataBase64) {
              img.thumbnailUrl = img.url; // Usar la misma imagen como thumbnail
            }
            setImagen(img);
            console.log('Imagen procesada:', img);
          } else {
            console.error('Error cargando imagen:', result.error);
          }
          setLoadingImage(false);
        })
        .catch(error => {
          console.error('Error cargando imagen:', error);
          setLoadingImage(false);
        });
    }
  }, [arqueo.imagenId, imagen]);

  return (
    <>
      <Card sx={{ '&:hover': { boxShadow: 4 }, height: '100%', display: 'flex', flexDirection: 'column' }}>
        <CardContent sx={{ flexGrow: 1 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
            <Typography variant="h6" sx={{ fontWeight: 600, display: 'flex', alignItems: 'center' }}>
              <Inventory sx={{ mr: 1 }} />
              Arqueo
            </Typography>
            <Chip
              label={new Date(arqueo.fecha).toLocaleDateString('es-AR')}
              color="primary"
              size="small"
              icon={<Schedule fontSize="small" />}
            />
          </Box>

          <Box sx={{ mb: 2 }}>
            <Typography variant="body2" color="text.secondary" sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
              <LocationOn fontSize="small" sx={{ mr: 0.5 }} />
              {arqueo.localNombre}
            </Typography>
          </Box>

          {arqueo.imagenId && (
            <Box sx={{ mb: 2 }}>
              {loadingImage ? (
                <Box sx={{ display: 'flex', justifyContent: 'center', p: 2 }}>
                  <CircularProgress size={24} />
                </Box>
              ) : imagen ? (
                <Box
                  onClick={() => setShowImage(true)}
                  sx={{
                    cursor: 'pointer',
                    borderRadius: 1,
                    overflow: 'hidden',
                    border: '1px solid',
                    borderColor: 'divider',
                    '&:hover': {
                      opacity: 0.8
                    }
                  }}
                >
                  <img
                    src={imagen.thumbnailUrl || imagen.url}
                    alt="Miniatura del arqueo"
                    style={{
                      width: '100%',
                      height: '150px',
                      objectFit: 'cover'
                    }}
                    onError={(e) => {
                      console.error('Error cargando imagen miniatura:', e);
                      console.error('URL que falló:', imagen.thumbnailUrl || imagen.url);
                      console.error('Imagen completa:', imagen);
                    }}
                  />
                </Box>
              ) : (
                <Button
                  size="small"
                  startIcon={<PhotoCamera />}
                  onClick={() => setShowImage(true)}
                  variant="outlined"
                  fullWidth
                >
                  Ver Foto
                </Button>
              )}
            </Box>
          )}

          <Divider sx={{ my: 1 }} />

          <Typography variant="caption" color="text.secondary">
            Creado: {new Date(arqueo.createdAt).toLocaleDateString('es-AR')}
          </Typography>
        </CardContent>
        <CardActions>
          <Button size="small" color="error" startIcon={<Delete />} onClick={onDelete}>
            Eliminar
          </Button>
        </CardActions>
      </Card>

      {/* Dialog para mostrar la imagen */}
      <Dialog open={showImage} onClose={() => setShowImage(false)} maxWidth="md" fullWidth>
        <DialogTitle>Imagen del Arqueo</DialogTitle>
        <DialogContent>
          {loadingImage ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
              <CircularProgress />
            </Box>
          ) : imagen ? (
            <img 
              src={imagen.url} 
              alt="Arqueo" 
              style={{ width: '100%', height: 'auto' }}
              onError={(e) => {
                console.error('Error cargando imagen grande:', e);
                console.error('URL que falló:', imagen.url);
                console.error('Imagen completa:', imagen);
              }}
            />
          ) : (
            <Typography>No se pudo cargar la imagen</Typography>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setShowImage(false)}>Cerrar</Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

const CreateArqueoDialog = ({ open, onClose, onSubmit, locales }) => {
  const [formData, setFormData] = useState({
    localId: '',
    fecha: new Date().toISOString().split('T')[0], // Fecha de hoy por defecto
    imagenId: '',
    imagenPreview: null,
    uploading: false
  });
  const [showCamera, setShowCamera] = useState(false);

  useEffect(() => {
    if (!open) {
      setFormData({
        localId: '',
        fecha: new Date().toISOString().split('T')[0],
        imagenId: '',
        imagenPreview: null,
        uploading: false
      });
    }
  }, [open]);

  const handleImageUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    // Validar que sea una imagen
    if (!file.type.startsWith('image/')) {
      alert('Por favor selecciona un archivo de imagen');
      return;
    }

    setFormData(prev => ({ ...prev, uploading: true }));

    try {
      // El servicio de imágenes automáticamente comprime si es necesario
      const imageData = await imageUploadService.uploadImage(file, 'arqueos');
      
      // Guardar en ImagenRepository
      const imagenToSave = {
        nombre: file.name,
        mimeType: file.type,
        size: file.size,
        url: imageData.url, // Data URL (base64)
        thumbnailUrl: imageData.thumbnailUrl || '',
        createdTime: new Date().toISOString(),
        tipo: 'arqueo' // Para identificar que es de arqueos
      };

      const result = await ImagenRepository.saveImagen(imagenToSave);
      
      if (result.success) {
        setFormData(prev => ({ 
          ...prev, 
          imagenId: result.id,
          imagenPreview: imageData.thumbnailUrl || imageData.url,
          uploading: false 
        }));
      } else {
        alert('Error al guardar la imagen: ' + result.error);
        setFormData(prev => ({ ...prev, uploading: false }));
      }
    } catch (error) {
      console.error('Error subiendo imagen:', error);
      alert('Error al subir la imagen: ' + error.message);
      setFormData(prev => ({ ...prev, uploading: false }));
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (!formData.imagenId) {
      alert('Por favor sube una foto del arqueo');
      return;
    }

    // Convertir la fecha a timestamp en zona horaria local (no UTC)
    const [year, month, day] = formData.fecha.split('-').map(Number);
    const fecha = new Date(year, month - 1, day, 0, 0, 0, 0);
    const fechaTimestamp = fecha.getTime();
    onSubmit({ ...formData, fecha: fechaTimestamp });
  };

  const handleCameraCapture = async (file) => {
    setFormData(prev => ({ ...prev, uploading: true }));

    try {
      // El servicio de imágenes automáticamente comprime si es necesario
      const imageData = await imageUploadService.uploadImage(file, 'arqueos');
      
      // Guardar en ImagenRepository
      const imagenToSave = {
        nombre: file.name,
        mimeType: file.type,
        size: file.size,
        url: imageData.url, // Data URL (base64)
        thumbnailUrl: imageData.thumbnailUrl || '',
        createdTime: new Date().toISOString(),
        tipo: 'arqueo'
      };

      const result = await ImagenRepository.saveImagen(imagenToSave);
      
      if (result.success) {
        setFormData(prev => ({ 
          ...prev, 
          imagenId: result.id,
          imagenPreview: imageData.thumbnailUrl || imageData.url,
          uploading: false 
        }));
      } else {
        alert('Error al guardar la imagen: ' + result.error);
        setFormData(prev => ({ ...prev, uploading: false }));
      }
    } catch (error) {
      console.error('Error subiendo imagen:', error);
      alert('Error al subir la imagen: ' + error.message);
      setFormData(prev => ({ ...prev, uploading: false }));
    }
  };

  return (
    <>
      <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
        <DialogTitle>Crear Nuevo Arqueo</DialogTitle>
        <form onSubmit={handleSubmit}>
        <DialogContent>
          <Grid container spacing={2}>
            <Grid item xs={12}>
              <FormControl fullWidth required>
                <InputLabel>Local *</InputLabel>
                <Select
                  value={formData.localId}
                  onChange={(e) => setFormData(prev => ({ ...prev, localId: e.target.value }))}
                  label="Local *"
                >
                  <MenuItem value="">Seleccionar local</MenuItem>
                  {locales.map(local => (
                    <MenuItem key={local.id} value={local.id}>{local.nombre}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Fecha del Arqueo *"
                type="date"
                value={formData.fecha}
                onChange={(e) => setFormData(prev => ({ ...prev, fecha: e.target.value }))}
                required
                InputLabelProps={{
                  shrink: true,
                }}
              />
            </Grid>
            <Grid item xs={12}>
              <Box sx={{ border: '1px dashed #ccc', borderRadius: 1, p: 2, textAlign: 'center' }}>
                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'center', flexWrap: 'wrap' }}>
                  {/* Botón para tomar foto con cámara */}
                  <Button
                    variant="contained"
                    startIcon={<PhotoCamera />}
                    onClick={() => setShowCamera(true)}
                    disabled={formData.uploading}
                  >
                    Tomar Foto
                  </Button>

                  {/* Botón para seleccionar de galería */}
                  <input
                    accept="image/*"
                    style={{ display: 'none' }}
                    id="raised-button-file"
                    type="file"
                    onChange={handleImageUpload}
                    disabled={formData.uploading}
                  />
                  <label htmlFor="raised-button-file">
                    <Button
                      variant="outlined"
                      component="span"
                      startIcon={formData.uploading ? <CircularProgress size={20} /> : <CameraAlt />}
                      disabled={formData.uploading}
                    >
                      {formData.uploading ? 'Subiendo...' : 'Elegir de Galería'}
                    </Button>
                  </label>
                </Box>

                <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                  La foto se comprimirá automáticamente
                </Typography>

                {formData.imagenId && formData.imagenPreview && (
                  <Box sx={{ mt: 2 }}>
                    <Chip label="✓ Foto cargada" color="success" />
                    <Box sx={{ mt: 1 }}>
                      <img 
                        src={formData.imagenPreview} 
                        alt="Preview" 
                        style={{ maxWidth: '100%', maxHeight: '200px' }}
                      />
                    </Box>
                  </Box>
                )}
              </Box>
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancelar</Button>
          <Button 
            type="submit" 
            variant="contained"
            disabled={formData.uploading || !formData.imagenId}
          >
            Crear Arqueo
          </Button>
        </DialogActions>
      </form>
    </Dialog>

    {/* Dialog de cámara */}
    <CameraCapture
      open={showCamera}
      onClose={() => setShowCamera(false)}
      onCapture={handleCameraCapture}
    />
    </>
  );
};

const FilterArqueosDialog = ({ open, onClose, filterState, onFilterChange, locales }) => {
  const [currentFilters, setCurrentFilters] = useState(filterState);

  useEffect(() => {
    setCurrentFilters(filterState);
  }, [filterState]);

  const handleFilterChange = (field) => (event) => {
    setCurrentFilters(prev => ({ ...prev, [field]: event.target.value }));
  };

  const handleApplyFilters = () => {
    onFilterChange(currentFilters);
    onClose();
  };

  const handleClearFilters = () => {
    setCurrentFilters({ localId: '' });
    onFilterChange({ localId: '' });
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>Filtrar Arqueos</DialogTitle>
      <DialogContent>
        <Grid container spacing={2}>
          <Grid item xs={12}>
            <FormControl fullWidth>
              <InputLabel>Local</InputLabel>
              <Select
                value={currentFilters.localId}
                onChange={handleFilterChange('localId')}
                label="Local"
              >
                <MenuItem value="">Todos los locales</MenuItem>
                {locales.map(local => (
                  <MenuItem key={local.id} value={local.id}>{local.nombre}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
        </Grid>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClearFilters}>Limpiar Filtros</Button>
        <Button onClick={handleApplyFilters} variant="contained">Aplicar Filtros</Button>
      </DialogActions>
    </Dialog>
  );
};

export default ArqueosTab;

