import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CardActions,
  Button,
  Grid,
  Chip,
  Fab,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Alert,
  CircularProgress,
  Avatar,
  Divider,
  List,
  ListItem,
  ListItemText,
  ListItemAvatar,
  Checkbox,
  FormControlLabel,
} from '@mui/material';
import {
  Add,
  Edit,
  Delete,
  Person,
  LocationOn,
  SupervisorAccount,
} from '@mui/icons-material';
import UserRepository from '../../repositories/UserRepository';
import LocalRepository from '../../repositories/LocalRepository';

const SupervisoresTab = ({ user }) => {
  const [supervisors, setSupervisors] = useState([]);
  const [locales, setLocales] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [editingSupervisor, setEditingSupervisor] = useState(null);
  const [deletingSupervisor, setDeletingSupervisor] = useState(null);

  // Cargar datos desde Firebase en tiempo real (igual que la app Android)
  useEffect(() => {
    setLoading(true);

    // Suscribirse a supervisores en tiempo real
    const unsubscribeSupervisors = UserRepository.subscribeToSupervisors((supervisors) => {
      console.log('Supervisores recibidos de Firebase:', supervisors);
      setSupervisors(supervisors);
    });

    // Suscribirse a locales en tiempo real
    const unsubscribeLocales = LocalRepository.subscribeToLocales((locales) => {
      console.log('Locales recibidos de Firebase:', locales);
      setLocales(locales);
    });

    setLoading(false);

    return () => {
      unsubscribeSupervisors();
      unsubscribeLocales();
    };
  }, []);

  const handleCreateSupervisor = async (formData) => {
    try {
      const supervisorData = {
        nombre: formData.nombre,
        username: formData.username,
        rol: 'SUPERVISOR',
        localesAsignados: formData.localesAsignados || [],
        createdAt: Date.now()
      };

      const result = await UserRepository.createUser(supervisorData, formData.password);
      if (result.success) {
        setShowCreateDialog(false);
        // Data will update via real-time subscription
      } else {
        console.error('Error creando supervisor:', result.error);
      }
    } catch (error) {
      console.error('Error creando supervisor:', error);
    }
  };

  const handleUpdateSupervisor = async (supervisorId, formData) => {
    try {
      const supervisorData = {
        nombre: formData.nombre,
        username: formData.username,
        rol: 'SUPERVISOR',
        localesAsignados: formData.localesAsignados || []
      };

      const result = await UserRepository.updateUser(supervisorId, supervisorData, formData.password);
      if (result.success) {
        setEditingSupervisor(null);
        // Data will update via real-time subscription
      } else {
        console.error('Error actualizando supervisor:', result.error);
      }
    } catch (error) {
      console.error('Error actualizando supervisor:', error);
    }
  };

  const handleDeleteSupervisor = async (supervisorId) => {
    try {
      const result = await UserRepository.deleteUser(supervisorId);
      if (result.success) {
        setDeletingSupervisor(null);
        // Data will update via real-time subscription
      } else {
        console.error('Error eliminando supervisor:', result.error);
      }
    } catch (error) {
      console.error('Error eliminando supervisor:', error);
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Cargando supervisores...</Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 2 }}>
      {/* Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5" sx={{ fontWeight: 600 }}>
          Supervisores
        </Typography>
        <Fab
          color="primary"
          size="medium"
          onClick={() => setShowCreateDialog(true)}
        >
          <Add />
        </Fab>
      </Box>

      {/* Lista de Supervisores */}
      {supervisors.length === 0 ? (
        <Card sx={{ textAlign: 'center', py: 4 }}>
          <CardContent>
            <Person sx={{ fontSize: 64, color: 'primary.main', mb: 2 }} />
            <Typography variant="h6" color="text.secondary">
              No hay supervisores registrados
            </Typography>
            <Button
              variant="contained"
              startIcon={<Add />}
              onClick={() => setShowCreateDialog(true)}
              sx={{ mt: 2 }}
            >
              Crear Primer Supervisor
            </Button>
          </CardContent>
        </Card>
      ) : (
        <Grid container spacing={2}>
          {supervisors.map((supervisor) => (
            <Grid item xs={12} sm={6} md={4} key={supervisor.id}>
              <SupervisorCard
                supervisor={supervisor}
                locales={locales.filter(l => l.supervisorId === supervisor.id)}
                onEdit={() => setEditingSupervisor(supervisor)}
                onDelete={() => setDeletingSupervisor(supervisor)}
              />
            </Grid>
          ))}
        </Grid>
      )}

      {/* Dialog para Crear/Editar Supervisor */}
      <CreateEditSupervisorDialog
        open={showCreateDialog || !!editingSupervisor}
        onClose={() => {
          setShowCreateDialog(false);
          setEditingSupervisor(null);
        }}
        onSubmit={editingSupervisor ? (data) => handleUpdateSupervisor(editingSupervisor.id, data) : handleCreateSupervisor}
        supervisor={editingSupervisor}
        locales={locales}
      />

      {/* Dialog para Confirmar Eliminación */}
      <DeleteSupervisorDialog
        open={!!deletingSupervisor}
        onClose={() => setDeletingSupervisor(null)}
        onConfirm={() => {
          if (deletingSupervisor) {
            handleDeleteSupervisor(deletingSupervisor.id);
          }
        }}
        supervisor={deletingSupervisor}
      />
    </Box>
  );
};

const SupervisorCard = ({ supervisor, locales, onEdit, onDelete }) => {
  return (
    <Card sx={{ '&:hover': { boxShadow: 4 }, height: '100%', display: 'flex', flexDirection: 'column' }}>
      <CardContent sx={{ flexGrow: 1 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
          <Avatar sx={{ mr: 2, bgcolor: 'primary.main' }}>
            <Person />
          </Avatar>
          <Box>
            <Typography variant="h6" sx={{ fontWeight: 600 }}>
              {supervisor.nombre}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              @{supervisor.username}
            </Typography>
          </Box>
        </Box>

        <Divider sx={{ my: 2 }} />

        <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
          Locales Asignados ({locales.length}):
        </Typography>
        
        {locales.length === 0 ? (
          <Typography variant="body2" color="text.secondary">
            Sin locales asignados
          </Typography>
        ) : (
          <List dense>
            {locales.map((local) => (
              <ListItem key={local.id} sx={{ px: 0, py: 0.5 }}>
                <ListItemAvatar>
                  <Avatar sx={{ width: 24, height: 24, bgcolor: 'secondary.main' }}>
                    <LocationOn sx={{ fontSize: 16 }} />
                  </Avatar>
                </ListItemAvatar>
                <ListItemText
                  primary={local.nombre}
                  secondary={local.estado}
                  primaryTypographyProps={{ variant: 'body2' }}
                  secondaryTypographyProps={{ variant: 'caption' }}
                />
              </ListItem>
            ))}
          </List>
        )}
      </CardContent>
      <CardActions>
        <Button size="small" startIcon={<Edit />} onClick={onEdit}>
          Editar
        </Button>
        <Button size="small" color="error" startIcon={<Delete />} onClick={onDelete}>
          Eliminar
        </Button>
      </CardActions>
    </Card>
  );
};

const CreateEditSupervisorDialog = ({ open, onClose, onSubmit, supervisor, locales }) => {
  const [formData, setFormData] = useState({
    nombre: '',
    username: '',
    password: '',
    localesAsignados: []
  });

  useEffect(() => {
    if (supervisor) {
      setFormData({
        nombre: supervisor.nombre,
        username: supervisor.username,
        password: '',
        localesAsignados: supervisor.localesAsignados || []
      });
    } else {
      setFormData({
        nombre: '',
        username: '',
        password: '',
        localesAsignados: []
      });
    }
  }, [supervisor]);

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit(formData);
    onClose();
  };

  const handleLocalToggle = (localId) => {
    setFormData(prev => ({
      ...prev,
      localesAsignados: prev.localesAsignados.includes(localId)
        ? prev.localesAsignados.filter(id => id !== localId)
        : [...prev.localesAsignados, localId]
    }));
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle>{supervisor ? 'Editar Supervisor' : 'Crear Nuevo Supervisor'}</DialogTitle>
      <form onSubmit={handleSubmit}>
        <DialogContent>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Nombre *"
                value={formData.nombre}
                onChange={(e) => setFormData(prev => ({ ...prev, nombre: e.target.value }))}
                required
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Username *"
                value={formData.username}
                onChange={(e) => setFormData(prev => ({ ...prev, username: e.target.value }))}
                required
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label={supervisor ? "Nueva Contraseña (opcional)" : "Contraseña *"}
                type="password"
                value={formData.password}
                onChange={(e) => setFormData(prev => ({ ...prev, password: e.target.value }))}
                required={!supervisor}
              />
            </Grid>
            <Grid item xs={12}>
              <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
                Locales Asignados:
              </Typography>
              <Box sx={{ maxHeight: 200, overflow: 'auto', border: 1, borderColor: 'divider', borderRadius: 1, p: 1 }}>
                {locales.map((local) => (
                  <FormControlLabel
                    key={local.id}
                    control={
                      <Checkbox
                        checked={formData.localesAsignados.includes(local.id)}
                        onChange={() => handleLocalToggle(local.id)}
                      />
                    }
                    label={local.nombre}
                  />
                ))}
              </Box>
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancelar</Button>
          <Button type="submit" variant="contained">
            {supervisor ? 'Actualizar' : 'Crear'}
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  );
};

const DeleteSupervisorDialog = ({ open, onClose, onConfirm, supervisor }) => {
  return (
    <Dialog open={open} onClose={onClose}>
      <DialogTitle>Confirmar Eliminación</DialogTitle>
      <DialogContent>
        <Typography>
          ¿Estás seguro de que quieres eliminar al supervisor "{supervisor?.nombre}"?
        </Typography>
        <Alert severity="warning" sx={{ mt: 2 }}>
          Esta acción no se puede deshacer.
        </Alert>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Cancelar</Button>
        <Button onClick={onConfirm} color="error" variant="contained">
          Eliminar
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default SupervisoresTab;