// Repositorio de Arqueos - Conecta con Firebase real
import { db } from '../services/firebase';
import { collection, doc, getDoc, setDoc, updateDoc, deleteDoc, getDocs, query, where, addDoc, onSnapshot } from 'firebase/firestore';
import Arqueo from '../models/Arqueo';

class ArqueoRepository {
  // Crear arqueo
  async createArqueo(arqueo) {
    try {
      // Si es un objeto plano, usarlo directamente; si tiene toMap, convertirlo
      const arqueoData = typeof arqueo.toMap === 'function' 
        ? arqueo.toMap() 
        : arqueo;
      
      const arqueosCollection = collection(db, 'arqueos');
      const docRef = await addDoc(arqueosCollection, arqueoData);
      
      return { success: true, id: docRef.id };
    } catch (error) {
      console.error('Error creando arqueo:', error);
      return { success: false, error: error.message };
    }
  }

  // Actualizar arqueo
  async updateArqueo(arqueoId, data) {
    try {
      const arqueoDocRef = doc(db, 'arqueos', arqueoId);
      await updateDoc(arqueoDocRef, {
        ...data,
        updatedAt: Date.now()
      });
      
      return { success: true };
    } catch (error) {
      console.error('Error actualizando arqueo:', error);
      return { success: false, error: error.message };
    }
  }

  // Eliminar arqueo
  async deleteArqueo(arqueoId) {
    try {
      const arqueoDocRef = doc(db, 'arqueos', arqueoId);
      await deleteDoc(arqueoDocRef);
      
      return { success: true };
    } catch (error) {
      console.error('Error eliminando arqueo:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener arqueo por ID
  async getArqueoById(arqueoId) {
    try {
      const arqueoDocRef = doc(db, 'arqueos', arqueoId);
      const arqueoDoc = await getDoc(arqueoDocRef);

      if (!arqueoDoc.exists()) {
        return { success: false, error: 'Arqueo no encontrado' };
      }

      const arqueoData = arqueoDoc.data();
      const arqueo = Arqueo.fromMap({ ...arqueoData, id: arqueoDoc.id });
      return { success: true, arqueo };
    } catch (error) {
      console.error('Error obteniendo arqueo:', error);
      return { success: false, error: error.message };
    }
  }

  // Suscribirse a todos los arqueos en tiempo real
  subscribeToArqueos(callback) {
    const arqueosCollection = collection(db, 'arqueos');
    
    return onSnapshot(arqueosCollection, (snapshot) => {
      const arqueos = [];
      snapshot.forEach(doc => {
        const arqueoData = doc.data();
        const arqueo = Arqueo.fromMap({ ...arqueoData, id: doc.id });
        arqueos.push(arqueo);
      });
      // Ordenar en memoria por fecha descendente
      arqueos.sort((a, b) => b.fecha - a.fecha);
      callback(arqueos);
    }, (error) => {
      console.error('Error suscribiéndose a arqueos:', error);
    });
  }

  // Suscribirse a arqueos por local en tiempo real
  subscribeToArqueosByLocal(localId, callback) {
    const arqueosCollection = collection(db, 'arqueos');
    const q = query(
      arqueosCollection,
      where('localId', '==', localId)
    );
    
    return onSnapshot(q, (snapshot) => {
      const arqueos = [];
      snapshot.forEach(doc => {
        const arqueoData = doc.data();
        const arqueo = Arqueo.fromMap({ ...arqueoData, id: doc.id });
        arqueos.push(arqueo);
      });
      // Ordenar en memoria por fecha descendente
      arqueos.sort((a, b) => b.fecha - a.fecha);
      callback(arqueos);
    }, (error) => {
      console.error('Error suscribiéndose a arqueos por local:', error);
    });
  }

  // Suscribirse a arqueos por supervisor en tiempo real
  subscribeToArqueosBySupervisor(supervisorId, callback) {
    const arqueosCollection = collection(db, 'arqueos');
    const q = query(
      arqueosCollection,
      where('supervisorId', '==', supervisorId)
    );
    
    return onSnapshot(q, (snapshot) => {
      const arqueos = [];
      snapshot.forEach(doc => {
        const arqueoData = doc.data();
        const arqueo = Arqueo.fromMap({ ...arqueoData, id: doc.id });
        arqueos.push(arqueo);
      });
      // Ordenar en memoria por fecha descendente
      arqueos.sort((a, b) => b.fecha - a.fecha);
      callback(arqueos);
    }, (error) => {
      console.error('Error suscribiéndose a arqueos por supervisor:', error);
    });
  }
}

export default new ArqueoRepository();

