// Repositorio de Locales - Conecta con Firebase real
import { db } from '../services/firebase';
import { collection, doc, getDoc, setDoc, updateDoc, deleteDoc, getDocs, query, where, orderBy } from 'firebase/firestore';
import { onSnapshot } from 'firebase/firestore';
import Local from '../models/Local';

class LocalRepository {
  // Crear local
  async createLocal(local) {
    try {
      // Usar el nombre del local como ID del documento
      const localId = local.nombre;
      
      // Verificar si el documento ya existe
      const localDocRef = doc(db, 'locales', localId);
      const existingDoc = await getDoc(localDocRef);

      if (existingDoc.exists()) {
        throw new Error('Ya existe un local con ese nombre');
      }

      // Si es un objeto plano, usarlo directamente; si tiene toMap, convertirlo
      const localData = typeof local.toMap === 'function' 
        ? local.toMap() 
        : local;

      await setDoc(localDocRef, localData);
      
      // Actualizar locales asignados del supervisor
      if (local.supervisorId && local.supervisorId.length > 0) {
        await this.updateSupervisorLocales(local.supervisorId, localId, 'add');
      }
      
      return { success: true, id: localId };
    } catch (error) {
      console.error('Error creando local:', error);
      return { success: false, error: error.message };
    }
  }

  // Actualizar local
  async updateLocal(localId, local) {
    try {
      // Si es un objeto plano, usarlo directamente; si tiene toMap, convertirlo
      const localData = typeof local.toMap === 'function' 
        ? local.toMap() 
        : local;

      const localDocRef = doc(db, 'locales', localId);
      await updateDoc(localDocRef, localData);
      return { success: true };
    } catch (error) {
      console.error('Error actualizando local:', error);
      return { success: false, error: error.message };
    }
  }

  // Eliminar local
  async deleteLocal(localId) {
    try {
      const localDocRef = doc(db, 'locales', localId);
      await deleteDoc(localDocRef);
      return { success: true };
    } catch (error) {
      console.error('Error eliminando local:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener local por ID
  async getLocalById(localId) {
    try {
      const localDocRef = doc(db, 'locales', localId);
      const localDoc = await getDoc(localDocRef);

      if (!localDoc.exists()) {
        return { success: false, error: 'Local no encontrado' };
      }

      const localData = localDoc.data();
      const local = Local.fromMap({ ...localData, id: localDoc.id });
      return { success: true, local };
    } catch (error) {
      console.error('Error obteniendo local:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener todos los locales
  async getAllLocales() {
    try {
      const localesCollection = collection(db, 'locales');
      const localesSnapshot = await getDocs(localesCollection);
      
      const locales = [];
      localesSnapshot.forEach(doc => {
        const localData = doc.data();
        const local = Local.fromMap({ ...localData, id: doc.id });
        locales.push(local);
      });

      return { success: true, locales };
    } catch (error) {
      console.error('Error obteniendo locales:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener locales por supervisor
  async getLocalesBySupervisor(supervisorId) {
    try {
      const localesCollection = collection(db, 'locales');
      const q = query(localesCollection, where('supervisorId', '==', supervisorId));
      const localesSnapshot = await getDocs(q);
      
      const locales = [];
      localesSnapshot.forEach(doc => {
        const localData = doc.data();
        const local = Local.fromMap({ ...localData, id: doc.id });
        locales.push(local);
      });

      return { success: true, locales };
    } catch (error) {
      console.error('Error obteniendo locales por supervisor:', error);
      return { success: false, error: error.message };
    }
  }

  // Escuchar cambios en locales (tiempo real)
  subscribeToLocales(callback) {
    const localesCollection = collection(db, 'locales');
    const q = query(localesCollection, orderBy('createdAt', 'desc'));
    
    return onSnapshot(q, (snapshot) => {
      const locales = [];
      snapshot.forEach(doc => {
        const localData = doc.data();
        const local = Local.fromMap({ ...localData, id: doc.id });
        locales.push(local);
      });
      callback(locales);
    });
  }

  // Escuchar cambios en locales por supervisor (tiempo real)
  subscribeToLocalesBySupervisor(supervisorId, callback) {
    const localesCollection = collection(db, 'locales');
    // Consulta simplificada sin orderBy para evitar el error de índice
    const q = query(
      localesCollection, 
      where('supervisorId', '==', supervisorId)
    );
    
    return onSnapshot(q, (snapshot) => {
      const locales = [];
      snapshot.forEach(doc => {
        const localData = doc.data();
        const local = Local.fromMap({ ...localData, id: doc.id });
        locales.push(local);
      });
      
      // Ordenar por fecha de creación (descendente) en el cliente
      locales.sort((a, b) => b.createdAt - a.createdAt);
      
      callback(locales);
    });
  }

  // Escuchar cambios en un local específico (tiempo real)
  subscribeToLocal(localId, callback) {
    const localDocRef = doc(db, 'locales', localId);
    
    return onSnapshot(localDocRef, (snapshot) => {
      if (snapshot.exists()) {
        const localData = snapshot.data();
        const local = Local.fromMap({ ...localData, id: snapshot.id });
        callback(local);
      } else {
        callback(null);
      }
    });
  }

  // Actualizar datos administrativos de un local
  async updateDatosAdministrativos(localId, datosAdministrativos) {
    try {
      const localDocRef = doc(db, 'locales', localId);
      await updateDoc(localDocRef, { 
        datosAdministrativos: datosAdministrativos,
        lastUpdate: Date.now()
      });
      return { success: true };
    } catch (error) {
      console.error('Error actualizando datos administrativos:', error);
      return { success: false, error: error.message };
    }
  }

  // Actualizar locales asignados del supervisor
  async updateSupervisorLocales(supervisorId, localId, action) {
    try {
      const userDocRef = doc(db, 'users', supervisorId);
      const userDoc = await getDoc(userDocRef);
      
      if (userDoc.exists()) {
        const userData = userDoc.data();
        const localesAsignados = userData.localesAsignados || [];
        
        let newLocales;
        if (action === 'add') {
          newLocales = [...localesAsignados, localId];
        } else if (action === 'remove') {
          newLocales = localesAsignados.filter(id => id !== localId);
        }
        
        await updateDoc(userDocRef, { localesAsignados: newLocales });
      }
    } catch (error) {
      console.error('Error actualizando locales del supervisor:', error);
    }
  }

  // Actualizar estado del local
  async updateLocalEstado(localId) {
    try {
      // Obtener pendientes activos del local
      const pendientesCollection = collection(db, 'pendientes');
      const pendientesQuery = query(
        pendientesCollection,
        where('localId', '==', localId),
        where('estado', 'in', ['asignado', 'recibido', 'en_proceso'])
      );
      const pendientesSnapshot = await getDocs(pendientesQuery);

      // Obtener gastos en espera del local
      const gastosCollection = collection(db, 'gastos');
      const gastosQuery = query(
        gastosCollection,
        where('localId', '==', localId),
        where('estado', '==', 'en_espera')
      );
      const gastosSnapshot = await getDocs(gastosQuery);

      // Determinar nuevo estado
      let nuevoEstado = 'activo';
      if (!gastosSnapshot.empty) {
        nuevoEstado = 'con_gastos_en_espera';
      } else if (!pendientesSnapshot.empty) {
        nuevoEstado = 'con_pendientes';
      }

      // Actualizar estado del local
      const localDocRef = doc(db, 'locales', localId);
      await updateDoc(localDocRef, { 
        estado: nuevoEstado,
        lastUpdate: Date.now()
      });
    } catch (error) {
      console.error('Error actualizando estado del local:', error);
    }
  }

}

export default new LocalRepository();
