// Modelo Notification - Extendido para sistema de vencimientos
class Notification {
  constructor({
    id = '',
    userId = '',
    tipo = '',
    titulo = '',
    mensaje = '',
    referenceId = '',
    leida = false,
    createdAt = Date.now(),
    // Campos adicionales para vencimientos
    localId = '',
    localNombre = '',
    pendienteId = '',
    urgencia = 'normal',
    fechaVencimiento = null,
    diasRestantes = null,
    categoria = '',
    fechaCreacion = Date.now()
  } = {}) {
    this.id = id;
    this.userId = userId;
    this.tipo = tipo;
    this.titulo = titulo;
    this.mensaje = mensaje;
    this.referenceId = referenceId;
    this.leida = leida;
    this.createdAt = createdAt;
    // Campos adicionales
    this.localId = localId;
    this.localNombre = localNombre;
    this.pendienteId = pendienteId;
    this.urgencia = urgencia;
    this.fechaVencimiento = fechaVencimiento;
    this.diasRestantes = diasRestantes;
    this.categoria = categoria;
    this.fechaCreacion = fechaCreacion;
  }

  toMap() {
    return {
      id: this.id,
      userId: this.userId,
      tipo: this.tipo,
      titulo: this.titulo,
      mensaje: this.mensaje,
      referenceId: this.referenceId,
      leida: this.leida,
      createdAt: this.createdAt,
      // Campos adicionales
      localId: this.localId,
      localNombre: this.localNombre,
      pendienteId: this.pendienteId,
      urgencia: this.urgencia,
      fechaVencimiento: this.fechaVencimiento,
      diasRestantes: this.diasRestantes,
      categoria: this.categoria,
      fechaCreacion: this.fechaCreacion
    };
  }

  static fromMap(map) {
    return new Notification({
      id: map.id ?? '',
      userId: map.userId ?? '',
      tipo: map.tipo ?? '',
      titulo: map.titulo ?? '',
      mensaje: map.mensaje ?? '',
      referenceId: map.referenceId ?? '',
      leida: map.leida ?? false,
      createdAt: map.createdAt ?? Date.now(),
      // Campos adicionales
      localId: map.localId ?? '',
      localNombre: map.localNombre ?? '',
      pendienteId: map.pendienteId ?? '',
      urgencia: map.urgencia ?? 'normal',
      fechaVencimiento: ('fechaVencimiento' in map) ? map.fechaVencimiento : null,
      diasRestantes: ('diasRestantes' in map) ? map.diasRestantes : null,
      categoria: map.categoria ?? '',
      fechaCreacion: map.fechaCreacion ?? Date.now()
    });
  }
}

export default Notification;