import React from 'react';
import {
  Card,
  CardContent,
  Skeleton,
  Box,
  Grid
} from '@mui/material';

const PendienteCardSkeleton = () => (
  <Card sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
    <CardContent sx={{ flexGrow: 1 }}>
      {/* Título skeleton */}
      <Skeleton variant="text" height={32} sx={{ mb: 2 }} />
      
      {/* Información skeleton */}
      <Box sx={{ mb: 2 }}>
        <Skeleton variant="text" height={20} width="80%" sx={{ mb: 0.5 }} />
        <Skeleton variant="text" height={20} width="70%" sx={{ mb: 0.5 }} />
        <Skeleton variant="text" height={20} width="60%" sx={{ mb: 0.5 }} />
        <Skeleton variant="text" height={20} width="50%" />
      </Box>
      
      {/* Chips skeleton */}
      <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
        <Skeleton variant="rectangular" height={24} width={80} sx={{ borderRadius: 1 }} />
        <Skeleton variant="rectangular" height={24} width={60} sx={{ borderRadius: 1 }} />
      </Box>
      
      {/* Chat skeleton */}
      <Box sx={{ mb: 2 }}>
        <Skeleton variant="text" height={16} width="30%" sx={{ mb: 1 }} />
        <Box sx={{ bgcolor: 'grey.50', p: 1, borderRadius: 1 }}>
          <Skeleton variant="rectangular" height={40} sx={{ borderRadius: 1, mb: 0.5 }} />
          <Skeleton variant="rectangular" height={40} sx={{ borderRadius: 1 }} />
        </Box>
      </Box>
      
      {/* Input skeleton */}
      <Box sx={{ display: 'flex', gap: 0.5 }}>
        <Skeleton variant="rectangular" height={36} sx={{ flex: 1, borderRadius: 1 }} />
        <Skeleton variant="rectangular" height={36} width={40} sx={{ borderRadius: 1 }} />
      </Box>
    </CardContent>
    
    {/* Botones skeleton */}
    <Box sx={{ p: 2, display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
      <Skeleton variant="rectangular" height={32} width={80} sx={{ borderRadius: 1 }} />
      <Skeleton variant="rectangular" height={32} width={80} sx={{ borderRadius: 1 }} />
    </Box>
  </Card>
);

const PendientesGridSkeleton = ({ count = 6 }) => (
  <Grid container spacing={{ xs: 1, sm: 2 }}>
    {Array.from({ length: count }).map((_, index) => (
      <Grid item xs={12} sm={6} md={4} key={index}>
        <PendienteCardSkeleton />
      </Grid>
    ))}
  </Grid>
);

const NotificationSkeleton = () => (
  <Box sx={{ 
    display: 'flex', 
    alignItems: 'flex-start', 
    p: 2, 
    mb: 1,
    bgcolor: 'background.paper',
    borderRadius: 2,
    boxShadow: 1
  }}>
    <Skeleton variant="circular" width={40} height={40} sx={{ mr: 2 }} />
    <Box sx={{ flex: 1 }}>
      <Skeleton variant="text" height={20} width="60%" sx={{ mb: 0.5 }} />
      <Skeleton variant="text" height={16} width="80%" sx={{ mb: 1 }} />
      <Box sx={{ display: 'flex', gap: 1 }}>
        <Skeleton variant="rectangular" height={20} width={60} sx={{ borderRadius: 1 }} />
        <Skeleton variant="rectangular" height={20} width={80} sx={{ borderRadius: 1 }} />
      </Box>
    </Box>
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
      <Skeleton variant="rectangular" height={24} width={24} sx={{ borderRadius: 1 }} />
      <Skeleton variant="rectangular" height={24} width={24} sx={{ borderRadius: 1 }} />
    </Box>
  </Box>
);

const NotificationsSkeleton = ({ count = 5 }) => (
  <Box>
    {Array.from({ length: count }).map((_, index) => (
      <NotificationSkeleton key={index} />
    ))}
  </Box>
);

export {
  PendienteCardSkeleton,
  PendientesGridSkeleton,
  NotificationSkeleton,
  NotificationsSkeleton
};
