// Modelo Arqueo - Similar a Gasto pero para control de mercadería
// Las fotos se guardan en la colección 'imagenes' y aquí solo guardamos el ID
class Arqueo {
  constructor({
    id = '',
    localId = '',
    localNombre = '',
    supervisorId = '',
    supervisorNombre = '',
    imagenId = '', // ID de la imagen en la colección 'imagenes'
    fecha = Date.now(), // Fecha del arqueo (puede ser diferente a createdAt)
    createdAt = Date.now(), // Fecha de creación/subida
    updatedAt = Date.now()
  } = {}) {
    this.id = id;
    this.localId = localId;
    this.localNombre = localNombre;
    this.supervisorId = supervisorId;
    this.supervisorNombre = supervisorNombre;
    this.imagenId = imagenId;
    this.fecha = fecha;
    this.createdAt = createdAt;
    this.updatedAt = updatedAt;
  }

  toMap() {
    return {
      id: this.id,
      localId: this.localId,
      localNombre: this.localNombre,
      supervisorId: this.supervisorId,
      supervisorNombre: this.supervisorNombre,
      imagenId: this.imagenId,
      fecha: this.fecha,
      createdAt: this.createdAt,
      updatedAt: this.updatedAt
    };
  }

  static fromMap(map) {
    return new Arqueo({
      id: map.id || '',
      localId: map.localId || '',
      localNombre: map.localNombre || '',
      supervisorId: map.supervisorId || '',
      supervisorNombre: map.supervisorNombre || '',
      imagenId: map.imagenId || '',
      fecha: map.fecha || Date.now(),
      createdAt: map.createdAt || Date.now(),
      updatedAt: map.updatedAt || Date.now()
    });
  }
}

export default Arqueo;

