import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CardActions,
  Button,
  Grid,
  Avatar,
  Chip,
  Alert,
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
} from '@mui/material';
import {
  LocationOn,
  Person,
  Phone,
  Edit,
  Visibility,
  Assignment,
  Receipt,
  TrendingUp,
} from '@mui/icons-material';
import LocalRepository from '../../repositories/LocalRepository';
import PendienteRepository from '../../repositories/PendienteRepository';
import GastoRepository from '../../repositories/GastoRepository';
import LocalDetailScreen from '../LocalDetail/LocalDetailScreen';

const LocalesTab = ({ user }) => {
  const [locales, setLocales] = useState([]);
  const [pendientes, setPendientes] = useState([]);
  const [gastos, setGastos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showEditDialog, setShowEditDialog] = useState(false);
  const [editingLocal, setEditingLocal] = useState(null);
  const [selectedLocalId, setSelectedLocalId] = useState(null);

  // Cargar locales del supervisor desde Firebase (igual que la app Android)
  useEffect(() => {
    if (!user || !user.id) return;

    setLoading(true);

    // Suscribirse a locales del supervisor en tiempo real
    const unsubscribeLocales = LocalRepository.subscribeToLocalesBySupervisor(user.id, (locales) => {
      console.log('Locales del supervisor recibidos de Firebase:', locales);
      setLocales(locales);
    });

    // Suscribirse a pendientes del supervisor en tiempo real
    const unsubscribePendientes = PendienteRepository.subscribeToPendientesBySupervisor(user.id, (pendientes) => {
      console.log('Pendientes del supervisor recibidos de Firebase:', pendientes);
      setPendientes(pendientes);
    });

    // Suscribirse a todos los gastos en tiempo real (luego se filtran por locales del supervisor)
    const unsubscribeGastos = GastoRepository.subscribeToGastos((gastos) => {
      console.log('Gastos recibidos de Firebase:', gastos);
      setGastos(gastos);
      setLoading(false);
    });

    return () => {
      unsubscribeLocales();
      unsubscribePendientes();
      unsubscribeGastos();
    };
  }, [user]);

  const handleEditLocal = (local) => {
    setEditingLocal(local);
    setShowEditDialog(true);
  };

  const handleViewDetails = (local) => {
    setSelectedLocalId(local.id);
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Cargando locales...</Typography>
      </Box>
    );
  }

  // Si hay un local seleccionado, mostrar la pantalla de detalles
  if (selectedLocalId) {
    return (
      <LocalDetailScreen 
        localId={selectedLocalId} 
        onBack={() => setSelectedLocalId(null)} 
      />
    );
  }

  return (
    <Box sx={{ p: 2 }}>
      {/* Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5" sx={{ fontWeight: 600 }}>
          Mis Locales
        </Typography>
        <Chip label={`${locales.length} locales asignados`} color="primary" />
      </Box>

      {/* Resumen de estadísticas - Datos reales filtrados por locales del supervisor */}
      <Grid container spacing={2} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ textAlign: 'center', py: 2 }}>
            <CardContent>
              <Typography variant="h4" color="primary" sx={{ fontWeight: 'bold' }}>
                {pendientes.filter(p => p.estado === 'asignado' || p.estado === 'en_proceso').length}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Pendientes Activos
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ textAlign: 'center', py: 2 }}>
            <CardContent>
              <Typography variant="h4" color="success.main" sx={{ fontWeight: 'bold' }}>
                {pendientes.filter(p => p.estado === 'realizado').length}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Pendientes Completados
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ textAlign: 'center', py: 2 }}>
            <CardContent>
              <Typography variant="h4" color="warning.main" sx={{ fontWeight: 'bold' }}>
                {(() => {
                  const localIds = locales.map(l => l.id);
                  return gastos.filter(g => g.estado === 'en_espera' && localIds.includes(g.localId)).length;
                })()}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Gastos Pendientes
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ textAlign: 'center', py: 2 }}>
            <CardContent>
              <Typography variant="h4" color="primary" sx={{ fontWeight: 'bold' }}>
                ${(() => {
                  const localIds = locales.map(l => l.id);
                  return gastos
                    .filter(g => g.estado === 'aprobado' && localIds.includes(g.localId))
                    .reduce((sum, g) => sum + (g.monto || 0), 0);
                })().toLocaleString('es-AR', { minimumFractionDigits: 2 })}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Total Gastos Aprobados
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Lista de locales */}
      {locales.length === 0 ? (
        <Card sx={{ textAlign: 'center', py: 4 }}>
          <CardContent>
            <Typography variant="h6" color="text.secondary">
              No tienes locales asignados
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Contacta con el administrador para que te asignen locales
            </Typography>
          </CardContent>
        </Card>
      ) : (
        <Grid container spacing={2}>
          {locales.map((local) => (
            <Grid item xs={12} md={6} key={local.id}>
              <Card sx={{ '&:hover': { boxShadow: 4 } }}>
                <CardContent>
                  {/* Header del local */}
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                      <Avatar sx={{ mr: 2, bgcolor: 'primary.main' }}>
                        <LocationOn />
                      </Avatar>
                      <Box>
                        <Typography variant="h6" sx={{ fontWeight: 600 }}>
                          {local.nombre}
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                          {local.datosAdministrativos?.direccion || 'Sin dirección'}
                        </Typography>
                      </Box>
                    </Box>
                    <Chip
                      label={local.estado === 'activo' ? 'Activo' : local.estado === 'con_pendientes' ? 'Con Pendientes' : local.estado}
                      color={local.estado === 'activo' ? 'success' : local.estado === 'con_pendientes' ? 'warning' : 'default'}
                      size="small"
                    />
                  </Box>

                  {/* Información de contacto */}
                  <Box sx={{ mb: 2 }}>
                    <Typography variant="body2" color="text.secondary" sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                      <Phone sx={{ fontSize: 16, mr: 1 }} />
                      {local.datosAdministrativos?.telefono || 'Sin teléfono'}
                    </Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ display: 'flex', alignItems: 'center' }}>
                      <Person sx={{ fontSize: 16, mr: 1 }} />
                      {user.nombre}
                    </Typography>
                  </Box>

                  {/* Estadísticas del local - Datos reales */}
                  <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
                    Estadísticas del Local:
                  </Typography>
                  <Grid container spacing={1} sx={{ mb: 2 }}>
                    {(() => {
                      // Calcular estadísticas reales para este local
                      const localPendientes = pendientes.filter(p => p.localId === local.id);
                      const localGastos = gastos.filter(g => g.localId === local.id);
                      
                      const pendientesActivos = localPendientes.filter(p => 
                        p.estado === 'asignado' || p.estado === 'en_proceso'
                      ).length;
                      const pendientesCompletados = localPendientes.filter(p => 
                        p.estado === 'realizado'
                      ).length;
                      const gastosPendientes = localGastos.filter(g => 
                        g.estado === 'en_espera'
                      ).length;
                      const gastosAprobados = localGastos.filter(g => 
                        g.estado === 'aprobado'
                      ).length;
                      const totalGastos = localGastos
                        .filter(g => g.estado === 'aprobado')
                        .reduce((sum, g) => sum + (g.monto || 0), 0);

                      return (
                        <>
                          <Grid item xs={6}>
                            <Box sx={{ display: 'flex', alignItems: 'center' }}>
                              <Assignment sx={{ fontSize: 16, mr: 1, color: 'primary.main' }} />
                              <Typography variant="body2">
                                {pendientesActivos} activos
                              </Typography>
                            </Box>
                          </Grid>
                          <Grid item xs={6}>
                            <Box sx={{ display: 'flex', alignItems: 'center' }}>
                              <Receipt sx={{ fontSize: 16, mr: 1, color: 'warning.main' }} />
                              <Typography variant="body2">
                                {gastosPendientes} gastos pendientes
                              </Typography>
                            </Box>
                          </Grid>
                          <Grid item xs={6}>
                            <Box sx={{ display: 'flex', alignItems: 'center' }}>
                              <TrendingUp sx={{ fontSize: 16, mr: 1, color: 'success.main' }} />
                              <Typography variant="body2">
                                {pendientesCompletados} completados
                              </Typography>
                            </Box>
                          </Grid>
                          <Grid item xs={6}>
                            <Box sx={{ display: 'flex', alignItems: 'center' }}>
                              <TrendingUp sx={{ fontSize: 16, mr: 1, color: 'success.main' }} />
                              <Typography variant="body2">
                                {gastosAprobados} gastos aprobados
                              </Typography>
                            </Box>
                          </Grid>
                          {totalGastos > 0 && (
                            <Grid item xs={12}>
                              <Box sx={{ mb: 2 }}>
                                <Typography variant="body2" color="text.secondary">
                                  Total gastos aprobados: <strong>${totalGastos.toLocaleString('es-AR', { minimumFractionDigits: 2 })}</strong>
                                </Typography>
                              </Box>
                            </Grid>
                          )}
                        </>
                      );
                    })()}
                  </Grid>
                </CardContent>
                <CardActions>
                  <Button
                    size="small"
                    startIcon={<Edit />}
                    onClick={() => handleEditLocal(local)}
                  >
                    Editar
                  </Button>
                  <Button
                    size="small"
                    startIcon={<Visibility />}
                    onClick={() => handleViewDetails(local)}
                  >
                    Ver Detalles
                  </Button>
                </CardActions>
              </Card>
            </Grid>
          ))}
        </Grid>
      )}

      {/* Dialog para editar local */}
      {editingLocal && (
        <EditLocalDialog
          open={showEditDialog}
          onClose={() => {
            setShowEditDialog(false);
            setEditingLocal(null);
          }}
          local={editingLocal}
        />
      )}
    </Box>
  );
};

// Componente para editar local
const EditLocalDialog = ({ open, onClose, local }) => {
  const [formData, setFormData] = useState({
    direccion: '',
    telefono: ''
  });

  useEffect(() => {
    if (local) {
      setFormData({
        direccion: local.datosAdministrativos?.direccion || '',
        telefono: local.datosAdministrativos?.telefono || ''
      });
    }
  }, [local]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      // Aquí actualizarías el local en Firebase
      console.log('Actualizando local:', local.id, formData);
      onClose();
    } catch (error) {
      console.error('Error actualizando local:', error);
    }
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>Editar Local: {local?.nombre}</DialogTitle>
      <form onSubmit={handleSubmit}>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
            <TextField
              fullWidth
              label="Dirección"
              value={formData.direccion}
              onChange={(e) => setFormData(prev => ({ ...prev, direccion: e.target.value }))}
            />
            <TextField
              fullWidth
              label="Teléfono"
              value={formData.telefono}
              onChange={(e) => setFormData(prev => ({ ...prev, telefono: e.target.value }))}
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancelar</Button>
          <Button type="submit" variant="contained">Guardar</Button>
        </DialogActions>
      </form>
    </Dialog>
  );
};

export default LocalesTab;