// Repositorio de Agenda - Conecta con Firebase
import { db } from '../services/firebase';
import { collection, doc, getDoc, updateDoc, deleteDoc, query, where, orderBy, addDoc, onSnapshot } from 'firebase/firestore';
import ActividadAgenda from '../models/ActividadAgenda';

class AgendaRepository {
  // Crear actividad
  async createActividad(actividad) {
    try {
      const actividadData = typeof actividad.toMap === 'function' 
        ? actividad.toMap() 
        : actividad;
      
      const actividadesCollection = collection(db, 'agenda');
      const docRef = await addDoc(actividadesCollection, actividadData);
      
      return { success: true, id: docRef.id };
    } catch (error) {
      console.error('Error creando actividad:', error);
      return { success: false, error: error.message };
    }
  }

  // Actualizar actividad
  async updateActividad(actividadId, data) {
    try {
      const actividadDocRef = doc(db, 'agenda', actividadId);
      await updateDoc(actividadDocRef, {
        ...data,
        updatedAt: Date.now()
      });
      
      return { success: true };
    } catch (error) {
      console.error('Error actualizando actividad:', error);
      return { success: false, error: error.message };
    }
  }

  // Marcar actividad como completada
  async marcarCompletada(actividadId, completada) {
    try {
      const actividadDocRef = doc(db, 'agenda', actividadId);
      await updateDoc(actividadDocRef, {
        completada: completada,
        fechaCompletada: completada ? Date.now() : null,
        updatedAt: Date.now()
      });
      
      return { success: true };
    } catch (error) {
      console.error('Error marcando actividad:', error);
      return { success: false, error: error.message };
    }
  }

  // Cambiar fecha de actividad
  async cambiarFecha(actividadId, nuevaFecha) {
    try {
      const actividadDocRef = doc(db, 'agenda', actividadId);
      await updateDoc(actividadDocRef, {
        fecha: nuevaFecha,
        updatedAt: Date.now()
      });
      
      return { success: true };
    } catch (error) {
      console.error('Error cambiando fecha:', error);
      return { success: false, error: error.message };
    }
  }

  // Eliminar actividad
  async deleteActividad(actividadId) {
    try {
      const actividadDocRef = doc(db, 'agenda', actividadId);
      await deleteDoc(actividadDocRef);
      
      return { success: true };
    } catch (error) {
      console.error('Error eliminando actividad:', error);
      return { success: false, error: error.message };
    }
  }

  // Suscribirse a actividades de un supervisor en tiempo real
  subscribeToActividadesBySupervisor(supervisorId, callback) {
    const actividadesCollection = collection(db, 'agenda');
    const q = query(
      actividadesCollection,
      where('supervisorId', '==', supervisorId)
    );
    
    return onSnapshot(q, (snapshot) => {
      const actividades = [];
      snapshot.forEach(doc => {
        const actividadData = doc.data();
        const actividad = ActividadAgenda.fromMap({ ...actividadData, id: doc.id });
        actividades.push(actividad);
      });
      // Ordenar por fecha en el cliente
      actividades.sort((a, b) => a.fecha - b.fecha);
      callback(actividades);
    }, (error) => {
      console.error('Error suscribiéndose a actividades:', error);
    });
  }

  // Suscribirse a todas las actividades (para el maestro)
  subscribeToTodasActividades(callback) {
    const actividadesCollection = collection(db, 'agenda');
    const q = query(actividadesCollection);
    
    return onSnapshot(q, (snapshot) => {
      const actividades = [];
      snapshot.forEach(doc => {
        const actividadData = doc.data();
        const actividad = ActividadAgenda.fromMap({ ...actividadData, id: doc.id });
        actividades.push(actividad);
      });
      // Ordenar por fecha
      actividades.sort((a, b) => a.fecha - b.fecha);
      callback(actividades);
    }, (error) => {
      console.error('Error suscribiéndose a actividades:', error);
    });
  }
}

export default new AgendaRepository();

