// Servicio de autenticación - Conecta con Firebase real
import { db } from './firebase';
import { doc, getDoc } from 'firebase/firestore';
import User from '../models/User';

export const AUTH_TOKEN_KEY = 'authToken';
export const USER_KEY = 'user';

// Verificar conexión a Firebase real (igual que tu app Android)
export const checkFirebaseConnection = async () => {
  try {
    // Intentar una operación simple para verificar la conexión - igual que tu app Android
    const testDoc = doc(db, 'users', 'test');
    await getDoc(testDoc);
    return Promise.resolve();
  } catch (error) {
    console.error('Error de conexión con Firebase:', error);
    return Promise.reject(new Error('No se pudo conectar con el servidor. Verifica tu conexión a internet.'));
  }
};

// Verificar si hay usuario autenticado
export const isAuthenticated = () => {
  const token = localStorage.getItem(AUTH_TOKEN_KEY);
  const user = localStorage.getItem(USER_KEY);
  return !!(token && user);
};

// Obtener usuario actual
export const getCurrentUser = () => {
  const userStr = localStorage.getItem(USER_KEY);
  return userStr ? JSON.parse(userStr) : null;
};

// Login - Conecta con Firebase real (igual que tu app Android)
export const login = async (username, password) => {
  try {
    // Buscar usuario por ID (que ahora es el username) - igual que tu app Android
    const userDocRef = doc(db, 'users', username);
    const userDoc = await getDoc(userDocRef);

    if (!userDoc.exists()) {
      throw new Error('Usuario no encontrado');
    }

    const userData = userDoc.data();
    const storedPassword = userData.password || '';

    if (storedPassword !== password) {
      throw new Error('Contraseña incorrecta');
    }

    const user = {
      id: userDoc.id, // El ID es el username
      nombre: userData.nombre || '',
      username: userDoc.id, // El username es el ID del documento
      rol: userData.rol || '',
      localesAsignados: userData.localesAsignados || [],
      createdAt: userData.createdAt || Date.now()
    };

    const token = `token_${user.id}_${Date.now()}`;
    localStorage.setItem(AUTH_TOKEN_KEY, token);
    localStorage.setItem(USER_KEY, JSON.stringify(user));
    
    return user;
  } catch (error) {
    console.error('Error en login:', error);
    throw error;
  }
};

// Logout
export const logout = () => {
  localStorage.removeItem(AUTH_TOKEN_KEY);
  localStorage.removeItem(USER_KEY);
};

// Verificar token
export const verifyToken = async () => {
  const token = localStorage.getItem(AUTH_TOKEN_KEY);
  if (!token) {
    throw new Error('No hay token de autenticación');
  }
  
  // Simular verificación del token
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (token.startsWith('token_')) {
        resolve(true);
      } else {
        reject(new Error('Token inválido'));
      }
    }, 500);
  });
};
