// Servicio ULTRA SIMPLE para subir imágenes
// ✅ NO requiere API key, NO requiere autenticación, NO requiere servidor externo
// ✅ Guarda las imágenes directamente en Firestore como base64
// ⚠️ Límite: 1MB por imagen (Firestore tiene límite de 1MB por documento)

class ImageUploadService {
  // Subir imagen (convierte a base64 y retorna datos)
  async uploadImage(file, pendienteId) {
    try {
      // Validar archivo
      if (!file || !file.type.startsWith('image/')) {
        throw new Error('El archivo debe ser una imagen');
      }

      // Comprimir imagen si es necesaria para que quepa en Firestore (límite ~700KB para base64)
      let processedFile = file;
      if (file.size > 700 * 1024) {
        console.log(`⚠️ Imagen muy grande (${(file.size / 1024).toFixed(2)} KB), comprimiendo...`);
        processedFile = await this.compressImage(file, 700 * 1024);
        console.log(`✅ Imagen comprimida a ${(processedFile.size / 1024).toFixed(2)} KB`);
      }

      // Convertir a base64 (la forma más simple, sin servidor externo)
      return await this.uploadImageSimple(processedFile, pendienteId);

    } catch (error) {
      console.error('Error subiendo imagen:', error);
      throw error;
    }
  }

  // Comprimir imagen para que quepa en Firestore
  async compressImage(file, maxSizeBytes) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');

      img.onload = () => {
        let width = img.width;
        let height = img.height;
        let quality = 0.85;

        // Paso 1: Reducir dimensiones si es necesario (máximo 1920px)
        const maxDimension = 1920;
        if (width > maxDimension || height > maxDimension) {
          if (width > height) {
            height = (height * maxDimension) / width;
            width = maxDimension;
          } else {
            width = (width * maxDimension) / height;
            height = maxDimension;
          }
        }

        canvas.width = width;
        canvas.height = height;
        ctx.drawImage(img, 0, 0, width, height);

        // Paso 2: Comprimir iterativamente hasta que quepa
        const tryCompress = (q, currentWidth, currentHeight) => {
          // Si la calidad es muy baja y aún no cabe, reducir dimensiones
          if (q < 0.3 && (currentWidth > 1280 || currentHeight > 1280)) {
            const ratio = 1280 / Math.max(currentWidth, currentHeight);
            currentWidth = Math.floor(currentWidth * ratio);
            currentHeight = Math.floor(currentHeight * ratio);
            
            canvas.width = currentWidth;
            canvas.height = currentHeight;
            ctx.drawImage(img, 0, 0, currentWidth, currentHeight);
            q = 0.85; // Resetear calidad con nuevo tamaño
          }

          canvas.toBlob(
            (blob) => {
              if (!blob) {
                reject(new Error('Error al crear blob de imagen'));
                return;
              }

              if (blob.size <= maxSizeBytes || (q <= 0.1 && currentWidth <= 800)) {
                const compressedFile = new File([blob], file.name, {
                  type: 'image/jpeg', // Forzar JPEG para mejor compresión
                  lastModified: Date.now()
                });
                console.log(`✅ Compresión final: ${currentWidth}x${currentHeight}, calidad ${Math.round(q * 100)}%, tamaño ${(blob.size / 1024).toFixed(2)} KB`);
                resolve(compressedFile);
              } else {
                // Reducir calidad y reintentar
                tryCompress(q - 0.1, currentWidth, currentHeight);
              }
            },
            'image/jpeg', // Siempre usar JPEG para mejor compresión
            q
          );
        };

        tryCompress(quality, width, height);
      };

      img.onerror = (error) => {
        console.error('Error al cargar imagen:', error);
        reject(new Error('Error al cargar la imagen'));
      };
      
      img.src = URL.createObjectURL(file);
    });
  }

  // Método: Guardar como base64 en Firestore (más simple aún)
  async uploadImageSimple(file, pendienteId) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      
      reader.onload = async (e) => {
        try {
          const base64String = e.target.result;
          
          // Crear datos de la imagen
          const imageData = {
            id: `img_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
            name: file.name,
            url: base64String, // Data URL completo (listo para usar en <img src>)
            size: file.size,
            mimeType: file.type,
            pendienteId: pendienteId,
            createdTime: new Date().toISOString(),
            // Thumbnail (versión más pequeña para rendimiento)
            thumbnailUrl: await this.createThumbnail(file, 200, 200),
          };

          resolve(imageData);
        } catch (error) {
          reject(error);
        }
      };

      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  // Crear thumbnail (opcional, para mejor rendimiento)
  async createThumbnail(file, maxWidth, maxHeight) {
    return new Promise((resolve) => {
      const img = new Image();
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');

      img.onload = () => {
        // Calcular dimensiones manteniendo proporción
        let width = img.width;
        let height = img.height;

        if (width > height) {
          if (width > maxWidth) {
            height = (height * maxWidth) / width;
            width = maxWidth;
          }
        } else {
          if (height > maxHeight) {
            width = (width * maxHeight) / height;
            height = maxHeight;
          }
        }

        canvas.width = width;
        canvas.height = height;
        ctx.drawImage(img, 0, 0, width, height);

        const thumbnailUrl = canvas.toDataURL('image/jpeg', 0.7);
        resolve(thumbnailUrl);
      };

      img.onerror = () => resolve(null);
      img.src = URL.createObjectURL(file);
    });
  }

  // Eliminar imagen (no hay servidor, solo devuelve true)
  async deleteImage(imageId) {
    // Las imágenes están en Firestore, se eliminan junto con la observación
    return true;
  }

  // Verificar si está configurado (siempre true, no necesita configuración)
  isConfigured() {
    return true; // No requiere configuración externa
  }
}

export default new ImageUploadService();
