// Repositorio de Gastos - Conecta con Firebase real (igual que la app Android)
import { db } from '../services/firebase';
import { collection, doc, getDoc, setDoc, updateDoc, deleteDoc, getDocs, query, where, orderBy, addDoc } from 'firebase/firestore';
import { onSnapshot } from 'firebase/firestore';
import Gasto from '../models/Gasto';
import LocalRepository from './LocalRepository';

class GastoRepository {
  // Crear gasto (igual que la app Android)
  async createGasto(gasto) {
    try {
      // Si es un objeto plano, usarlo directamente; si tiene toMap, convertirlo
      const gastoData = typeof gasto.toMap === 'function' 
        ? gasto.toMap() 
        : gasto;
      
      const gastosCollection = collection(db, 'gastos');
      const docRef = await addDoc(gastosCollection, gastoData);
      
      // Actualizar estado del local
      await LocalRepository.updateLocalEstado(gastoData.localId);
      
      return { success: true, id: docRef.id };
    } catch (error) {
      console.error('Error creando gasto:', error);
      return { success: false, error: error.message };
    }
  }

  // Actualizar estado del gasto (igual que la app Android)
  async updateEstado(gastoId, estado, observaciones = '') {
    try {
      const gastoDocRef = doc(db, 'gastos', gastoId);
      await updateDoc(gastoDocRef, {
        estado: estado,
        observaciones: observaciones,
        updatedAt: Date.now()
      });
      
      // Actualizar estado del local
      const gasto = await this.getGastoById(gastoId);
      if (gasto.success) {
        await LocalRepository.updateLocalEstado(gasto.gasto.localId);
      }
      
      return { success: true };
    } catch (error) {
      console.error('Error actualizando estado:', error);
      return { success: false, error: error.message };
    }
  }

  // Eliminar gasto (igual que la app Android)
  async deleteGasto(gastoId) {
    try {
      // Obtener el gasto antes de eliminarlo para actualizar el estado del local
      const gasto = await this.getGastoById(gastoId);
      
      const gastoDocRef = doc(db, 'gastos', gastoId);
      await deleteDoc(gastoDocRef);
      
      // Actualizar estado del local si existe
      if (gasto.success) {
        await LocalRepository.updateLocalEstado(gasto.gasto.localId);
      }
      
      return { success: true };
    } catch (error) {
      console.error('Error eliminando gasto:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener gasto por ID (igual que la app Android)
  async getGastoById(gastoId) {
    try {
      const gastoDocRef = doc(db, 'gastos', gastoId);
      const gastoDoc = await getDoc(gastoDocRef);

      if (!gastoDoc.exists()) {
        return { success: false, error: 'Gasto no encontrado' };
      }

      const gastoData = gastoDoc.data();
      const gasto = Gasto.fromMap({ ...gastoData, id: gastoDoc.id });
      return { success: true, gasto };
    } catch (error) {
      console.error('Error obteniendo gasto:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener todos los gastos (igual que la app Android)
  getAllGastos() {
    return new Promise((resolve, reject) => {
      const gastosCollection = collection(db, 'gastos');
      const q = query(gastosCollection, orderBy('createdAt', 'desc'));
      
      const unsubscribe = onSnapshot(q, (snapshot) => {
        const gastos = [];
        snapshot.forEach(doc => {
          const gastoData = doc.data();
          const gasto = Gasto.fromMap({ ...gastoData, id: doc.id });
          gastos.push(gasto);
        });
        resolve(gastos);
      }, (error) => {
        console.error('Error obteniendo gastos:', error);
        reject(error);
      });

      return unsubscribe;
    });
  }

  // Suscribirse a todos los gastos en tiempo real (igual que la app Android)
  subscribeToGastos(callback) {
    const gastosCollection = collection(db, 'gastos');
    const q = query(gastosCollection, orderBy('createdAt', 'desc'));
    
    return onSnapshot(q, (snapshot) => {
      const gastos = [];
      snapshot.forEach(doc => {
        const gastoData = doc.data();
        const gasto = Gasto.fromMap({ ...gastoData, id: doc.id });
        gastos.push(gasto);
      });
      callback(gastos);
    }, (error) => {
      console.error('Error suscribiéndose a gastos:', error);
    });
  }

  // Obtener gastos por local (igual que la app Android)
  getGastosByLocal(localId) {
    return new Promise((resolve, reject) => {
      const gastosCollection = collection(db, 'gastos');
      const q = query(
        gastosCollection,
        where('localId', '==', localId),
        orderBy('createdAt', 'desc')
      );
      
      const unsubscribe = onSnapshot(q, (snapshot) => {
        const gastos = [];
        snapshot.forEach(doc => {
          const gastoData = doc.data();
          const gasto = Gasto.fromMap({ ...gastoData, id: doc.id });
          gastos.push(gasto);
        });
        resolve(gastos);
      }, (error) => {
        console.error('Error obteniendo gastos por local:', error);
        reject(error);
      });

      return unsubscribe;
    });
  }

  // Suscribirse a gastos por local en tiempo real (igual que la app Android)
  subscribeToGastosByLocal(localId, callback) {
    const gastosCollection = collection(db, 'gastos');
    const q = query(
      gastosCollection,
      where('localId', '==', localId),
      orderBy('createdAt', 'desc')
    );
    
    return onSnapshot(q, (snapshot) => {
      const gastos = [];
      snapshot.forEach(doc => {
        const gastoData = doc.data();
        const gasto = Gasto.fromMap({ ...gastoData, id: doc.id });
        gastos.push(gasto);
      });
      callback(gastos);
    }, (error) => {
      console.error('Error suscribiéndose a gastos por local:', error);
    });
  }
}

export default new GastoRepository();