import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import { CssBaseline, Box, CircularProgress, Alert } from '@mui/material';
import LoginScreen from './components/Login/LoginScreen';
import MaestroDashboard from './components/Dashboard/MaestroDashboard';
import SupervisorDashboard from './components/Dashboard/SupervisorDashboard';
import { getCurrentUser, isAuthenticated } from './services/auth';
import { initializeFirebase } from './services/firebase';

// Tema personalizado idéntico a la app Android
const theme = createTheme({
  palette: {
    primary: {
      main: '#1976d2',
      light: '#42a5f5',
      dark: '#1565c0',
    },
    secondary: {
      main: '#dc004e',
      light: '#ff5983',
      dark: '#9a0036',
    },
    background: {
      default: '#f5f5f5',
      paper: '#ffffff',
    },
    error: {
      main: '#d32f2f',
    },
    warning: {
      main: '#ed6c02',
    },
    success: {
      main: '#2e7d32',
    },
  },
  typography: {
    fontFamily: '"Roboto", "Helvetica", "Arial", sans-serif',
    h4: {
      fontWeight: 600,
    },
    h6: {
      fontWeight: 500,
    },
  },
  components: {
    MuiCard: {
      styleOverrides: {
        root: {
          borderRadius: 12,
          boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
        },
      },
    },
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: 8,
          textTransform: 'none',
          fontWeight: 500,
        },
      },
    },
  },
});

function App() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const initializeApp = async () => {
      try {
        // Inicializar Firebase
        await initializeFirebase();
        
        // Verificar si hay usuario autenticado
        if (isAuthenticated()) {
          const currentUser = getCurrentUser();
          setUser(currentUser);
        }
      } catch (err) {
        console.error('Error inicializando la aplicación:', err);
        setError('Error al conectar con el servidor. Verifica tu conexión a internet.');
      } finally {
        setLoading(false);
      }
    };

    initializeApp();
  }, []);

  const handleLogin = (userData) => {
    setUser(userData);
    setError(null);
  };

  const handleLogout = () => {
    setUser(null);
    // Limpiar datos locales
    localStorage.removeItem('user');
    localStorage.removeItem('authToken');
  };

  if (loading) {
    return (
      <ThemeProvider theme={theme}>
        <CssBaseline />
        <Box
          sx={{
            minHeight: '100vh',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
          }}
        >
          <Box sx={{ textAlign: 'center', color: 'white' }}>
            <CircularProgress size={60} sx={{ color: 'white', mb: 2 }} />
            <Box sx={{ fontSize: '1.2rem', fontWeight: 500 }}>
              Conectando con el servidor...
            </Box>
          </Box>
        </Box>
      </ThemeProvider>
    );
  }

  if (error) {
    return (
      <ThemeProvider theme={theme}>
        <CssBaseline />
        <Box
          sx={{
            minHeight: '100vh',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            p: 3,
          }}
        >
          <Box sx={{ maxWidth: 500, width: '100%' }}>
            <Alert 
              severity="error" 
              sx={{ 
                borderRadius: 3,
                '& .MuiAlert-message': { fontSize: '1.1rem' }
              }}
            >
              <Box sx={{ fontWeight: 600, mb: 1 }}>
                ⚠️ Error de Conexión
              </Box>
              {error}
              <Box sx={{ mt: 2 }}>
                <button 
                  onClick={() => window.location.reload()}
                  style={{
                    background: '#d32f2f',
                    color: 'white',
                    border: 'none',
                    padding: '8px 16px',
                    borderRadius: '6px',
                    cursor: 'pointer',
                    fontWeight: 500,
                  }}
                >
                  🔄 Reintentar Conexión
                </button>
              </Box>
            </Alert>
          </Box>
        </Box>
      </ThemeProvider>
    );
  }

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Router>
        <Routes>
          {/* Rutas principales */}
          <Route path="/*" element={
            !user ? (
              <LoginScreen onLogin={handleLogin} />
            ) : (
              user.rol === 'MAESTRO' || user.rol === 'maestro' ? (
                <MaestroDashboard user={user} onLogout={handleLogout} />
              ) : (
                <SupervisorDashboard user={user} onLogout={handleLogout} />
              )
            )
          } />
        </Routes>
      </Router>
    </ThemeProvider>
  );
}

export default App;