import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CardActions,
  Button,
  Grid,
  Chip,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  CircularProgress,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Checkbox,
  Tabs,
  Tab,
} from '@mui/material';
import {
  CheckCircle,
  RadioButtonUnchecked,
  CalendarToday,
  Person,
  EventAvailable,
} from '@mui/icons-material';
import AgendaRepository from '../../repositories/AgendaRepository';
import UserRepository from '../../repositories/UserRepository';

// Funciones auxiliares para manejar fechas correctamente (sin zona horaria)
const obtenerComponentesFecha = (timestamp) => {
  const fecha = new Date(timestamp);
  // Obtener componentes usando UTC para evitar problemas de zona horaria
  return {
    año: fecha.getUTCFullYear(),
    mes: fecha.getUTCMonth(),
    dia: fecha.getUTCDate()
  };
};

const normalizarFecha = (timestamp) => {
  const comp = obtenerComponentesFecha(timestamp);
  // Crear fecha en UTC a las 00:00:00
  return new Date(Date.UTC(comp.año, comp.mes, comp.dia));
};

const formatearFecha = (timestamp) => {
  const comp = obtenerComponentesFecha(timestamp);
  const dia = String(comp.dia).padStart(2, '0');
  const mes = String(comp.mes + 1).padStart(2, '0');
  return `${dia}/${mes}/${comp.año}`;
};

const AgendaTab = ({ user }) => {
  const [actividades, setActividades] = useState([]);
  const [supervisores, setSupervisores] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedSupervisorId, setSelectedSupervisorId] = useState('');
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [viewMode, setViewMode] = useState('calendar'); // 'calendar' o 'list'

  useEffect(() => {
    setLoading(true);

    // Suscribirse a todas las actividades
    const unsubscribeActividades = AgendaRepository.subscribeToTodasActividades((actividades) => {
      console.log('Actividades de agenda recibidas:', actividades);
      setActividades(actividades);
      setLoading(false);
    });

    // Suscribirse a supervisores en tiempo real
    const unsubscribeSupervisores = UserRepository.subscribeToSupervisors((supervisores) => {
      console.log('Supervisores recibidos en AgendaTab:', supervisores);
      setSupervisores(supervisores);
    });

    return () => {
      unsubscribeActividades();
      unsubscribeSupervisores();
    };
  }, []);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Cargando agendas...</Typography>
      </Box>
    );
  }

  // Si no hay supervisor seleccionado, mostrar lista de supervisores
  if (!selectedSupervisorId) {
    console.log('Renderizando SupervisoresList con:', supervisores.length, 'supervisores');
    return (
      <SupervisoresList
        supervisores={supervisores}
        actividades={actividades}
        onSelectSupervisor={setSelectedSupervisorId}
      />
    );
  }

  // Si hay supervisor seleccionado, mostrar su agenda completa
  const actividadesSupervisor = actividades.filter(a => a.supervisorId === selectedSupervisorId);
  const supervisor = supervisores.find(s => s.id === selectedSupervisorId);

  return (
    <Box sx={{ p: 2 }}>
      {/* Header con botón para volver */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Box>
          <Button 
            startIcon={<Person />} 
            onClick={() => setSelectedSupervisorId('')}
            sx={{ mb: 1 }}
          >
            ← Volver a supervisores
          </Button>
          <Typography variant="h5" sx={{ fontWeight: 600 }}>
            Agenda de {supervisor?.nombre || 'Supervisor'}
          </Typography>
        </Box>
        <Box>
          <Button
            variant={viewMode === 'calendar' ? 'contained' : 'outlined'}
            startIcon={<CalendarToday />}
            onClick={() => setViewMode('calendar')}
            sx={{ mr: 1 }}
            size="small"
          >
            Calendario
          </Button>
          <Button
            variant={viewMode === 'list' ? 'contained' : 'outlined'}
            startIcon={<EventAvailable />}
            onClick={() => setViewMode('list')}
            size="small"
          >
            Lista
          </Button>
        </Box>
      </Box>

      {/* Estadísticas */}
      <Grid container spacing={2} sx={{ mb: 3 }}>
        <Grid item xs={4}>
          <Card sx={{ bgcolor: 'primary.light' }}>
            <CardContent>
              <Typography variant="h4" color="primary.contrastText">
                {actividadesSupervisor.filter(a => !a.completada).length}
              </Typography>
              <Typography variant="body2" color="primary.contrastText">Pendientes</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={4}>
          <Card sx={{ bgcolor: 'success.light' }}>
            <CardContent>
              <Typography variant="h4" color="success.contrastText">
                {actividadesSupervisor.filter(a => a.completada).length}
              </Typography>
              <Typography variant="body2" color="success.contrastText">Completadas</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={4}>
          <Card sx={{ bgcolor: 'info.light' }}>
            <CardContent>
              <Typography variant="h4" color="info.contrastText">{actividadesSupervisor.length}</Typography>
              <Typography variant="body2" color="info.contrastText">Total</Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Vista de calendario o lista */}
      {viewMode === 'calendar' ? (
        <CalendarioVistaReadOnly
          selectedDate={selectedDate}
          onDateChange={setSelectedDate}
          actividades={actividadesSupervisor}
        />
      ) : (
        <ActividadesSupervisorVista actividades={actividadesSupervisor} />
      )}
    </Box>
  );
};

const SupervisoresList = ({ supervisores, actividades, onSelectSupervisor }) => {
  console.log('SupervisoresList - supervisores:', supervisores);
  console.log('SupervisoresList - cantidad:', supervisores?.length);
  
  // Calcular estadísticas por supervisor
  const getEstadisticasSupervisor = (supId) => {
    const acts = actividades.filter(a => a.supervisorId === supId);
    return {
      total: acts.length,
      pendientes: acts.filter(a => !a.completada).length,
      completadas: acts.filter(a => a.completada).length
    };
  };

  return (
    <Box sx={{ p: 2 }}>
      <Typography variant="h5" sx={{ fontWeight: 600, mb: 3 }}>
        Selecciona un Supervisor
      </Typography>

      {supervisores.length === 0 && (
        <Typography color="text.secondary" sx={{ textAlign: 'center', py: 4 }}>
          No hay supervisores disponibles
        </Typography>
      )}

      <Grid container spacing={2}>
        {supervisores.map(sup => {
          const stats = getEstadisticasSupervisor(sup.id);
          return (
            <Grid item xs={12} sm={6} md={4} key={sup.id}>
              <Card 
                sx={{ 
                  cursor: 'pointer',
                  '&:hover': { 
                    boxShadow: 6,
                    transform: 'scale(1.02)',
                    transition: 'all 0.2s'
                  },
                  height: '100%'
                }}
                onClick={() => onSelectSupervisor(sup.id)}
              >
                <CardContent>
                  <Typography variant="h6" sx={{ mb: 2, display: 'flex', alignItems: 'center' }}>
                    <Person sx={{ mr: 1, color: 'primary.main' }} />
                    {sup.nombre}
                  </Typography>
                  
                  <Grid container spacing={1} sx={{ mb: 2 }}>
                    <Grid item xs={6}>
                      <Box sx={{ textAlign: 'center', p: 1.5, bgcolor: 'primary.light', borderRadius: 1 }}>
                        <Typography variant="h4" color="primary.contrastText">{stats.pendientes}</Typography>
                        <Typography variant="caption" color="primary.contrastText">Pendientes</Typography>
                      </Box>
                    </Grid>
                    <Grid item xs={6}>
                      <Box sx={{ textAlign: 'center', p: 1.5, bgcolor: 'success.light', borderRadius: 1 }}>
                        <Typography variant="h4" color="success.contrastText">{stats.completadas}</Typography>
                        <Typography variant="caption" color="success.contrastText">Completadas</Typography>
                      </Box>
                    </Grid>
                  </Grid>

                  <Typography variant="body2" color="text.secondary" align="center">
                    Total: {stats.total} actividades
                  </Typography>
                </CardContent>
                <CardActions>
                  <Button 
                    fullWidth 
                    endIcon={<CalendarToday />}
                    onClick={() => onSelectSupervisor(sup.id)}
                  >
                    Ver Agenda
                  </Button>
                </CardActions>
              </Card>
            </Grid>
          );
        })}
      </Grid>
    </Box>
  );
};

const CalendarioVistaReadOnly = ({ selectedDate, onDateChange, actividades }) => {
  const año = selectedDate.getFullYear();
  const mes = selectedDate.getMonth();
  
  const primerDia = new Date(año, mes, 1);
  const ultimoDia = new Date(año, mes + 1, 0);
  const diasEnMes = ultimoDia.getDate();
  const diaSemanaInicio = primerDia.getDay();
  
  const meses = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 
                 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];

  const cambiarMes = (delta) => {
    const nuevaFecha = new Date(año, mes + delta, 1);
    onDateChange(nuevaFecha);
  };

  const getActividadesDelDia = (dia) => {
    return actividades.filter(act => {
      const actComp = obtenerComponentesFecha(act.fecha);
      return actComp.año === año &&
             actComp.mes === mes &&
             actComp.dia === dia;
    });
  };

  return (
    <Box>
      {/* Navegación de mes */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Button onClick={() => cambiarMes(-1)}>{"<"}</Button>
        <Typography variant="h6">{meses[mes]} {año}</Typography>
        <Button onClick={() => cambiarMes(1)}>{">"}</Button>
      </Box>

      {/* Calendario */}
      <Card>
        <CardContent>
          <Grid container spacing={1}>
            {['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'].map(dia => (
              <Grid item xs={12/7} key={dia}>
                <Typography variant="caption" align="center" display="block" fontWeight="bold">
                  {dia}
                </Typography>
              </Grid>
            ))}
            
            {Array.from({ length: diaSemanaInicio }).map((_, i) => (
              <Grid item xs={12/7} key={`empty-${i}`}>
                <Box sx={{ height: 80 }} />
              </Grid>
            ))}
            
            {Array.from({ length: diasEnMes }).map((_, i) => {
              const dia = i + 1;
              const actividadesDia = getActividadesDelDia(dia);
              const hoy = normalizarFecha(new Date());
              const fechaDia = normalizarFecha(new Date(año, mes, dia));
              const esHoy = hoy.getTime() === fechaDia.getTime();
              
              return (
                <Grid item xs={12/7} key={dia}>
                  <Card 
                    variant="outlined"
                    sx={{ 
                      height: 80, 
                      cursor: 'pointer',
                      bgcolor: esHoy ? 'info.light' : 'background.paper',
                      '&:hover': { bgcolor: esHoy ? 'info.main' : 'action.hover' }
                    }}
                    onClick={() => onDateChange(new Date(año, mes, dia))}
                  >
                    <CardContent sx={{ p: 1, '&:last-child': { pb: 1 } }}>
                      <Typography variant="body2" color={esHoy ? 'info.contrastText' : 'text.primary'}>
                        {dia}
                      </Typography>
                      {actividadesDia.length > 0 && (
                        <Box sx={{ mt: 0.5 }}>
                          {actividadesDia.slice(0, 2).map(act => (
                            <Typography 
                              key={act.id} 
                              variant="caption" 
                              display="block"
                              sx={{ 
                                textDecoration: act.completada ? 'line-through' : 'none',
                                opacity: act.completada ? 0.6 : 1,
                                color: esHoy ? 'info.contrastText' : 'text.secondary',
                                overflow: 'hidden',
                                textOverflow: 'ellipsis',
                                whiteSpace: 'nowrap'
                              }}
                            >
                              {act.completada ? '✓' : '•'} {act.titulo}
                            </Typography>
                          ))}
                          {actividadesDia.length > 2 && (
                            <Typography variant="caption" color={esHoy ? 'info.contrastText' : 'text.secondary'}>
                              +{actividadesDia.length - 2}
                            </Typography>
                          )}
                        </Box>
                      )}
                    </CardContent>
                  </Card>
                </Grid>
              );
            })}
          </Grid>
        </CardContent>
      </Card>

      {/* Actividades del día seleccionado */}
      <Box sx={{ mt: 3 }}>
        <Typography variant="h6" sx={{ mb: 2 }}>
          Actividades del {formatearFecha(selectedDate.getTime())}
        </Typography>
        
        {getActividadesDelDia(selectedDate.getDate()).length === 0 ? (
          <Card>
            <CardContent sx={{ textAlign: 'center', py: 3 }}>
              <Typography color="text.secondary">
                Sin actividades este día
              </Typography>
            </CardContent>
          </Card>
        ) : (
          <List>
            {getActividadesDelDia(selectedDate.getDate()).map(act => (
              <Card key={act.id} sx={{ mb: 1 }}>
                <ListItem>
                  <ListItemIcon>
                    {act.completada ? (
                      <CheckCircle color="success" />
                    ) : (
                      <RadioButtonUnchecked />
                    )}
                  </ListItemIcon>
                  <ListItemText
                    primary={act.titulo}
                    secondary={act.descripcion}
                    sx={{
                      textDecoration: act.completada ? 'line-through' : 'none',
                      opacity: act.completada ? 0.7 : 1
                    }}
                  />
                </ListItem>
              </Card>
            ))}
          </List>
        )}
      </Box>
    </Box>
  );
};

const ActividadesSupervisorVista = ({ actividades }) => {
  const [tab, setTab] = useState(0);
  
  const hoy = normalizarFecha(Date.now());
  
  const actividadesHoy = actividades.filter(a => {
    const fecha = normalizarFecha(a.fecha);
    return fecha.getTime() === hoy.getTime() && !a.completada;
  });
  
  const actividadesProximas = actividades.filter(a => {
    const fecha = normalizarFecha(a.fecha);
    return fecha.getTime() > hoy.getTime() && !a.completada;
  });
  
  const actividadesCompletadas = actividades.filter(a => a.completada);

  const renderLista = (lista, titulo) => (
    <Box>
      <Typography variant="h6" sx={{ mb: 2 }}>{titulo}</Typography>
      {lista.length === 0 ? (
        <Typography color="text.secondary" sx={{ ml: 2 }}>Sin actividades</Typography>
      ) : (
        <List>
          {lista.map(act => (
            <Card key={act.id} sx={{ mb: 1 }}>
              <ListItem>
                <ListItemIcon>
                  {act.completada ? (
                    <CheckCircle color="success" />
                  ) : (
                    <RadioButtonUnchecked />
                  )}
                </ListItemIcon>
                <ListItemText
                  primary={act.titulo}
                  secondary={
                    <>
                      {act.descripcion}
                      <br />
                      <Chip 
                        label={formatearFecha(act.fecha)} 
                        size="small" 
                        icon={<CalendarToday fontSize="small" />}
                        sx={{ mt: 0.5 }}
                      />
                    </>
                  }
                  sx={{
                    textDecoration: act.completada ? 'line-through' : 'none',
                    opacity: act.completada ? 0.7 : 1
                  }}
                />
              </ListItem>
            </Card>
          ))}
        </List>
      )}
    </Box>
  );

  return (
    <Box>
      <Tabs value={tab} onChange={(e, v) => setTab(v)} sx={{ mb: 2 }}>
        <Tab label={`Hoy (${actividadesHoy.length})`} />
        <Tab label={`Próximas (${actividadesProximas.length})`} />
        <Tab label={`Completadas (${actividadesCompletadas.length})`} />
      </Tabs>

      {tab === 0 && renderLista(actividadesHoy, '📅 Para Hoy')}
      {tab === 1 && renderLista(actividadesProximas, '📆 Próximas Actividades')}
      {tab === 2 && renderLista(actividadesCompletadas, '✅ Actividades Completadas')}
    </Box>
  );
};

export default AgendaTab;

