import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CardActions,
  Button,
  IconButton,
  Fab,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Grid,
  Avatar,
  Chip,
  List,
  ListItem,
  ListItemText,
  ListItemAvatar,
  Divider,
} from '@mui/material';
import {
  Add,
  Edit,
  Delete,
  LocationOn,
  Person,
  ArrowBack,
  SupervisorAccount,
} from '@mui/icons-material';
import LocalRepository from '../../repositories/LocalRepository';
import UserRepository from '../../repositories/UserRepository';
import LocalDetailScreen from '../LocalDetail/LocalDetailScreen';

const LocalesTab = ({ user }) => {
  const [locales, setLocales] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [selectedSupervisor, setSelectedSupervisor] = useState(null);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [editingLocal, setEditingLocal] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedLocalId, setSelectedLocalId] = useState(null);

  // Cargar datos desde Firebase en tiempo real (igual que la app Android)
  useEffect(() => {
    setLoading(true);

    // Suscribirse a supervisores en tiempo real
    const unsubscribeSupervisors = UserRepository.subscribeToSupervisors((supervisors) => {
      console.log('Supervisores recibidos de Firebase:', supervisors);
      setSupervisors(supervisors);
    });

    // Suscribirse a locales en tiempo real
    const unsubscribeLocales = LocalRepository.subscribeToLocales((locales) => {
      console.log('Locales recibidos de Firebase:', locales);
      setLocales(locales);
    });

    setLoading(false);

    return () => {
      unsubscribeSupervisors();
      unsubscribeLocales();
    };
  }, []);

  const handleCreateLocal = async (formData) => {
    try {
      const localData = {
        nombre: formData.nombre,
        supervisorId: formData.supervisorId,
        supervisorNombre: formData.supervisorNombre,
        estado: 'activo',
        datosAdministrativos: {
          direccion: formData.direccion || '',
          telefono: formData.telefono || '',
        },
        createdAt: Date.now(),
        lastUpdate: Date.now()
      };

      const result = await LocalRepository.createLocal(localData);
      if (result.success) {
        setShowCreateDialog(false);
        // Los datos se actualizarán automáticamente por la suscripción en tiempo real
      } else {
        console.error('Error creando local:', result.error);
      }
    } catch (error) {
      console.error('Error creando local:', error);
    }
  };

  const handleEditLocal = (local) => {
    setEditingLocal(local);
  };

  const handleUpdateLocal = (formData) => {
    setLocales(prev => prev.map(l => 
      l.id === editingLocal.id ? { ...l, ...formData } : l
    ));
    setEditingLocal(null);
  };

  const localesDelSupervisor = selectedSupervisor 
    ? locales.filter(l => l.supervisorId === selectedSupervisor.id)
    : [];

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <Typography>Cargando locales...</Typography>
      </Box>
    );
  }

  // Mostrar pantalla de detalles del local si hay uno seleccionado
  if (selectedLocalId) {
    return (
      <LocalDetailScreen 
        localId={selectedLocalId} 
        onBack={() => setSelectedLocalId(null)} 
      />
    );
  }

  return (
    <Box sx={{ p: 2 }}>
      {!selectedSupervisor ? (
        // Vista de supervisores
        <Box>
          {/* Header */}
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
            <Typography variant="h5" sx={{ fontWeight: 600 }}>
              Supervisores
            </Typography>
            <Chip label={`${supervisors.length} total`} color="primary" />
          </Box>

          {/* Lista de supervisores */}
          <Grid container spacing={2}>
            {supervisors.map((supervisor) => (
              <Grid item xs={12} sm={6} md={4} key={supervisor.id}>
                <Card sx={{ '&:hover': { boxShadow: 4 }, cursor: 'pointer' }}
                      onClick={() => setSelectedSupervisor(supervisor)}>
                  <CardContent>
                    <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                      <Avatar sx={{ mr: 2, bgcolor: 'primary.main' }}>
                        <SupervisorAccount />
                      </Avatar>
                      <Box>
                        <Typography variant="h6" sx={{ fontWeight: 600 }}>
                          {supervisor.nombre}
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                          {supervisor.rol}
                        </Typography>
                      </Box>
                    </Box>
                    
                    <Box sx={{ mb: 2 }}>
                      <Typography variant="body2" color="text.secondary">
                        Usuario: {supervisor.username}
                      </Typography>
                    </Box>

                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <Chip
                        label={`${supervisor.localesAsignados?.length || 0} locales`}
                        color="primary"
                        size="small"
                      />
                      <Button size="small" variant="outlined">
                        Ver Locales
                      </Button>
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>
        </Box>
      ) : (
        // Vista de locales del supervisor
        <Box>
          {/* Header con botón de volver */}
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <IconButton onClick={() => setSelectedSupervisor(null)} sx={{ mr: 1 }}>
                <ArrowBack />
              </IconButton>
              <Box>
                <Typography variant="h5" sx={{ fontWeight: 600 }}>
                  {selectedSupervisor.nombre}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Locales asignados
                </Typography>
              </Box>
            </Box>
            
            <Fab
              color="primary"
              size="medium"
              onClick={() => setShowCreateDialog(true)}
            >
              <Add />
            </Fab>
          </Box>

          {/* Lista de locales del supervisor */}
          {localesDelSupervisor.length === 0 ? (
            <Card sx={{ textAlign: 'center', py: 4 }}>
              <CardContent>
                <Typography variant="h6" color="text.secondary">
                  No hay locales asignados a este supervisor
                </Typography>
                <Button
                  variant="contained"
                  startIcon={<Add />}
                  onClick={() => setShowCreateDialog(true)}
                  sx={{ mt: 2 }}
                >
                  Crear Primer Local
                </Button>
              </CardContent>
            </Card>
          ) : (
            <Grid container spacing={2}>
              {localesDelSupervisor.map((local) => (
                <Grid item xs={12} sm={6} md={4} key={local.id}>
                  <Card sx={{ '&:hover': { boxShadow: 4 } }}>
                    <CardContent>
                      <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                        <Avatar sx={{ mr: 2, bgcolor: 'secondary.main' }}>
                          <LocationOn />
                        </Avatar>
                        <Box sx={{ flexGrow: 1 }}>
                          <Typography variant="h6" sx={{ fontWeight: 600 }}>
                            {local.nombre}
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            {local.datosAdministrativos?.direccion || 'Sin dirección'}
                          </Typography>
                        </Box>
                      </Box>
                      
                      <Box sx={{ mb: 2 }}>
                        <Typography variant="body2" color="text.secondary">
                          📞 {local.datosAdministrativos?.telefono || 'Sin teléfono'}
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                          👤 {local.supervisorNombre}
                        </Typography>
                      </Box>

                      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <Chip
                          label={local.estado === 'activo' ? 'Activo' : 'Inactivo'}
                          color={local.estado === 'activo' ? 'success' : 'default'}
                          size="small"
                        />
                        <Typography variant="caption" color="text.secondary">
                          Creado: {new Date(local.createdAt).toLocaleDateString()}
                        </Typography>
                      </Box>
                    </CardContent>
                    <CardActions>
                      <Button
                        size="small"
                        onClick={() => setSelectedLocalId(local.id)}
                      >
                        Ver Detalles
                      </Button>
                      <Button
                        size="small"
                        startIcon={<Edit />}
                        onClick={() => handleEditLocal(local)}
                      >
                        Editar
                      </Button>
                      <Button
                        size="small"
                        color="error"
                        startIcon={<Delete />}
                      >
                        Eliminar
                      </Button>
                    </CardActions>
                  </Card>
                </Grid>
              ))}
            </Grid>
          )}
        </Box>
      )}

      {/* Dialog para crear/editar local */}
      <CreateEditLocalDialog
        open={showCreateDialog || !!editingLocal}
        onClose={() => {
          setShowCreateDialog(false);
          setEditingLocal(null);
        }}
        onSubmit={editingLocal ? handleUpdateLocal : handleCreateLocal}
        local={editingLocal}
        supervisors={supervisors}
        selectedSupervisor={selectedSupervisor}
      />
    </Box>
  );
};

// Componente para crear/editar local
const CreateEditLocalDialog = ({ open, onClose, onSubmit, local, supervisors, selectedSupervisor }) => {
  const [formData, setFormData] = useState({
    nombre: '',
    supervisorId: selectedSupervisor?.id || '',
    supervisorNombre: selectedSupervisor?.nombre || '',
    direccion: '',
    telefono: '',
  });

  React.useEffect(() => {
    if (local) {
      setFormData({
        nombre: local.nombre,
        supervisorId: local.supervisorId,
        supervisorNombre: local.supervisorNombre,
        direccion: local.direccion || '',
        telefono: local.telefono || '',
      });
    } else {
      setFormData({
        nombre: '',
        supervisorId: selectedSupervisor?.id || '',
        supervisorNombre: selectedSupervisor?.nombre || '',
        direccion: '',
        telefono: '',
      });
    }
  }, [local, selectedSupervisor]);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.nombre && formData.supervisorId) {
      const supervisor = supervisors.find(s => s.id === formData.supervisorId);
      onSubmit({
        ...formData,
        supervisorNombre: supervisor?.nombre || '',
      });
      
      setFormData({
        nombre: '',
        supervisorId: '',
        supervisorNombre: '',
        direccion: '',
        telefono: '',
      });
    }
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>
        {local ? 'Editar Local' : 'Crear Nuevo Local'}
      </DialogTitle>
      <form onSubmit={handleSubmit}>
        <DialogContent>
          <Grid container spacing={2}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Nombre del Local *"
                value={formData.nombre}
                onChange={(e) => setFormData(prev => ({ ...prev, nombre: e.target.value }))}
                required
              />
            </Grid>
            <Grid item xs={12}>
              <FormControl fullWidth>
                <InputLabel>Supervisor *</InputLabel>
                <Select
                  value={formData.supervisorId}
                  onChange={(e) => {
                    const supervisor = supervisors.find(s => s.id === e.target.value);
                    setFormData(prev => ({ 
                      ...prev, 
                      supervisorId: e.target.value,
                      supervisorNombre: supervisor?.nombre || ''
                    }));
                  }}
                  required
                >
                  <MenuItem value="">Seleccionar supervisor</MenuItem>
                  {supervisors.map(s => (
                    <MenuItem key={s.id} value={s.id}>{s.nombre}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Dirección"
                value={formData.direccion}
                onChange={(e) => setFormData(prev => ({ ...prev, direccion: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Teléfono"
                value={formData.telefono}
                onChange={(e) => setFormData(prev => ({ ...prev, telefono: e.target.value }))}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancelar</Button>
          <Button type="submit" variant="contained">
            {local ? 'Actualizar' : 'Crear'}
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  );
};

export default LocalesTab;
