// Modelo Local - Exactamente igual que la app Android
class Local {
  constructor({
    id = '',
    nombre = '',
    supervisorId = '',
    supervisorNombre = '',
    estado = 'activo',
    datosAdministrativos = {},
    createdAt = Date.now(),
    lastUpdate = Date.now()
  } = {}) {
    this.id = id;
    this.nombre = nombre;
    this.supervisorId = supervisorId;
    this.supervisorNombre = supervisorNombre;
    this.estado = estado;
    this.datosAdministrativos = datosAdministrativos;
    this.createdAt = createdAt;
    this.lastUpdate = lastUpdate;
  }

  toMap() {
    return {
      id: this.id,
      nombre: this.nombre,
      supervisorId: this.supervisorId,
      supervisorNombre: this.supervisorNombre,
      estado: this.estado,
      datosAdministrativos: this.datosAdministrativos,
      createdAt: this.createdAt,
      lastUpdate: this.lastUpdate
    };
  }

  static fromMap(map) {
    return new Local({
      id: map.id || '',
      nombre: map.nombre || '',
      supervisorId: map.supervisorId || '',
      supervisorNombre: map.supervisorNombre || '',
      estado: map.estado || 'activo',
      datosAdministrativos: map.datosAdministrativos || {},
      createdAt: map.createdAt || Date.now(),
      lastUpdate: map.lastUpdate || Date.now()
    });
  }
}

export default Local;