import React, { useState, useEffect, useMemo, useRef } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CardActions,
  Button,
  Chip,
  Fab,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Grid,
  CircularProgress,
  Divider,
  Switch,
  FormControlLabel,
  Menu,
  Fade,
  Grow,
  IconButton,
  useMediaQuery,
} from '@mui/material';
import { useTheme } from '@mui/material/styles';
import {
  Add,
  FilterList,
  Edit,
  Delete,
  Assignment,
  Schedule,
  Person,
  LocationOn,
  Warning,
  CheckCircle,
  Cancel,
  Chat,
  Send,
  AttachFile,
  Image,
  Close,
} from '@mui/icons-material';
import PendienteRepository from '../../repositories/PendienteRepository';
import LocalRepository from '../../repositories/LocalRepository';
import UserRepository from '../../repositories/UserRepository';
import { getCurrentUser } from '../../services/auth';
import { PendientesGridSkeleton } from '../Common/SkeletonComponents';
import AdvancedSearch from '../Common/AdvancedSearch';
import { exportPendientesReport } from '../../utils/exportUtils';
import useToast from '../../hooks/useToast';
import NotificationRepository from '../../repositories/NotificationRepository';
import Notification from '../../models/Notification';
import pushNotificationService from '../../services/pushNotifications';
import ImageUploadDialog from '../Common/ImageUploadDialog';
import ImageGallery from '../Common/ImageGallery';

const PendientesTab = ({ user }) => {
  const [pendientes, setPendientes] = useState([]);
  const [locales, setLocales] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [editingPendiente, setEditingPendiente] = useState(null);
  const [showFilterDialog, setShowFilterDialog] = useState(false);
  const [filterState, setFilterState] = useState({
    area: '',
    urgencia: '',
    estado: ''
  });
  const [showCompletedPendientes, setShowCompletedPendientes] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [searchFilters, setSearchFilters] = useState({});
  const [showImageUpload, setShowImageUpload] = useState(false);
  const [selectedPendienteForImages, setSelectedPendienteForImages] = useState(null);
  const [showImageDialog, setShowImageDialog] = useState(false);
  const [selectedImages, setSelectedImages] = useState([]);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const toast = useToast();
  const currentUser = getCurrentUser();

  // Cargar datos desde Firebase en tiempo real
  useEffect(() => {
    if (!user || !user.id) return;

    setLoading(true);

    let asignados = [];
    let creados = [];

    const updateCombinedPendientes = () => {
      // Combinar ambas listas y eliminar duplicados
      const combined = [...asignados, ...creados];
      const unique = combined.filter((pendiente, index, self) =>
        index === self.findIndex((p) => p.id === pendiente.id)
      );
      console.log('Pendientes combinados (asignados + creados):', unique);
      setPendientes(unique);
      setLoading(false);
    };

    // Suscribirse a pendientes asignados al supervisor (excluye los creados por él)
    const unsubscribeAsignados = PendienteRepository.subscribeToPendientesBySupervisor(user.id, (pendientes) => {
      console.log('Pendientes asignados recibidos de Firebase:', pendientes);
      asignados = pendientes;
      updateCombinedPendientes();
    });

    // Suscribirse a pendientes creados por el supervisor (incluye los que él creó)
    const unsubscribeCreados = PendienteRepository.subscribeToPendientesByCreadoPor(user.id, (pendientes) => {
      console.log('Pendientes creados por supervisor recibidos de Firebase:', pendientes);
      creados = pendientes;
      updateCombinedPendientes();
    });

    // Suscribirse a locales del supervisor en tiempo real
    const unsubscribeLocales = LocalRepository.subscribeToLocalesBySupervisor(user.id, (locales) => {
      console.log('Locales del supervisor recibidos de Firebase:', locales);
      setLocales(locales);
    });

    return () => {
      unsubscribeAsignados();
      unsubscribeCreados();
      unsubscribeLocales();
    };
  }, [user]);

  // Inicializar y suscribir push para el usuario
  useEffect(() => {
    (async () => {
      try {
        await pushNotificationService.initialize();
        if (currentUser?.id) {
          await pushNotificationService.subscribeUser(currentUser.id);
        }
      } catch (e) {
        console.warn('No se pudo suscribir a push:', e);
      }
    })();
  }, [currentUser?.id]);

  const handleCreatePendiente = async (formData) => {
    try {
      console.log('handleCreatePendiente - formData:', formData);
      console.log('handleCreatePendiente - locales disponibles:', locales);
      
      const local = locales.find(l => l.id === formData.localId);
      console.log('handleCreatePendiente - local encontrado:', local);

      // Obtener información del maestro para asignarle el pendiente
      const maestroResult = await UserRepository.getUserById('admin');
      const maestro = maestroResult.success ? maestroResult.user : null;

      // Si hay observación inicial, se convierte en la primera observación
      const observacionesIniciales = formData.observacionInicial ? [{
        id: `initial_${Date.now()}`,
        mensaje: formData.observacionInicial,
        enviadoPor: currentUser.id,
        enviadoPorNombre: currentUser.nombre,
        rol: "SUPERVISOR",
        timestamp: Date.now()
      }] : [];

      // Convertir fechaLimite correctamente a timestamp en zona horaria local
      let fechaLimiteTimestamp = 0;
      if (formData.fechaLimite) {
        const [year, month, day] = formData.fechaLimite.split('-').map(Number);
        const fecha = new Date(year, month - 1, day, 23, 59, 59, 999);
        fechaLimiteTimestamp = fecha.getTime();
      }

      const pendienteData = {
        localId: formData.localId,
        localNombre: local?.nombre || 'Desconocido',
        supervisorId: 'admin', // Asignado al maestro (como en la app Android)
        supervisorNombre: maestro?.nombre || 'Admin Maestro', // Nombre del maestro
        creadoPor: currentUser.id,
        creadoPorNombre: currentUser.nombre,
        descripcion: formData.descripcion,
        estado: "asignado",
        prioridad: "media",
        area: formData.area,
        urgencia: formData.urgencia === 'true',
        fechaLimite: fechaLimiteTimestamp,
        observaciones: observacionesIniciales,
        createdAt: Date.now(),
        updatedAt: Date.now()
      };

      console.log('handleCreatePendiente - pendienteData a enviar:', pendienteData);

      const result = await PendienteRepository.createPendiente(pendienteData);
      console.log('handleCreatePendiente - result:', result);
      
      if (result.success) {
        setShowCreateDialog(false);
        toast.showSuccess('Pendiente creado exitosamente');
      } else {
        console.error('Error creando pendiente:', result.error);
        toast.showError('Error al crear el pendiente');
      }
    } catch (error) {
      console.error('Error creando pendiente:', error);
      toast.showError('Error al crear el pendiente');
    }
  };

  const handleUpdatePendiente = async (id, formData) => {
    try {
      const result = await PendienteRepository.updatePendiente(id, {
        estado: formData.estado,
        updatedAt: Date.now()
      });
      if (result.success) {
        setEditingPendiente(null);
        toast.showSuccess('Pendiente actualizado exitosamente');
      } else {
        console.error('Error actualizando pendiente:', result.error);
        toast.showError('Error al actualizar el pendiente');
      }
    } catch (error) {
      console.error('Error actualizando pendiente:', error);
      toast.showError('Error al actualizar el pendiente');
    }
  };

  const handleDeletePendiente = async (id) => {
    try {
      const result = await PendienteRepository.deletePendiente(id);
      if (result.success) {
        toast.showSuccess('Pendiente eliminado exitosamente');
      } else {
        console.error('Error eliminando pendiente:', result.error);
        toast.showError('Error al eliminar el pendiente');
      }
    } catch (error) {
      console.error('Error eliminando pendiente:', error);
      toast.showError('Error al eliminar el pendiente');
    }
  };

  const handleAddObservation = async (pendienteId, message) => {
    try {
      const pendiente = pendientes.find(p => p.id === pendienteId);
      const result = await PendienteRepository.addObservation(pendienteId, {
        id: Date.now().toString(),
        enviadoPor: currentUser.id,
        enviadoPorNombre: currentUser.nombre,
        rol: currentUser.rol,
        timestamp: Date.now(),
        mensaje: message
      });
      if (result.success) {
        toast.showSuccess('Observación agregada exitosamente');

        // Crear notificación para el otro usuario (maestro en este flujo)
        // Usar ID único para evitar spam de notificaciones - solo UNA por pendiente
        if (pendiente) {
          const destinatarioId = pendiente.supervisorId || 'admin';
          // ID único: evita múltiples notificaciones del mismo pendiente al mismo usuario
          const notifId = `chat_mensaje_${pendiente.id}_${currentUser.id}_${destinatarioId}`;
          const notification = new Notification({
            id: notifId,
            userId: destinatarioId,
            tipo: 'chat_pendiente',
            titulo: 'Nuevo mensaje en pendiente',
            mensaje: `${currentUser.nombre} escribió en "${pendiente.descripcion}"`,
            referenceId: `${pendiente.id}_mensaje`,
            pendienteId: pendiente.id,
            localId: pendiente.localId,
            localNombre: pendiente.localNombre,
            categoria: 'chat_pendiente',
            createdAt: Date.now(),
            fechaCreacion: Date.now()
          });
          await NotificationRepository.createNotification(notification);

          if (pushNotificationService.isEnabled() && pushNotificationService.isNotificationTypeEnabled('pendientes')) {
            pushNotificationService.showCustomNotification('💬 Nuevo mensaje', `${pendiente.localNombre}: ${pendiente.descripcion}`);
          }
        }
      } else {
        console.error('Error añadiendo observación:', result.error);
        toast.showError('Error al agregar la observación');
      }
    } catch (error) {
      console.error('Error añadiendo observación:', error);
      toast.showError('Error al agregar la observación');
    }
  };

  const handleUpdateEstado = async (pendienteId, nuevoEstado) => {
    try {
      const result = await PendienteRepository.updatePendiente(pendienteId, {
        estado: nuevoEstado,
        updatedAt: Date.now()
      });
      if (result.success) {
        toast.showSuccess(`Estado actualizado a: ${nuevoEstado}`);
      } else {
        console.error('Error actualizando estado:', result.error);
        toast.showError('Error al actualizar el estado');
      }
    } catch (error) {
      console.error('Error actualizando estado:', error);
      toast.showError('Error al actualizar el estado');
    }
  };

  const handleSearch = (term, filters) => {
    setSearchTerm(term);
    setSearchFilters(filters);
  };

  const handleExport = (data) => {
    const timestamp = new Date().toISOString().split('T')[0];
    const filename = `pendientes_${timestamp}.csv`;
    exportPendientesReport(data, filename);
    toast.showSuccess(`Exportados ${data.length} pendientes`);
  };

  // Funciones para manejar imágenes
  const handleOpenImageUpload = (pendiente) => {
    setSelectedPendienteForImages(pendiente);
    setShowImageUpload(true);
  };

  const handleCloseImageUpload = () => {
    setShowImageUpload(false);
    setSelectedPendienteForImages(null);
  };

  const handleImageUploadComplete = async (uploadedImages) => {
    if (!selectedPendienteForImages) return;

    try {
      console.log('🔵 SUPERVISOR - Imágenes recibidas:', uploadedImages);
      
      // Agregar las imágenes como observación especial
      // No mostrar mensaje redundante, solo las imágenes
      const imageObservation = {
        id: Date.now().toString(),
        enviadoPor: currentUser.id,
        enviadoPorNombre: currentUser.nombre,
        rol: currentUser.rol,
        timestamp: Date.now(),
        mensaje: '',
        tipo: 'imagenes',
        imagenes: uploadedImages
      };

      console.log('🔵 SUPERVISOR - Observación a guardar:', imageObservation);
      const result = await PendienteRepository.addObservation(selectedPendienteForImages.id, imageObservation);
      
      if (result.success) {
        toast.showSuccess(`${uploadedImages.length} imagen(es) agregada(s) al chat`);
        handleCloseImageUpload();
      } else {
        console.error('Error agregando imágenes:', result.error);
        toast.showError('Error al agregar las imágenes al chat');
      }
    } catch (error) {
      console.error('Error agregando imágenes:', error);
      toast.showError('Error al agregar las imágenes al chat');
    }
  };

  const handleDeleteImage = async (pendienteId, imageId) => {
    try {
      // Encontrar la observación que contiene la imagen
      const pendiente = pendientes.find(p => p.id === pendienteId);
      if (!pendiente || !pendiente.observaciones) return;

      // Buscar la observación con la imagen
      const observationWithImage = pendiente.observaciones.find(obs => 
        obs.imagenes && obs.imagenes.some(img => img.id === imageId)
      );

      if (!observationWithImage) return;

      // Eliminar la imagen de la observación
      const updatedImages = observationWithImage.imagenes.filter(img => img.id !== imageId);
      
      if (updatedImages.length === 0) {
        // Si no quedan imágenes, eliminar toda la observación
        const result = await PendienteRepository.removeObservation(pendienteId, observationWithImage.id);
        if (result.success) {
          toast.showSuccess('Imagen eliminada correctamente');
        } else {
          toast.showError('Error eliminando imagen');
        }
      } else {
        // Actualizar la observación con las imágenes restantes
        const updatedObservation = {
          ...observationWithImage,
          imagenes: updatedImages,
          mensaje: ''
        };
        
        const result = await PendienteRepository.updateObservation(pendienteId, updatedObservation);
        if (result.success) {
          toast.showSuccess('Imagen eliminada correctamente');
        } else {
          toast.showError('Error eliminando imagen');
        }
      }
    } catch (error) {
      console.error('Error eliminando imagen:', error);
      toast.showError('Error eliminando imagen');
    }
  };

  const handleOpenImageDialog = (imagenes) => {
    setSelectedImages(imagenes);
    setShowImageDialog(true);
  };

  const getFilteredPendientes = useMemo(() => {
    let currentPendientes = pendientes;

    // Filtrar pendientes completados y cancelados si el switch está desactivado
    if (!showCompletedPendientes) {
      currentPendientes = currentPendientes.filter(p => p.estado !== 'realizado' && p.estado !== 'cancelado');
    }

    // Aplicar filtros del estado
    currentPendientes = currentPendientes.filter(pendiente => {
      const matchesArea = filterState.area === '' || pendiente.area === filterState.area;
      const matchesUrgencia = filterState.urgencia === '' || pendiente.urgencia.toString() === filterState.urgencia;
      const matchesEstado = filterState.estado === '' || pendiente.estado === filterState.estado;

      return matchesArea && matchesUrgencia && matchesEstado;
    });

    // Aplicar búsqueda de texto
    if (searchTerm) {
      const lowerSearchTerm = searchTerm.toLowerCase();
      currentPendientes = currentPendientes.filter(p => 
        p.descripcion.toLowerCase().includes(lowerSearchTerm) ||
        p.localNombre.toLowerCase().includes(lowerSearchTerm) ||
        p.area.toLowerCase().includes(lowerSearchTerm) ||
        (p.creadoPorNombre && p.creadoPorNombre.toLowerCase().includes(lowerSearchTerm)) ||
        (p.supervisorNombre && p.supervisorNombre.toLowerCase().includes(lowerSearchTerm))
      );
    }

    // Aplicar filtros de búsqueda avanzada
    Object.entries(searchFilters).forEach(([key, value]) => {
      if (value && value !== '') {
        currentPendientes = currentPendientes.filter(p => {
          const itemValue = p[key];
          
          if (typeof value === 'boolean') {
            return itemValue === value;
          }
          
          if (typeof value === 'string') {
            return itemValue?.toLowerCase().includes(value.toLowerCase());
          }
          
          return itemValue === value;
        });
      }
    });

    return currentPendientes.sort((a, b) => {
      // Sort by urgency (urgent first)
      if (a.urgencia && !b.urgencia) return -1;
      if (!a.urgencia && b.urgencia) return 1;

      // Then by creation date (newest first)
      return b.createdAt - a.createdAt;
    });
  }, [pendientes, filterState, showCompletedPendientes, searchTerm, searchFilters]);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Cargando pendientes...</Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ p: { xs: 1.5, sm: 2 } }}>
      {/* Header y Botones */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: { xs: 1.5, sm: 3 } }}>
        <Typography variant="h5" sx={{ fontWeight: 600, fontSize: { xs: '1.25rem', sm: '1.5rem' } }}>
          Mis Pendientes
        </Typography>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Button
            variant="outlined"
            size={isMobile ? 'small' : 'medium'}
            startIcon={<FilterList />}
            onClick={() => setShowFilterDialog(true)}
          >
            Filtros
          </Button>
          <Fab
            color="primary"
            size={isMobile ? 'small' : 'medium'}
            onClick={() => setShowCreateDialog(true)}
            sx={{ position: 'fixed', bottom: { xs: 88, sm: 16 }, right: 16 }}
          >
            <Add />
          </Fab>
        </Box>
      </Box>

      {/* Búsqueda Avanzada */}
      <AdvancedSearch
        items={pendientes}
        onSearch={handleSearch}
        onExport={handleExport}
        searchFields={['descripcion', 'localNombre', 'area', 'creadoPorNombre', 'supervisorNombre']}
        filterOptions={{
          estado: {
            label: 'Estado',
            options: [
              { value: 'asignado', label: 'Asignado' },
              { value: 'en_progreso', label: 'En Progreso' },
              { value: 'completado', label: 'Completado' },
              { value: 'cancelado', label: 'Cancelado' }
            ]
          },
          urgencia: {
            label: 'Urgencia',
            options: [
              { value: true, label: 'Urgente' },
              { value: false, label: 'Normal' }
            ]
          },
          area: {
            label: 'Área',
            options: [
              { value: 'administracion', label: 'Administración' },
              { value: 'mantenimiento', label: 'Mantenimiento' },
              { value: 'limpieza', label: 'Limpieza' },
              { value: 'seguridad', label: 'Seguridad' }
            ]
          }
        }}
        placeholder="Buscar pendientes..."
        showFilters={!isMobile}
        showExport={!isMobile}
      />

      {/* Filtros Activos */}
      <Box sx={{ mb: 2 }}>
        <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>Filtros activos:</Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          {filterState.area && (
            <Chip
              label={`Área: ${filterState.area}`}
              onDelete={() => setFilterState(prev => ({ ...prev, area: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {filterState.urgencia !== '' && (
            <Chip
              label={`Urgencia: ${filterState.urgencia === 'true' ? 'Sí' : 'No'}`}
              onDelete={() => setFilterState(prev => ({ ...prev, urgencia: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {filterState.estado && (
            <Chip
              label={`Estado: ${filterState.estado}`}
              onDelete={() => setFilterState(prev => ({ ...prev, estado: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {!filterState.area && filterState.urgencia === '' && !filterState.estado && (
            <Typography variant="body2" color="text.secondary">Ninguno</Typography>
          )}
        </Box>
      </Box>

      {/* Toggle para Pendientes Completados */}
      <FormControlLabel
        control={
          <Switch
            checked={showCompletedPendientes}
            onChange={(e) => setShowCompletedPendientes(e.target.checked)}
          />
        }
        label="Mostrar pendientes completados"
        sx={{ mb: 2 }}
      />

      {/* Lista de Pendientes */}
      {loading ? (
        <PendientesGridSkeleton count={6} />
      ) : getFilteredPendientes.length === 0 ? (
        <Fade in={true} timeout={500}>
          <Card sx={{ textAlign: 'center', py: 4 }}>
            <CardContent>
              <Typography variant="h6" color="text.secondary">
                No hay pendientes que coincidan con los filtros.
              </Typography>
              <Button
                variant="contained"
                startIcon={<Add />}
                onClick={() => setShowCreateDialog(true)}
                sx={{ mt: 2 }}
              >
                Crear Nuevo Pendiente
              </Button>
            </CardContent>
          </Card>
        </Fade>
      ) : (
        <Grid container spacing={{ xs: 1, sm: 2 }}>
          {getFilteredPendientes.map((pendiente, index) => (
            <Grid item xs={12} sm={6} md={4} key={pendiente.id}>
              <Grow in={true} timeout={300 + (index * 100)}>
                <div>
                  <PendienteCard
                    pendiente={pendiente}
                    onEdit={() => setEditingPendiente(pendiente)}
                    onDelete={() => handleDeletePendiente(pendiente.id)}
                    onAddObservation={handleAddObservation}
                    onUpdateEstado={handleUpdateEstado}
                    onOpenImageUpload={handleOpenImageUpload}
                    onDeleteImage={handleDeleteImage}
                    onOpenImageDialog={handleOpenImageDialog}
                    currentUser={currentUser}
                  />
                </div>
              </Grow>
            </Grid>
          ))}
        </Grid>
      )}

      {/* Dialog para Crear/Editar Pendiente */}
      <CreateEditPendienteDialog
        open={showCreateDialog || !!editingPendiente}
        onClose={() => {
          setShowCreateDialog(false);
          setEditingPendiente(null);
        }}
        onSubmit={editingPendiente ? (data) => handleUpdatePendiente(editingPendiente.id, data) : handleCreatePendiente}
        pendiente={editingPendiente}
        locales={locales}
        currentUser={currentUser}
      />

      {/* Dialog para Filtros */}
      <FilterPendientesDialog
        open={showFilterDialog}
        onClose={() => setShowFilterDialog(false)}
        filterState={filterState}
        onFilterChange={setFilterState}
      />

      {/* Diálogo de subida de imágenes */}
      <ImageUploadDialog
        open={showImageUpload}
        onClose={handleCloseImageUpload}
        onUploadComplete={handleImageUploadComplete}
        pendienteId={selectedPendienteForImages?.id}
        existingImages={selectedPendienteForImages?.observaciones?.flatMap(obs => obs.imagenes || []) || []}
      />

      {/* Diálogo para ver imágenes */}
      {showImageDialog && (
        <Dialog
          open={showImageDialog}
          onClose={() => setShowImageDialog(false)}
          maxWidth="md"
          fullWidth
        >
          <DialogTitle sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <Typography variant="h6">Imágenes</Typography>
            <IconButton onClick={() => setShowImageDialog(false)} size="small">
              <Close />
            </IconButton>
          </DialogTitle>
          <DialogContent>
            <ImageGallery 
              images={selectedImages}
              onDeleteImage={(imageId) => {
                // Buscar en qué observación está esta imagen para eliminarla
                const pendienteActual = pendientes.find(p => 
                  p.observaciones?.some(obs => 
                    obs.imagenes?.some(img => img.id === imageId)
                  )
                );
                if (pendienteActual) {
                  handleDeleteImage(pendienteActual.id, imageId);
                  // Remover de la lista actual
                  setSelectedImages(selectedImages.filter(img => img.id !== imageId));
                }
              }}
              pendienteId={''}
              canDelete={false}
            />
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setShowImageDialog(false)}>Cerrar</Button>
          </DialogActions>
        </Dialog>
      )}
    </Box>
  );
};

const PendienteCard = ({ pendiente, onEdit, onDelete, onAddObservation, onUpdateEstado, onOpenImageUpload, onDeleteImage, onOpenImageDialog, currentUser }) => {
  const [newObservation, setNewObservation] = useState('');
  const [anchorEl, setAnchorEl] = useState(null);
  const open = Boolean(anchorEl);
  const chatEndRef = useRef(null);
  const chatContainerRef = useRef(null);

  // Verificar si el pendiente fue creado por el supervisor actual
  const canEdit = pendiente.creadoPor === currentUser.id;

  const getEstadoLabel = (estado) => {
    switch (estado) {
      case 'asignado': return 'Asignado';
      case 'en_proceso': return 'En Proceso';
      case 'realizado': return 'Realizado';
      case 'cancelado': return 'Cancelado';
      default: return estado;
    }
  };

  const getEstadoColor = (estado) => {
    switch (estado) {
      case 'asignado': return 'secondary';
      case 'en_proceso': return 'info';
      case 'realizado': return 'success';
      case 'cancelado': return 'error';
      default: return 'default';
    }
  };

  const getStatusIcon = (estado) => {
    switch (estado) {
      case 'asignado': return <Warning fontSize="small" />;
      case 'en_proceso': return <Schedule fontSize="small" />;
      case 'realizado': return <CheckCircle fontSize="small" />;
      case 'cancelado': return <Cancel fontSize="small" />;
      default: return <Warning fontSize="small" />;
    }
  };

  const handleEstadoClick = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleEstadoClose = (nuevoEstado) => {
    setAnchorEl(null);
    if (nuevoEstado) {
      onUpdateEstado(pendiente.id, nuevoEstado);
    }
  };

  const handleAddObservationClick = () => {
    if (newObservation.trim()) {
      onAddObservation(pendiente.id, newObservation);
      setNewObservation('');
      // Hacer scroll al final después de agregar la observación
      setTimeout(() => {
        scrollToBottom();
      }, 100);
    }
  };

  const scrollToBottom = () => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
    }
  };

  // Auto-scroll cuando cambian las observaciones
  useEffect(() => {
    scrollToBottom();
  }, [pendiente.observaciones?.length]);

  // Determinar si el pendiente fue creado (no es una actualización)
  const isCreatedPendiente = pendiente.estado === 'asignado' &&
                             pendiente.createdAt &&
                             pendiente.updatedAt &&
                             pendiente.createdAt === pendiente.updatedAt;

  return (
    <Card sx={{ 
      '&:hover': { boxShadow: 4 }, 
      height: '100%', 
      display: 'flex', 
      flexDirection: 'column',
      borderRadius: { xs: 2, sm: 3 }
    }}>
      <CardContent sx={{ 
        flex: 1,
        display: 'flex',
        flexDirection: 'column',
        p: { xs: 2, sm: 3 },
        '&:last-child': { pb: { xs: 2, sm: 3 } }
      }}>
        {/* Título optimizado para móviles */}
        <Typography 
          variant="h6" 
          sx={{ 
            fontWeight: 600, 
            mb: { xs: 1.5, sm: 2 }, 
            fontSize: { xs: '1rem', sm: '1.2rem' },
            lineHeight: { xs: 1.3, sm: 1.4 }
          }}
        >
          {pendiente.descripcion}
        </Typography>

        <Box sx={{ 
          display: 'flex', 
          flexDirection: { xs: 'column', sm: 'row' },
          justifyContent: 'space-between', 
          alignItems: { xs: 'flex-start', sm: 'flex-start' }, 
          mb: 1,
          gap: { xs: 1, sm: 0 }
        }}>
          <Box sx={{ flex: 1 }}>
            <Typography 
              variant="body2" 
              color="text.secondary" 
              sx={{ 
                mb: 0.5,
                fontSize: { xs: '0.75rem', sm: '0.875rem' },
                display: 'flex',
                alignItems: 'center'
              }}
            >
              <LocationOn fontSize="small" sx={{ mr: 0.5 }} />
              {pendiente.localNombre}
            </Typography>
            <Typography 
              variant="body2" 
              color="text.secondary" 
              sx={{ 
                mb: 0.5,
                fontSize: { xs: '0.75rem', sm: '0.875rem' },
                display: 'flex',
                alignItems: 'center'
              }}
            >
              <Person fontSize="small" sx={{ mr: 0.5 }} />
              Creado por: {pendiente.creadoPorNombre || 'Desconocido'}
            </Typography>
            <Typography 
              variant="body2" 
              color="text.secondary" 
              sx={{ 
                mb: 0.5,
                fontSize: { xs: '0.75rem', sm: '0.875rem' },
                display: 'flex',
                alignItems: 'center'
              }}
            >
              <Person fontSize="small" sx={{ mr: 0.5 }} />
              Asignado a: {pendiente.supervisorNombre || 'Desconocido'}
            </Typography>
            <Typography 
              variant="body2" 
              color="text.secondary" 
              sx={{ 
                mb: 1,
                fontSize: { xs: '0.75rem', sm: '0.875rem' },
                display: 'flex',
                alignItems: 'center'
              }}
            >
              <Assignment fontSize="small" sx={{ mr: 0.5 }} />
              Área: {pendiente.area}
            </Typography>
            {pendiente.fechaLimite && (
              <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                <Schedule fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
                Límite: {new Date(pendiente.fechaLimite).toLocaleDateString()}
              </Typography>
            )}
          </Box>
          <Box sx={{ 
            display: 'flex', 
            flexDirection: { xs: 'row', sm: 'column' }, 
            alignItems: { xs: 'flex-start', sm: 'flex-end' }, 
            gap: { xs: 1, sm: 0.5 },
            flexWrap: { xs: 'wrap', sm: 'nowrap' }
          }}>
            <Chip
              label={getEstadoLabel(pendiente.estado)}
              color={getEstadoColor(pendiente.estado)}
              size="small"
              icon={getStatusIcon(pendiente.estado)}
              onClick={handleEstadoClick}
              sx={{ 
                cursor: 'pointer', 
                '&:hover': { opacity: 0.8 },
                fontSize: { xs: '0.65rem', sm: '0.75rem' },
                height: { xs: 24, sm: 28 }
              }}
              title="Clic para cambiar estado"
            />
            {pendiente.urgencia && (
              <Chip
                label="URGENTE"
                color="error"
                size="small"
                icon={<Warning fontSize="small" />}
                sx={{
                  fontSize: { xs: '0.65rem', sm: '0.75rem' },
                  height: { xs: 24, sm: 28 }
                }}
              />
            )}
          </Box>
        </Box>

        {/* Menú de estados */}
        <Menu
          anchorEl={anchorEl}
          open={open}
          onClose={() => handleEstadoClose(null)}
        >
          <MenuItem onClick={() => handleEstadoClose('asignado')}>
            Asignado
          </MenuItem>
          <MenuItem onClick={() => handleEstadoClose('en_proceso')}>
            En Proceso
          </MenuItem>
          <MenuItem onClick={() => handleEstadoClose('realizado')}>
            Realizado
          </MenuItem>
          <MenuItem onClick={() => handleEstadoClose('cancelado')}>
            Cancelado
          </MenuItem>
        </Menu>

        <Divider sx={{ my: 1 }} />

        {/* Chat de observaciones siempre visible */}
        <Box sx={{ mb: 1, flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
            <Chat fontSize="small" sx={{ mr: 0.5 }} />
            <Typography variant="body2" color="text.secondary">
              Chat ({pendiente.observaciones?.length || 0})
            </Typography>
          </Box>
          
          {pendiente.observaciones && pendiente.observaciones.length > 0 ? (
            <Box 
              ref={chatContainerRef}
              sx={{ 
                flex: 1,
                maxHeight: { xs: 250, sm: 350 }, 
                overflowY: 'auto', 
                p: { xs: 0.5, sm: 1 }, 
                bgcolor: 'grey.50', 
                borderRadius: 1, 
                mb: 1,
                minHeight: { xs: 200, sm: 300 }
              }}
            >
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: { xs: 0.5, sm: 1 } }}>
                {pendiente.observaciones.map((obs, index) => {
                  // Determinar si el mensaje es del usuario actual
                  const isCurrentUser = obs.enviadoPor === currentUser.id;
                  
                  return (
                    <Box
                      key={obs.id || index}
                      sx={{
                        display: 'flex',
                        justifyContent: isCurrentUser ? 'flex-end' : 'flex-start',
                        width: '100%',
                      }}
                    >
                      <Card
                        variant="outlined"
                        sx={{
                          maxWidth: { xs: '90%', sm: '85%' },
                          bgcolor: isCurrentUser ? 'primary.main' : 'background.paper',
                          color: isCurrentUser ? 'white' : 'text.primary',
                          p: { xs: 0.75, sm: 1 },
                          borderRadius: 2,
                          boxShadow: 1,
                        }}
                      >
                        <Box sx={{ 
                          display: 'flex', 
                          justifyContent: 'space-between', 
                          alignItems: 'center', 
                          mb: 0.5, 
                          gap: 1,
                          flexDirection: { xs: 'column', sm: 'row' }
                        }}>
                          <Typography 
                            variant="caption" 
                            sx={{ 
                              fontWeight: 'bold', 
                              fontSize: { xs: '0.65rem', sm: '0.7rem' }
                            }}
                          >
                            {obs.enviadoPorNombre}
                          </Typography>
                          <Typography 
                            variant="caption" 
                            sx={{ 
                              fontSize: { xs: '0.6rem', sm: '0.65rem' }, 
                              opacity: 0.8 
                            }}
                          >
                            {new Date(obs.timestamp).toLocaleDateString('es-AR', {
                              day: '2-digit',
                              month: '2-digit',
                              hour: '2-digit',
                              minute: '2-digit'
                            })}
                          </Typography>
                        </Box>
                        {/* Mostrar mensaje solo si NO es tipo imagen o si no hay imágenes */}
                        {obs.tipo !== 'imagenes' && (
                          <Typography 
                            variant="body2" 
                            sx={{ 
                              fontSize: { xs: '0.75rem', sm: '0.8rem' },
                              lineHeight: { xs: 1.3, sm: 1.4 }
                            }}
                          >
                            {obs.mensaje}
                          </Typography>
                        )}
                        
                        {/* Mostrar link clickeable para ver imágenes */}
                        {obs.imagenes && obs.imagenes.length > 0 && (
                          <Typography
                            variant="body2"
                            sx={{
                              color: 'primary.main',
                              cursor: 'pointer',
                              textDecoration: 'underline',
                              mt: obs.tipo !== 'imagenes' ? 1 : 0,
                              '&:hover': { color: 'primary.dark' },
                              fontSize: { xs: '0.75rem', sm: '0.8rem' }
                            }}
                            onClick={() => onOpenImageDialog(obs.imagenes)}
                          >
                            📷 Ver imagen{obs.imagenes.length > 1 ? 'es' : ''}
                          </Typography>
                        )}
                        {obs.tipo === 'imagenes' && (!obs.imagenes || obs.imagenes.length === 0) ? (
                          <Box sx={{ mt: 1, p: 1, bgcolor: 'warning.light', borderRadius: 1 }}>
                            <Typography variant="caption" color="text.secondary">
                              ⚠️ Imágenes no disponibles (DEBUG: tipo=imagenes pero imagenes={obs.imagenes ? obs.imagenes.length : 'null'})
                            </Typography>
                          </Box>
                        ) : null}
                      </Card>
                    </Box>
                  );
                })}
                <div ref={chatEndRef} />
              </Box>
            </Box>
          ) : (
            <Box sx={{ 
              flex: 1,
              p: 1, 
              bgcolor: 'grey.50', 
              borderRadius: 1, 
              mb: 1,
              minHeight: { xs: 200, sm: 300 },
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}>
              <Typography variant="caption" color="text.secondary" sx={{ fontStyle: 'italic' }}>
                No hay observaciones aún
              </Typography>
            </Box>
          )}
          
          {/* Input para añadir observación - Optimizado para móviles */}
          <Box sx={{ 
            display: 'flex', 
            gap: { xs: 0.5, sm: 0.5 },
            flexDirection: { xs: 'column', sm: 'row' }
          }}>
            <TextField
              fullWidth
              size="small"
              placeholder="Escribir observación..."
              value={newObservation}
              onChange={(e) => setNewObservation(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === 'Enter') {
                  handleAddObservationClick();
                }
              }}
              sx={{
                '& .MuiInputBase-input': {
                  fontSize: { xs: '0.875rem', sm: '1rem' }
                }
              }}
            />
            <Button 
              onClick={handleAddObservationClick} 
              variant="contained" 
              size="small" 
              disabled={!newObservation.trim()}
              sx={{
                minWidth: { xs: '100%', sm: 'auto' },
                height: { xs: 40, sm: 36 }
              }}
            >
              <Send fontSize="small" sx={{ mr: { xs: 1, sm: 0 } }} />
              <Typography sx={{ display: { xs: 'inline', sm: 'none' }, fontSize: '0.875rem' }}>
                Enviar
              </Typography>
            </Button>
            
            {/* Botón para subir imágenes */}
            <Button
              onClick={() => onOpenImageUpload(pendiente)}
              variant="outlined"
              size="small"
              sx={{
                minWidth: { xs: '100%', sm: 'auto' },
                height: { xs: 40, sm: 36 },
                borderColor: 'primary.main',
                color: 'primary.main',
                '&:hover': {
                  bgcolor: 'primary.main',
                  color: 'white'
                }
              }}
            >
              <AttachFile fontSize="small" sx={{ mr: { xs: 1, sm: 0 } }} />
              <Typography sx={{ display: { xs: 'inline', sm: 'none' }, fontSize: '0.875rem' }}>
                Imágenes
              </Typography>
            </Button>
          </Box>
        </Box>
      </CardContent>
      <CardActions sx={{ 
        justifyContent: 'flex-end',
        p: { xs: 1, sm: 2 },
        gap: { xs: 0.5, sm: 1 }
      }}>
        {!isCreatedPendiente && canEdit && (
          <Button 
            size="small" 
            startIcon={<Edit />} 
            onClick={onEdit}
            sx={{
              fontSize: { xs: '0.75rem', sm: '0.875rem' },
              px: { xs: 1, sm: 2 }
            }}
          >
            Gestionar
          </Button>
        )}
        {canEdit && (
          <Button size="small" color="error" startIcon={<Delete />} onClick={onDelete}>
            Eliminar
          </Button>
        )}
      </CardActions>
    </Card>
  );
};

