// Componente para filtrar pendientes
const FilterPendientesDialog = ({ open, onClose, filterState, onFilterChange }) => {
  const [tempFilterState, setTempFilterState] = useState({ ...filterState });

  const handleFilterChange = (e) => {
    setTempFilterState(prev => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleApplyFilters = () => {
    onFilterChange(tempFilterState);
    onClose();
  };

  const handleClearFilters = () => {
    setTempFilterState({ area: '', urgencia: '', estado: '' });
    onFilterChange({ area: '', urgencia: '', estado: '' });
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>Filtros de Pendientes</DialogTitle>
      <DialogContent>
        <Grid container spacing={2}>
          <Grid item xs={12} sm={6}>
            <FormControl fullWidth size="small">
              <InputLabel>Área</InputLabel>
              <Select
                value={tempFilterState.area}
                onChange={handleFilterChange}
                label="Área"
              >
                                 <MenuItem value="">Todas</MenuItem>
                 <MenuItem value="Mantenimiento">Mantenimiento</MenuItem>
                 <MenuItem value="Fabrica">Fabrica</MenuItem>
                 <MenuItem value="R.R.H.H">R.R.H.H</MenuItem>
                 <MenuItem value="Papelera">Papelera</MenuItem>
                 <MenuItem value="Marketing">Marketing</MenuItem>
                 <MenuItem value="Obras">Obras</MenuItem>
                 <MenuItem value="Sistemas">Sistemas</MenuItem>
                 <MenuItem value="Capacitaciones">Capacitaciones</MenuItem>
                 <MenuItem value="Personal">Personal</MenuItem>
                 <MenuItem value="Zonal">Zonal</MenuItem>
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12} sm={6}>
            <FormControl fullWidth size="small">
              <InputLabel>Urgencia</InputLabel>
              <Select
                value={tempFilterState.urgencia}
                onChange={handleFilterChange}
                name="urgencia"
              >
                <MenuItem value="">Todas</MenuItem>
                <MenuItem value="alta">Alta</MenuItem>
                <MenuItem value="media">Media</MenuItem>
                <MenuItem value="baja">Baja</MenuItem>
              </Select>
            </FormControl>
          </Grid>
                     <Grid item xs={12} sm={6}>
             <FormControl fullWidth size="small">
               <InputLabel>Estado</InputLabel>
               <Select
                 value={tempFilterState.estado}
                 onChange={handleFilterChange}
                 name="estado"
               >
                 <MenuItem value="">Todos</MenuItem>
                 <MenuItem value="asignado">Asignado</MenuItem>
                 <MenuItem value="en_proceso">En Proceso</MenuItem>
                 <MenuItem value="realizado">Realizado</MenuItem>
                 <MenuItem value="cancelado">Cancelado</MenuItem>
               </Select>
             </FormControl>
           </Grid>
        </Grid>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClearFilters}>Limpiar Filtros</Button>
        <Button onClick={handleApplyFilters} variant="contained">Aplicar Filtros</Button>
      </DialogActions>
    </Dialog>
  );
};

// Componente para crear/editar pendiente
const CreateEditPendienteDialog = ({ open, onClose, onSubmit, pendiente, locales, currentUser }) => {
  const [formData, setFormData] = useState({
    descripcion: '',
    observacionInicial: '',
    localId: '',
    area: '',
    urgencia: 'false',
    estado: 'asignado',
    fechaLimite: ''
  });

  useEffect(() => {
    if (pendiente) {
      setFormData({
        descripcion: pendiente.descripcion,
        observacionInicial: '',
        localId: pendiente.localId,
        area: pendiente.area,
        urgencia: pendiente.urgencia.toString(),
        estado: pendiente.estado,
        fechaLimite: pendiente.fechaLimite ? new Date(pendiente.fechaLimite).toISOString().split('T')[0] : ''
      });
    } else {
      setFormData({
        descripcion: '',
        observacionInicial: '',
        localId: '',
        area: '',
        urgencia: 'false',
        estado: 'asignado',
        fechaLimite: ''
      });
    }
  }, [pendiente]);

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit(formData);
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle>{pendiente ? 'Gestionar Pendiente' : 'Crear Nuevo Pendiente'}</DialogTitle>
      <form onSubmit={handleSubmit}>
        <DialogContent>
          <Grid container spacing={2}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Descripción del Pendiente *"
                value={formData.descripcion}
                onChange={(e) => setFormData(prev => ({ ...prev, descripcion: e.target.value }))}
                required
              />
            </Grid>
            {!pendiente && (
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label="Observación Inicial (Opcional)"
                  multiline
                  rows={3}
                  value={formData.observacionInicial}
                  onChange={(e) => setFormData(prev => ({ ...prev, observacionInicial: e.target.value }))}
                />
              </Grid>
            )}
                         {pendiente && (
               <Grid item xs={12}>
                 <FormControl fullWidth required>
                   <InputLabel>Estado *</InputLabel>
                   <Select
                     value={formData.estado}
                     onChange={(e) => setFormData(prev => ({ ...prev, estado: e.target.value }))}
                     label="Estado *"
                   >
                     <MenuItem value="asignado">Asignado</MenuItem>
                     <MenuItem value="en_proceso">En Proceso</MenuItem>
                     <MenuItem value="realizado">Realizado</MenuItem>
                     <MenuItem value="cancelado">Cancelado</MenuItem>
                   </Select>
                 </FormControl>
               </Grid>
             )}
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Local *</InputLabel>
                <Select
                  value={formData.localId}
                  onChange={(e) => setFormData(prev => ({ ...prev, localId: e.target.value }))}
                  required
                >
                  <MenuItem value="">Seleccionar local</MenuItem>
                  {locales.map(local => (
                    <MenuItem key={local.id} value={local.id}>{local.nombre}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth required>
                <InputLabel>Área *</InputLabel>
                <Select
                  value={formData.area}
                  onChange={(e) => setFormData(prev => ({ ...prev, area: e.target.value }))}
                  label="Área *"
                  required
                >
                                   <MenuItem value="">Seleccionar área</MenuItem>
                 <MenuItem value="Mantenimiento">Mantenimiento</MenuItem>
                 <MenuItem value="Fabrica">Fabrica</MenuItem>
                 <MenuItem value="R.R.H.H">R.R.H.H</MenuItem>
                 <MenuItem value="Papelera">Papelera</MenuItem>
                 <MenuItem value="Marketing">Marketing</MenuItem>
                 <MenuItem value="Obras">Obras</MenuItem>
                 <MenuItem value="Sistemas">Sistemas</MenuItem>
                 <MenuItem value="Capacitaciones">Capacitaciones</MenuItem>
                 <MenuItem value="Personal">Personal</MenuItem>
                 <MenuItem value="Zonal">Zonal</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Urgencia</InputLabel>
                <Select
                  value={formData.urgencia}
                  onChange={(e) => setFormData(prev => ({ ...prev, urgencia: e.target.value }))}
                >
                  <MenuItem value="false">No Urgente</MenuItem>
                  <MenuItem value="true">Urgente</MenuItem>
                </Select>
              </FormControl>
            </Grid>
                         <Grid item xs={12} sm={6}>
               <TextField
                 fullWidth
                 label="Fecha Límite (Opcional)"
                 type="date"
                 value={formData.fechaLimite}
                 onChange={(e) => setFormData(prev => ({ ...prev, fechaLimite: e.target.value }))}
                 InputLabelProps={{
                   shrink: true,
                 }}
               />
             </Grid>
           </Grid>
         </DialogContent>
         <DialogActions>
           <Button onClick={onClose}>Cancelar</Button>
           <Button type="submit" variant="contained">
             {pendiente ? 'Actualizar' : 'Crear'}
           </Button>
         </DialogActions>
      </form>
    </Dialog>
  );
};

export default PendientesTab;