// Servicio de Notificaciones Push
// Maneja las notificaciones push del navegador

class PushNotificationService {
  constructor() {
    this.isSupported = 'Notification' in window && 'serviceWorker' in navigator;
    this.permission = this.isSupported ? Notification.permission : 'denied';
    this.serviceWorkerRegistration = null;
    this.isInitialized = false;
  }

  // Inicializar el servicio de notificaciones
  async initialize() {
    if (!this.isSupported) {
      console.log('Notificaciones push no soportadas en este navegador');
      return false;
    }

    try {
      // Registrar el service worker (compatible con subrutas de GitHub Pages)
      const swPath = `${process.env.PUBLIC_URL || ''}/sw-notifications.js`;
      this.serviceWorkerRegistration = await navigator.serviceWorker.register(swPath);
      console.log('Service Worker registrado para notificaciones:', this.serviceWorkerRegistration);
      
      // Solicitar permisos si no están concedidos
      if (this.permission === 'default') {
        await this.requestPermission();
      }
      
      this.isInitialized = this.permission === 'granted';
      return this.isInitialized;
    } catch (error) {
      console.error('Error inicializando notificaciones push:', error);
      return false;
    }
  }

  // Solicitar permisos para notificaciones
  async requestPermission() {
    if (!this.isSupported) return false;
    
    try {
      this.permission = await Notification.requestPermission();
      console.log('Permiso de notificaciones:', this.permission);
      return this.permission === 'granted';
    } catch (error) {
      console.error('Error solicitando permisos:', error);
      return false;
    }
  }

  // Verificar si las notificaciones están habilitadas
  isEnabled() {
    return this.isSupported && this.permission === 'granted';
  }

  // Suscribirse al PushManager y guardar en Firestore
  async subscribeUser(userId) {
    try {
      if (!this.serviceWorkerRegistration) {
        const ok = await this.initialize();
        if (!ok) return { success: false, error: 'No inicializado' };
      }

      const existing = await this.serviceWorkerRegistration.pushManager.getSubscription();
      if (existing) {
        return { success: true, already: true };
      }

      const base64ToUint8Array = (base64) => {
        const padding = '='.repeat((4 - (base64.length % 4)) % 4);
        const base64Safe = (base64 + padding).replace(/-/g, '+').replace(/_/g, '/');
        const rawData = window.atob(base64Safe);
        return Uint8Array.from([...rawData].map((c) => c.charCodeAt(0)));
      };

      const vapidPublicKey = process.env.REACT_APP_VAPID_PUBLIC_KEY;
      if (!vapidPublicKey) {
        console.warn('REACT_APP_VAPID_PUBLIC_KEY no configurada');
        return { success: false, error: 'VAPID pública faltante' };
      }

      const subscription = await this.serviceWorkerRegistration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: base64ToUint8Array(vapidPublicKey)
      });

      // Guardar en Firestore
      const { default: PushSubscriptionRepository } = await import('../repositories/PushSubscriptionRepository');
      await PushSubscriptionRepository.saveSubscription(userId, subscription.toJSON());

      return { success: true };
    } catch (error) {
      console.error('Error suscribiendo al push:', error);
      return { success: false, error: error.message };
    }
  }

  // Mostrar notificación de pendiente asignado
  showPendienteAsignado(pendiente) {
    if (!this.isEnabled()) return;

    const message = {
      type: 'SHOW_NOTIFICATION',
      title: '📋 Nuevo Pendiente Asignado',
      body: `Se te asignó: "${pendiente.titulo}" en ${pendiente.localNombre}`,
      icon: '/favicon.ico',
      tag: `pendiente_${pendiente.id}`,
      data: {
        url: '/',
        pendienteId: pendiente.id,
        localId: pendiente.localId,
        localNombre: pendiente.localNombre
      }
    };

    this.sendMessageToServiceWorker(message);
  }

  // Mostrar notificación de vencimiento
  showVencimiento(vencimiento) {
    if (!this.isEnabled()) return;

    let title, body, tag;
    
    if (vencimiento.diasRestantes === 0) {
      title = '⚠️ ¡VENCIMIENTO URGENTE!';
      body = `¡VENCIDO! ${vencimiento.tipoVencimiento} en ${vencimiento.localNombre}`;
      tag = `vencimiento_urgente_${vencimiento.localId}_${vencimiento.tipoVencimiento}`;
    } else {
      title = '⏰ Vencimiento Próximo';
      body = `Quedan ${vencimiento.diasRestantes} días para ${vencimiento.tipoVencimiento} en ${vencimiento.localNombre}`;
      tag = `vencimiento_${vencimiento.localId}_${vencimiento.tipoVencimiento}_${vencimiento.diasRestantes}`;
    }

    const message = {
      type: 'SHOW_NOTIFICATION',
      title: title,
      body: body,
      icon: '/favicon.ico',
      tag: tag,
      data: {
        url: '/',
        localId: vencimiento.localId,
        localNombre: vencimiento.localNombre,
        tipoVencimiento: vencimiento.tipoVencimiento,
        diasRestantes: vencimiento.diasRestantes
      }
    };

    this.sendMessageToServiceWorker(message);
  }

  // Mostrar notificación de gasto aprobado/rechazado
  showGastoStatus(gasto, aprobado) {
    if (!this.isEnabled()) return;

    const title = aprobado ? '✅ Gasto Aprobado' : '❌ Gasto Rechazado';
    const body = `Tu gasto de $${gasto.monto} en ${gasto.localNombre} fue ${aprobado ? 'aprobado' : 'rechazado'}`;
    const tag = `gasto_${gasto.id}_${aprobado ? 'aprobado' : 'rechazado'}`;

    const message = {
      type: 'SHOW_NOTIFICATION',
      title: title,
      body: body,
      icon: '/favicon.ico',
      tag: tag,
      data: {
        url: '/',
        gastoId: gasto.id,
        localId: gasto.localId,
        localNombre: gasto.localNombre,
        monto: gasto.monto
      }
    };

    this.sendMessageToServiceWorker(message);
  }

  // Mostrar notificación personalizada
  showCustomNotification(title, body, data = {}) {
    if (!this.isEnabled()) return;

    const message = {
      type: 'SHOW_NOTIFICATION',
      title: title,
      body: body,
      icon: '/favicon.ico',
      tag: `custom_${Date.now()}`,
      data: {
        url: '/',
        ...data
      }
    };

    this.sendMessageToServiceWorker(message);
  }

  // Enviar mensaje al service worker
  sendMessageToServiceWorker(message) {
    if (this.serviceWorkerRegistration && this.serviceWorkerRegistration.active) {
      this.serviceWorkerRegistration.active.postMessage(message);
    } else {
      console.warn('Service Worker no está activo, no se puede mostrar notificación');
    }
  }

  // Obtener configuración de notificaciones del usuario
  getNotificationSettings() {
    const settings = localStorage.getItem('adminSE_notificationSettings');
    return settings ? JSON.parse(settings) : {
      pendientes: true,
      vencimientos: true,
      gastos: true,
      sonido: true,
      vibrar: true
    };
  }

  // Guardar configuración de notificaciones del usuario
  saveNotificationSettings(settings) {
    localStorage.setItem('adminSE_notificationSettings', JSON.stringify(settings));
  }

  // Verificar si un tipo de notificación está habilitado
  isNotificationTypeEnabled(type) {
    const settings = this.getNotificationSettings();
    return settings[type] !== false;
  }

  // Deshabilitar notificaciones
  disable() {
    this.saveNotificationSettings({
      pendientes: false,
      vencimientos: false,
      gastos: false,
      sonido: false,
      vibrar: false
    });
  }

  // Habilitar todas las notificaciones
  enableAll() {
    this.saveNotificationSettings({
      pendientes: true,
      vencimientos: true,
      gastos: true,
      sonido: true,
      vibrar: true
    });
  }
}

// Crear instancia singleton
const pushNotificationService = new PushNotificationService();

export default pushNotificationService;
