// Modelo de Usuario - Idéntico al de Android
export class User {
  constructor({
    id = "",
    nombre = "",
    username = "",
    rol = "SUPERVISOR",
    localesAsignados = [],
    createdAt = Date.now()
  } = {}) {
    this.id = id;
    this.nombre = nombre;
    this.username = username;
    this.rol = rol;
    this.localesAsignados = localesAsignados;
    this.createdAt = createdAt;
  }

  toMap() {
    return {
      id: this.id,
      nombre: this.nombre,
      username: this.username,
      rol: this.rol,
      localesAsignados: this.localesAsignados,
      createdAt: this.createdAt
    };
  }

  static fromMap(data) {
    return new User({
      id: data.id || "",
      nombre: data.nombre || "",
      username: data.username || "",
      rol: data.rol || "SUPERVISOR",
      localesAsignados: data.localesAsignados || [],
      createdAt: data.createdAt || Date.now()
    });
  }
}

export default User;
