import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CardActions,
  Button,
  Grid,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  CircularProgress,
  Divider,
} from '@mui/material';
import {
  FilterList,
  Delete,
  Inventory,
  Schedule,
  Person,
  LocationOn,
  PhotoCamera,
} from '@mui/icons-material';
import ArqueoRepository from '../../repositories/ArqueoRepository';
import LocalRepository from '../../repositories/LocalRepository';
import UserRepository from '../../repositories/UserRepository';
import ImagenRepository from '../../repositories/ImagenRepository';

const ArqueosTab = ({ user }) => {
  const [arqueos, setArqueos] = useState([]);
  const [locales, setLocales] = useState([]);
  const [supervisores, setSupervisores] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showFilterDialog, setShowFilterDialog] = useState(false);
  const [filterState, setFilterState] = useState({
    localId: '',
    supervisorId: '',
    fechaDesde: '',
    fechaHasta: ''
  });

  // Cargar datos desde Firebase en tiempo real
  useEffect(() => {
    setLoading(true);

    // Suscribirse a todos los arqueos en tiempo real
    const unsubscribeArqueos = ArqueoRepository.subscribeToArqueos((arqueos) => {
      console.log('Arqueos recibidos de Firebase:', arqueos);
      setArqueos(arqueos);
      setLoading(false);
    });

    // Suscribirse a locales en tiempo real
    const unsubscribeLocales = LocalRepository.subscribeToLocales((locales) => {
      console.log('Locales recibidos de Firebase:', locales);
      setLocales(locales);
    });

    // Cargar supervisores
    const loadSupervisores = async () => {
      try {
        const result = await UserRepository.getUsersByRole('supervisor');
        if (result.success) {
          setSupervisores(result.users);
        }
      } catch (error) {
        console.error('Error cargando supervisores:', error);
      }
    };

    loadSupervisores();

    return () => {
      unsubscribeArqueos();
      unsubscribeLocales();
    };
  }, []);

  const handleDeleteArqueo = async (id) => {
    if (!window.confirm('¿Estás seguro de que quieres eliminar este arqueo?')) {
      return;
    }
    
    try {
      const result = await ArqueoRepository.deleteArqueo(id);
      if (result.success) {
        // Data will update via real-time subscription
      } else {
        console.error('Error eliminando arqueo:', result.error);
        alert('Error al eliminar el arqueo');
      }
    } catch (error) {
      console.error('Error eliminando arqueo:', error);
      alert('Error al eliminar el arqueo');
    }
  };

  const getFilteredArqueos = () => {
    return arqueos.filter(arqueo => {
      const matchesLocal = filterState.localId === '' || arqueo.localId === filterState.localId;
      const matchesSupervisor = filterState.supervisorId === '' || arqueo.supervisorId === filterState.supervisorId;
      
      // Filtro de fecha desde
      let matchesFechaDesde = true;
      if (filterState.fechaDesde) {
        const [year, month, day] = filterState.fechaDesde.split('-').map(Number);
        const fechaDesde = new Date(year, month - 1, day, 0, 0, 0, 0);
        const fechaDesdeTimestamp = fechaDesde.getTime();
        matchesFechaDesde = arqueo.fecha >= fechaDesdeTimestamp;
      }
      
      // Filtro de fecha hasta
      let matchesFechaHasta = true;
      if (filterState.fechaHasta) {
        const [year, month, day] = filterState.fechaHasta.split('-').map(Number);
        const fechaHasta = new Date(year, month - 1, day, 23, 59, 59, 999);
        const fechaHastaTimestamp = fechaHasta.getTime();
        matchesFechaHasta = arqueo.fecha <= fechaHastaTimestamp;
      }
      
      return matchesLocal && matchesSupervisor && matchesFechaDesde && matchesFechaHasta;
    });
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Cargando arqueos...</Typography>
      </Box>
    );
  }

  const filteredArqueos = getFilteredArqueos();

  return (
    <Box sx={{ p: 2 }}>
      {/* Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5" sx={{ fontWeight: 600 }}>
          Arqueos
        </Typography>
        <Box>
          <Button
            variant="outlined"
            startIcon={<FilterList />}
            onClick={() => setShowFilterDialog(true)}
          >
            Filtros
          </Button>
        </Box>
      </Box>

      {/* Filtros Activos */}
      <Box sx={{ mb: 2 }}>
        <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>Filtros activos:</Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          {filterState.localId && (
            <Chip
              label={`Local: ${locales.find(l => l.id === filterState.localId)?.nombre || 'Desconocido'}`}
              onDelete={() => setFilterState(prev => ({ ...prev, localId: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {filterState.supervisorId && (
            <Chip
              label={`Supervisor: ${supervisores.find(s => s.id === filterState.supervisorId)?.nombre || 'Desconocido'}`}
              onDelete={() => setFilterState(prev => ({ ...prev, supervisorId: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {filterState.fechaDesde && (
            <Chip
              label={`Desde: ${new Date(filterState.fechaDesde).toLocaleDateString('es-AR')}`}
              onDelete={() => setFilterState(prev => ({ ...prev, fechaDesde: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {filterState.fechaHasta && (
            <Chip
              label={`Hasta: ${new Date(filterState.fechaHasta).toLocaleDateString('es-AR')}`}
              onDelete={() => setFilterState(prev => ({ ...prev, fechaHasta: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {!filterState.localId && !filterState.supervisorId && !filterState.fechaDesde && !filterState.fechaHasta && (
            <Typography variant="body2" color="text.secondary">Ninguno</Typography>
          )}
        </Box>
      </Box>

      {/* Estadísticas */}
      <Box sx={{ mb: 3 }}>
        <Typography variant="subtitle1" color="text.secondary">
          Total de arqueos: <strong>{filteredArqueos.length}</strong>
        </Typography>
      </Box>

      {/* Lista de Arqueos */}
      {filteredArqueos.length === 0 ? (
        <Card sx={{ textAlign: 'center', py: 4 }}>
          <CardContent>
            <Inventory sx={{ fontSize: 60, color: 'text.secondary', mb: 2 }} />
            <Typography variant="h6" color="text.secondary">
              No hay arqueos que coincidan con los filtros.
            </Typography>
          </CardContent>
        </Card>
      ) : (
        <Grid container spacing={2}>
          {filteredArqueos.map((arqueo) => (
            <Grid item xs={12} sm={6} md={4} key={arqueo.id}>
              <ArqueoCard
                arqueo={arqueo}
                onDelete={() => handleDeleteArqueo(arqueo.id)}
              />
            </Grid>
          ))}
        </Grid>
      )}

      {/* Dialog para Filtros */}
      <FilterArqueosDialog
        open={showFilterDialog}
        onClose={() => setShowFilterDialog(false)}
        filterState={filterState}
        onFilterChange={setFilterState}
        locales={locales}
        supervisores={supervisores}
      />
    </Box>
  );
};

const ArqueoCard = ({ arqueo, onDelete }) => {
  const [showImage, setShowImage] = useState(false);
  const [imagen, setImagen] = useState(null);
  const [loadingImage, setLoadingImage] = useState(false);

  // Cargar imagen desde ImagenRepository cuando hay un imagenId
  useEffect(() => {
    if (arqueo.imagenId && !imagen) {
      setLoadingImage(true);
      ImagenRepository.getImagenById(arqueo.imagenId)
        .then(result => {
          if (result.success) {
            const img = result.imagen;
            // Si la URL está vacía pero hay dataBase64, construir la URL
            if (!img.url && img.dataBase64) {
              img.url = `data:${img.mimeType || 'image/jpeg'};base64,${img.dataBase64}`;
            }
            if (!img.thumbnailUrl && img.dataBase64) {
              img.thumbnailUrl = img.url; // Usar la misma imagen como thumbnail
            }
            setImagen(img);
            console.log('Imagen procesada:', img);
          } else {
            console.error('Error cargando imagen:', result.error);
          }
          setLoadingImage(false);
        })
        .catch(error => {
          console.error('Error cargando imagen:', error);
          setLoadingImage(false);
        });
    }
  }, [arqueo.imagenId, imagen]);

  return (
    <>
      <Card sx={{ '&:hover': { boxShadow: 4 }, height: '100%', display: 'flex', flexDirection: 'column' }}>
        <CardContent sx={{ flexGrow: 1 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
            <Typography variant="h6" sx={{ fontWeight: 600, display: 'flex', alignItems: 'center' }}>
              <Inventory sx={{ mr: 1 }} />
              Arqueo
            </Typography>
            <Chip
              label={new Date(arqueo.fecha).toLocaleDateString('es-AR')}
              color="primary"
              size="small"
              icon={<Schedule fontSize="small" />}
            />
          </Box>

          <Box sx={{ mb: 2 }}>
            <Typography variant="body2" color="text.secondary" sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
              <LocationOn fontSize="small" sx={{ mr: 0.5 }} />
              {arqueo.localNombre}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ display: 'flex', alignItems: 'center' }}>
              <Person fontSize="small" sx={{ mr: 0.5 }} />
              {arqueo.supervisorNombre}
            </Typography>
          </Box>

          {arqueo.imagenId && (
            <Box sx={{ mb: 2 }}>
              {loadingImage ? (
                <Box sx={{ display: 'flex', justifyContent: 'center', p: 2 }}>
                  <CircularProgress size={24} />
                </Box>
              ) : imagen ? (
                <Box
                  onClick={() => setShowImage(true)}
                  sx={{
                    cursor: 'pointer',
                    borderRadius: 1,
                    overflow: 'hidden',
                    border: '1px solid',
                    borderColor: 'divider',
                    '&:hover': {
                      opacity: 0.8
                    }
                  }}
                >
                  <img
                    src={imagen.thumbnailUrl || imagen.url}
                    alt="Miniatura del arqueo"
                    style={{
                      width: '100%',
                      height: '150px',
                      objectFit: 'cover'
                    }}
                    onError={(e) => {
                      console.error('Error cargando imagen miniatura:', e);
                      console.error('URL que falló:', imagen.thumbnailUrl || imagen.url);
                      console.error('Imagen completa:', imagen);
                    }}
                  />
                </Box>
              ) : (
                <Button
                  size="small"
                  startIcon={<PhotoCamera />}
                  onClick={() => setShowImage(true)}
                  variant="outlined"
                  fullWidth
                >
                  Ver Foto
                </Button>
              )}
            </Box>
          )}

          <Divider sx={{ my: 1 }} />

          <Typography variant="caption" color="text.secondary">
            Creado: {new Date(arqueo.createdAt).toLocaleDateString('es-AR')}
          </Typography>
        </CardContent>
        <CardActions>
          <Button size="small" color="error" startIcon={<Delete />} onClick={onDelete}>
            Eliminar
          </Button>
        </CardActions>
      </Card>

      {/* Dialog para mostrar la imagen */}
      <Dialog open={showImage} onClose={() => setShowImage(false)} maxWidth="md" fullWidth>
        <DialogTitle>
          Arqueo - {arqueo.localNombre}
          <Typography variant="caption" display="block" color="text.secondary">
            {new Date(arqueo.fecha).toLocaleDateString('es-AR')} • {arqueo.supervisorNombre}
          </Typography>
        </DialogTitle>
        <DialogContent>
          {loadingImage ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
              <CircularProgress />
            </Box>
          ) : imagen ? (
            <img 
              src={imagen.url} 
              alt="Arqueo" 
              style={{ width: '100%', height: 'auto' }}
            />
          ) : (
            <Typography>No se pudo cargar la imagen</Typography>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setShowImage(false)}>Cerrar</Button>
          {imagen && (
            <Button 
              variant="contained" 
              onClick={() => {
                const win = window.open();
                win.document.write(`<img src="${imagen.url}" style="max-width: 100%;">`);
              }}
            >
              Abrir en Nueva Pestaña
            </Button>
          )}
        </DialogActions>
      </Dialog>
    </>
  );
};

const FilterArqueosDialog = ({ open, onClose, filterState, onFilterChange, locales, supervisores }) => {
  const [currentFilters, setCurrentFilters] = useState(filterState);

  useEffect(() => {
    setCurrentFilters(filterState);
  }, [filterState]);

  const handleFilterChange = (field) => (event) => {
    setCurrentFilters(prev => ({ ...prev, [field]: event.target.value }));
  };

  const handleApplyFilters = () => {
    onFilterChange(currentFilters);
    onClose();
  };

  const handleClearFilters = () => {
    const clearedFilters = {
      localId: '',
      supervisorId: '',
      fechaDesde: '',
      fechaHasta: ''
    };
    setCurrentFilters(clearedFilters);
    onFilterChange(clearedFilters);
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>Filtrar Arqueos</DialogTitle>
      <DialogContent>
        <Grid container spacing={2}>
          <Grid item xs={12}>
            <FormControl fullWidth>
              <InputLabel>Local</InputLabel>
              <Select
                value={currentFilters.localId}
                onChange={handleFilterChange('localId')}
                label="Local"
              >
                <MenuItem value="">Todos los locales</MenuItem>
                {locales.map(local => (
                  <MenuItem key={local.id} value={local.id}>{local.nombre}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12}>
            <FormControl fullWidth>
              <InputLabel>Supervisor</InputLabel>
              <Select
                value={currentFilters.supervisorId}
                onChange={handleFilterChange('supervisorId')}
                label="Supervisor"
              >
                <MenuItem value="">Todos los supervisores</MenuItem>
                {supervisores.map(supervisor => (
                  <MenuItem key={supervisor.id} value={supervisor.id}>{supervisor.nombre}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Fecha Desde"
              type="date"
              value={currentFilters.fechaDesde}
              onChange={handleFilterChange('fechaDesde')}
              InputLabelProps={{
                shrink: true,
              }}
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              label="Fecha Hasta"
              type="date"
              value={currentFilters.fechaHasta}
              onChange={handleFilterChange('fechaHasta')}
              InputLabelProps={{
                shrink: true,
              }}
            />
          </Grid>
        </Grid>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClearFilters}>Limpiar Filtros</Button>
        <Button onClick={handleApplyFilters} variant="contained">Aplicar Filtros</Button>
      </DialogActions>
    </Dialog>
  );
};

export default ArqueosTab;

