// Repositorio de Pendientes - Conecta con Firebase real (igual que la app Android)
import { db } from '../services/firebase';
import { collection, doc, getDoc, setDoc, updateDoc, deleteDoc, getDocs, query, where, orderBy, addDoc } from 'firebase/firestore';
import { onSnapshot } from 'firebase/firestore';
import Pendiente from '../models/Pendiente';
import Observacion from '../models/Observacion';
import LocalRepository from './LocalRepository';

class PendienteRepository {
  // Crear pendiente (igual que la app Android)
  async createPendiente(pendiente) {
    try {
      // Si es un objeto plano, convertirlo a mapa
      const pendienteMap = typeof pendiente.toMap === 'function' 
        ? pendiente.toMap() 
        : pendiente;
      
      const pendientesCollection = collection(db, 'pendientes');
      const docRef = await addDoc(pendientesCollection, pendienteMap);
      
      // Actualizar estado del local
      await LocalRepository.updateLocalEstado(pendiente.localId || pendienteMap.localId);
      
      return { success: true, id: docRef.id };
    } catch (error) {
      console.error('Error creando pendiente:', error);
      return { success: false, error: error.message };
    }
  }

  // Actualizar pendiente (igual que la app Android)
  async updatePendiente(pendienteId, pendiente) {
    try {
      // Si es un objeto plano, usarlo directamente; si tiene toMap, convertirlo
      const pendienteMap = typeof pendiente.toMap === 'function' 
        ? pendiente.toMap() 
        : pendiente;
      
      // Obtener el pendiente actual para tener el localId
      const pendienteActual = await this.getPendienteById(pendienteId);
      const localId = pendienteMap.localId || (pendienteActual.success ? pendienteActual.pendiente.localId : null);
      
      const pendienteDocRef = doc(db, 'pendientes', pendienteId);
      await updateDoc(pendienteDocRef, pendienteMap);
      
      // Actualizar estado del local solo si tenemos un localId válido
      if (localId) {
        await LocalRepository.updateLocalEstado(localId);
      }
      
      return { success: true };
    } catch (error) {
      console.error('Error actualizando pendiente:', error);
      return { success: false, error: error.message };
    }
  }

  // Actualizar estado del pendiente (igual que la app Android)
  async updateEstado(pendienteId, estado, observaciones = '') {
    try {
      const pendienteDocRef = doc(db, 'pendientes', pendienteId);
      await updateDoc(pendienteDocRef, {
        estado: estado,
        observaciones: observaciones,
        updatedAt: Date.now()
      });
      
      // Actualizar estado del local
      const pendiente = await this.getPendienteById(pendienteId);
      if (pendiente.success) {
        await LocalRepository.updateLocalEstado(pendiente.pendiente.localId);
      }
      
      return { success: true };
    } catch (error) {
      console.error('Error actualizando estado:', error);
      return { success: false, error: error.message };
    }
  }

  // Eliminar pendiente (igual que la app Android)
  async deletePendiente(pendienteId) {
    try {
      // Obtener el pendiente antes de eliminarlo para actualizar el estado del local
      const pendiente = await this.getPendienteById(pendienteId);
      
      const pendienteDocRef = doc(db, 'pendientes', pendienteId);
      await deleteDoc(pendienteDocRef);
      
      // Actualizar estado del local si existe
      if (pendiente.success) {
        await LocalRepository.updateLocalEstado(pendiente.pendiente.localId);
      }
      
      return { success: true };
    } catch (error) {
      console.error('Error eliminando pendiente:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener pendiente por ID (igual que la app Android)
  async getPendienteById(pendienteId) {
    try {
      const pendienteDocRef = doc(db, 'pendientes', pendienteId);
      const pendienteDoc = await getDoc(pendienteDocRef);

      if (!pendienteDoc.exists()) {
        return { success: false, error: 'Pendiente no encontrado' };
      }

      const pendienteData = pendienteDoc.data();
      const pendiente = Pendiente.fromMap({ ...pendienteData, id: pendienteDoc.id });
      return { success: true, pendiente };
    } catch (error) {
      console.error('Error obteniendo pendiente:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener todos los pendientes (igual que la app Android)
  getAllPendientes() {
    return new Promise((resolve, reject) => {
      const pendientesCollection = collection(db, 'pendientes');
      const q = query(pendientesCollection, orderBy('createdAt', 'desc'));
      
      const unsubscribe = onSnapshot(q, (snapshot) => {
        const pendientes = [];
        snapshot.forEach(doc => {
          const pendienteData = doc.data();
          const pendiente = Pendiente.fromMap({ ...pendienteData, id: doc.id });
          pendientes.push(pendiente);
        });
        resolve(pendientes);
      }, (error) => {
        console.error('Error obteniendo pendientes:', error);
        reject(error);
      });

      return unsubscribe;
    });
  }

  // Suscribirse a todos los pendientes en tiempo real (igual que la app Android)
  subscribeToPendientes(callback) {
    const pendientesCollection = collection(db, 'pendientes');
    const q = query(pendientesCollection, orderBy('createdAt', 'desc'));
    
    return onSnapshot(q, (snapshot) => {
      const pendientes = [];
      snapshot.forEach(doc => {
        const pendienteData = doc.data();
        const pendiente = Pendiente.fromMap({ ...pendienteData, id: doc.id });
        pendientes.push(pendiente);
      });
      callback(pendientes);
    }, (error) => {
      console.error('Error suscribiéndose a pendientes:', error);
    });
  }

  // Obtener pendientes por local (igual que la app Android)
  getPendientesByLocal(localId) {
    return new Promise((resolve, reject) => {
      const pendientesCollection = collection(db, 'pendientes');
      const q = query(
        pendientesCollection,
        where('localId', '==', localId),
        orderBy('createdAt', 'desc')
      );
      
      const unsubscribe = onSnapshot(q, (snapshot) => {
        const pendientes = [];
        snapshot.forEach(doc => {
          const pendienteData = doc.data();
          const pendiente = Pendiente.fromMap({ ...pendienteData, id: doc.id });
          pendientes.push(pendiente);
        });
        resolve(pendientes);
      }, (error) => {
        console.error('Error obteniendo pendientes por local:', error);
        reject(error);
      });

      return unsubscribe;
    });
  }

  // Suscribirse a pendientes por local en tiempo real (igual que la app Android)
  subscribeToPendientesByLocal(localId, callback) {
    const pendientesCollection = collection(db, 'pendientes');
    const q = query(
      pendientesCollection,
      where('localId', '==', localId),
      orderBy('createdAt', 'desc')
    );
    
    return onSnapshot(q, (snapshot) => {
      const pendientes = [];
      snapshot.forEach(doc => {
        const pendienteData = doc.data();
        const pendiente = Pendiente.fromMap({ ...pendienteData, id: doc.id });
        pendientes.push(pendiente);
      });
      callback(pendientes);
    }, (error) => {
      console.error('Error suscribiéndose a pendientes por local:', error);
    });
  }

  // Obtener pendientes por supervisor (igual que la app Android)
  getPendientesBySupervisor(supervisorId) {
    return new Promise((resolve, reject) => {
      const pendientesCollection = collection(db, 'pendientes');
      const q = query(
        pendientesCollection,
        where('supervisorId', '==', supervisorId),
        orderBy('createdAt', 'desc')
      );
      
      const unsubscribe = onSnapshot(q, (snapshot) => {
        const pendientes = [];
        snapshot.forEach(doc => {
          const pendienteData = doc.data();
          const pendiente = Pendiente.fromMap({ ...pendienteData, id: doc.id });
          pendientes.push(pendiente);
        });
        
        // Filtrar pendientes que NO fueron creados por el mismo supervisor (igual que la app Android)
        const pendientesAsignados = pendientes.filter(p => p.creadoPor !== supervisorId);
        
        resolve(pendientesAsignados);
      }, (error) => {
        console.error('Error obteniendo pendientes por supervisor:', error);
        reject(error);
      });

      return unsubscribe;
    });
  }

  // Suscribirse a pendientes por supervisor en tiempo real (igual que la app Android)
  subscribeToPendientesBySupervisor(supervisorId, callback) {
    const pendientesCollection = collection(db, 'pendientes');
    // Consulta simplificada sin orderBy para evitar el error de índice
    const q = query(
      pendientesCollection,
      where('supervisorId', '==', supervisorId)
    );
    
    return onSnapshot(q, (snapshot) => {
      const pendientes = [];
      snapshot.forEach(doc => {
        const pendienteData = doc.data();
        const pendiente = Pendiente.fromMap({ ...pendienteData, id: doc.id });
        pendientes.push(pendiente);
      });
      
      // Ordenar por fecha de creación (descendente) en el cliente
      pendientes.sort((a, b) => b.createdAt - a.createdAt);
      
      // Filtrar pendientes que NO fueron creados por el mismo supervisor (igual que la app Android)
      const pendientesAsignados = pendientes.filter(p => p.creadoPor !== supervisorId);
      
      callback(pendientesAsignados);
    }, (error) => {
      console.error('Error suscribiéndose a pendientes por supervisor:', error);
    });
  }

  // Obtener pendientes creados por supervisor (igual que la app Android)
  getPendientesByCreadoPor(creadoPorId) {
    return new Promise((resolve, reject) => {
      const pendientesCollection = collection(db, 'pendientes');
      const q = query(
        pendientesCollection,
        where('creadoPor', '==', creadoPorId),
        orderBy('createdAt', 'desc')
      );
      
      const unsubscribe = onSnapshot(q, (snapshot) => {
        const pendientes = [];
        snapshot.forEach(doc => {
          const pendienteData = doc.data();
          const pendiente = Pendiente.fromMap({ ...pendienteData, id: doc.id });
          pendientes.push(pendiente);
        });
        resolve(pendientes);
      }, (error) => {
        console.error('Error obteniendo pendientes por creado por:', error);
        reject(error);
      });

      return unsubscribe;
    });
  }

  // Suscribirse a pendientes creados por supervisor en tiempo real (igual que la app Android)
  subscribeToPendientesByCreadoPor(creadoPorId, callback) {
    const pendientesCollection = collection(db, 'pendientes');
    const q = query(
      pendientesCollection,
      where('creadoPor', '==', creadoPorId),
      orderBy('createdAt', 'desc')
    );
    
    return onSnapshot(q, (snapshot) => {
      const pendientes = [];
      snapshot.forEach(doc => {
        const pendienteData = doc.data();
        const pendiente = Pendiente.fromMap({ ...pendienteData, id: doc.id });
        pendientes.push(pendiente);
      });
      callback(pendientes);
    }, (error) => {
      console.error('Error suscribiéndose a pendientes por creado por:', error);
    });
  }

  // Añadir observación a un pendiente (igual que la app Android)
  async addObservation(pendienteId, observacion) {
    try {
      const pendienteDocRef = doc(db, 'pendientes', pendienteId);
      const pendienteDoc = await getDoc(pendienteDocRef);
      
      if (!pendienteDoc.exists()) {
        return { success: false, error: 'Pendiente no encontrado' };
      }
      
      const pendienteData = pendienteDoc.data();
      const observaciones = pendienteData.observaciones || [];
      
      // Serializar la observación para Firestore (convertir a objeto plano)
      const observacionSerializada = JSON.parse(JSON.stringify(observacion));
      
      // Añadir nueva observación
      observaciones.push(observacionSerializada);
      
      console.log('💾 Guardando observación en Firestore:', observacionSerializada);
      
      // Actualizar el documento
      await updateDoc(pendienteDocRef, {
        observaciones: observaciones,
        lastUpdate: Date.now()
      });
      
      return { success: true };
    } catch (error) {
      console.error('Error añadiendo observación:', error);
      return { success: false, error: error.message };
    }
  }

  // Eliminar observación de un pendiente
  async removeObservation(pendienteId, observacionId) {
    try {
      const pendienteDocRef = doc(db, 'pendientes', pendienteId);
      const pendienteDoc = await getDoc(pendienteDocRef);
      
      if (!pendienteDoc.exists()) {
        return { success: false, error: 'Pendiente no encontrado' };
      }
      
      const pendienteData = pendienteDoc.data();
      const observaciones = pendienteData.observaciones || [];
      
      // Filtrar la observación a eliminar
      const observacionesActualizadas = observaciones.filter(obs => obs.id !== observacionId);
      
      // Actualizar el documento
      await updateDoc(pendienteDocRef, {
        observaciones: observacionesActualizadas,
        lastUpdate: Date.now()
      });
      
      return { success: true };
    } catch (error) {
      console.error('Error eliminando observación:', error);
      return { success: false, error: error.message };
    }
  }

  // Actualizar observación de un pendiente
  async updateObservation(pendienteId, observacionActualizada) {
    try {
      const pendienteDocRef = doc(db, 'pendientes', pendienteId);
      const pendienteDoc = await getDoc(pendienteDocRef);
      
      if (!pendienteDoc.exists()) {
        return { success: false, error: 'Pendiente no encontrado' };
      }
      
      const pendienteData = pendienteDoc.data();
      const observaciones = pendienteData.observaciones || [];
      
      // Encontrar y actualizar la observación
      const observacionesActualizadas = observaciones.map(obs => 
        obs.id === observacionActualizada.id ? observacionActualizada : obs
      );
      
      // Actualizar el documento
      await updateDoc(pendienteDocRef, {
        observaciones: observacionesActualizadas,
        lastUpdate: Date.now()
      });
      
      return { success: true };
    } catch (error) {
      console.error('Error actualizando observación:', error);
      return { success: false, error: error.message };
    }
  }
}

export default new PendienteRepository();