// Repositorio de Notificaciones - Conecta con Firebase real (igual que la app Android)
import { db } from '../services/firebase';
import { collection, doc, getDoc, setDoc, updateDoc, deleteDoc, getDocs, query, where, orderBy, addDoc, limit } from 'firebase/firestore';
import { onSnapshot } from 'firebase/firestore';
import Notification from '../models/Notification';

class NotificationRepository {
  // Crear notificación (igual que la app Android)
  async createNotification(notification) {
    try {
      // Si viene con ID, hacemos UPSERT idempotente (evita duplicados)
      if (notification.id) {
        const notificationDocRef = doc(db, 'notifications', notification.id);
        await setDoc(notificationDocRef, notification.toMap(), { merge: false });
        await this.cleanupOldNotifications(notification.userId);
        return { success: true, id: notification.id };
      }

      // Fallback: verificar duplicados recientes por referenceId/tipo
      const existingNotification = await this.checkForDuplicateNotification(notification);
      if (existingNotification) {
        return await this.updateExistingNotification(existingNotification, notification);
      }

      const notificationsCollection = collection(db, 'notifications');
      const docRef = await addDoc(notificationsCollection, notification.toMap());
      
      // Limpiar notificaciones antiguas después de crear una nueva
      await this.cleanupOldNotifications(notification.userId);
      
      return { success: true, id: docRef.id };
    } catch (error) {
      console.error('Error creando notificación:', error);
      return { success: false, error: error.message };
    }
  }

  // Verificar notificación duplicada (más estricto para evitar falsos positivos)
  async checkForDuplicateNotification(notification) {
    try {
      const twentyFourHoursAgo = Date.now() - (24 * 60 * 60 * 1000);
      
      const notificationsCollection = collection(db, 'notifications');
      const q = query(
        notificationsCollection,
        where('userId', '==', notification.userId),
        where('tipo', '==', notification.tipo),
        where('referenceId', '==', notification.referenceId),
        where('mensaje', '==', notification.mensaje),
        where('createdAt', '>', twentyFourHoursAgo),
        limit(1)
      );
      
      const snapshot = await getDocs(q);
      
      if (!snapshot.empty) {
        return snapshot.docs[0].id;
      } else {
        return null;
      }
    } catch (error) {
      console.error('Error verificando notificación duplicada:', error);
      return null;
    }
  }

  // Actualizar notificación existente (igual que la app Android)
  async updateExistingNotification(existingId, newNotification) {
    try {
      const updates = {
        mensaje: newNotification.mensaje,
        createdAt: Date.now(),
        leida: false
      };
      
      const notificationDocRef = doc(db, 'notifications', existingId);
      await updateDoc(notificationDocRef, updates);
      
      return { success: true, id: existingId };
    } catch (error) {
      console.error('Error actualizando notificación existente:', error);
      return { success: false, error: error.message };
    }
  }

  // Limpiar notificaciones antiguas (igual que la app Android)
  async cleanupOldNotifications(userId) {
    try {
      const sevenDaysAgo = Date.now() - (7 * 24 * 60 * 60 * 1000);
      
      const notificationsCollection = collection(db, 'notifications');
      const q = query(
        notificationsCollection,
        where('userId', '==', userId),
        where('createdAt', '<', sevenDaysAgo),
        where('leida', '==', true)
      );
      
      const snapshot = await getDocs(q);
      
      // Eliminar notificaciones leídas de más de 7 días
      const deletePromises = snapshot.docs.map(doc => deleteDoc(doc.ref));
      await Promise.all(deletePromises);
    } catch (error) {
      // Silenciar errores de limpieza
      console.error('Error en limpieza de notificaciones:', error);
    }
  }

  // Marcar como leída (igual que la app Android)
  async markAsRead(notificationId) {
    try {
      const notificationDocRef = doc(db, 'notifications', notificationId);
      await updateDoc(notificationDocRef, { leida: true });
      
      return { success: true };
    } catch (error) {
      console.error('Error marcando notificación como leída:', error);
      return { success: false, error: error.message };
    }
  }

  // Eliminar notificación
  async deleteNotification(notificationId) {
    try {
      const notificationDocRef = doc(db, 'notifications', notificationId);
      await deleteDoc(notificationDocRef);
      
      return { success: true };
    } catch (error) {
      console.error('Error eliminando notificación:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener notificaciones por usuario (igual que la app Android)
  getNotificationsByUser(userId) {
    return new Promise((resolve, reject) => {
      const notificationsCollection = collection(db, 'notifications');
      const q = query(
        notificationsCollection,
        where('userId', '==', userId),
        orderBy('createdAt', 'desc')
      );
      
      const unsubscribe = onSnapshot(q, (snapshot) => {
        const notifications = [];
        snapshot.forEach(doc => {
          const notificationData = doc.data();
          const notification = Notification.fromMap({ ...notificationData, id: doc.id });
          notifications.push(notification);
        });
        resolve(notifications);
      }, (error) => {
        console.error('Error obteniendo notificaciones por usuario:', error);
        reject(error);
      });

      return unsubscribe;
    });
  }

  // Suscribirse a notificaciones por usuario en tiempo real (igual que la app Android)
  subscribeToNotificationsByUser(userId, callback) {
    const notificationsCollection = collection(db, 'notifications');
    const q = query(
      notificationsCollection,
      where('userId', '==', userId),
      orderBy('createdAt', 'desc')
    );
    
    return onSnapshot(q, (snapshot) => {
      const notifications = [];
      snapshot.forEach(doc => {
        const notificationData = doc.data();
        const notification = Notification.fromMap({ ...notificationData, id: doc.id });
        notifications.push(notification);
      });
      callback(notifications);
    }, (error) => {
      console.error('Error suscribiéndose a notificaciones por usuario:', error);
    });
  }

  // Obtener todas las notificaciones (igual que la app Android)
  getAllNotifications() {
    return new Promise((resolve, reject) => {
      const notificationsCollection = collection(db, 'notifications');
      const q = query(notificationsCollection, orderBy('createdAt', 'desc'));
      
      const unsubscribe = onSnapshot(q, (snapshot) => {
        const notifications = [];
        snapshot.forEach(doc => {
          const notificationData = doc.data();
          const notification = Notification.fromMap({ ...notificationData, id: doc.id });
          notifications.push(notification);
        });
        resolve(notifications);
      }, (error) => {
        console.error('Error obteniendo todas las notificaciones:', error);
        reject(error);
      });

      return unsubscribe;
    });
  }

  // Suscribirse a todas las notificaciones en tiempo real (igual que la app Android)
  subscribeToNotifications(callback) {
    const notificationsCollection = collection(db, 'notifications');
    const q = query(notificationsCollection, orderBy('createdAt', 'desc'));
    
    return onSnapshot(q, (snapshot) => {
      const notifications = [];
      snapshot.forEach(doc => {
        const notificationData = doc.data();
        const notification = Notification.fromMap({ ...notificationData, id: doc.id });
        notifications.push(notification);
      });
      callback(notifications);
    }, (error) => {
      console.error('Error suscribiéndose a notificaciones:', error);
    });
  }
}

export default new NotificationRepository();