import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CardActions,
  Button,
  Grid,
  Chip,
  Fab,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  CircularProgress,
  Divider,
} from '@mui/material';
import {
  Add,
  FilterList,
  Delete,
  Receipt,
  Schedule,
  LocationOn,
  CheckCircle,
  Cancel,
  AttachMoney,
} from '@mui/icons-material';
import GastoRepository from '../../repositories/GastoRepository';
import LocalRepository from '../../repositories/LocalRepository';
import { getCurrentUser } from '../../services/auth';

const GastosTab = ({ user }) => {
  const [gastos, setGastos] = useState([]);
  const [locales, setLocales] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [showFilterDialog, setShowFilterDialog] = useState(false);
  const [filterState, setFilterState] = useState({
    localId: '',
    estado: ''
  });
  const currentUser = getCurrentUser();

  // Cargar datos desde Firebase en tiempo real
  useEffect(() => {
    if (!user || !user.id) return;

    setLoading(true);

    // Suscribirse a todos los gastos (el supervisor solo verá los de sus locales asignados)
    const unsubscribeGastos = GastoRepository.subscribeToGastos((gastos) => {
      console.log('Gastos recibidos de Firebase:', gastos);
      setGastos(gastos);
      setLoading(false);
    });

    // Suscribirse a locales del supervisor en tiempo real
    const unsubscribeLocales = LocalRepository.subscribeToLocalesBySupervisor(user.id, (locales) => {
      console.log('Locales del supervisor recibidos de Firebase:', locales);
      setLocales(locales);
    });

    return () => {
      unsubscribeGastos();
      unsubscribeLocales();
    };
  }, [user]);

  const handleCreateGasto = async (formData) => {
    try {
      const local = locales.find(l => l.id === formData.localId);

      const gastoData = {
        localId: formData.localId,
        localNombre: local?.nombre || 'Desconocido',
        motivo: formData.motivo,
        descripcion: formData.descripcion,
        monto: parseFloat(formData.monto),
        imagenUrl: '',
        estado: 'en_espera', // Los gastos del supervisor siempre empiezan en espera
        observaciones: '',
        supervisorId: user.id, // ID del supervisor que creó el gasto
        supervisorNombre: user.nombre, // Nombre del supervisor que creó el gasto
        createdAt: Date.now(),
        updatedAt: Date.now()
      };

      const result = await GastoRepository.createGasto(gastoData);
      if (result.success) {
        setShowCreateDialog(false);
      } else {
        console.error('Error creando gasto:', result.error);
      }
    } catch (error) {
      console.error('Error creando gasto:', error);
    }
  };

  const handleDeleteGasto = async (id) => {
    try {
      const result = await GastoRepository.deleteGasto(id);
      if (result.success) {
        // Data will update via real-time subscription
      } else {
        console.error('Error eliminando gasto:', result.error);
      }
    } catch (error) {
      console.error('Error eliminando gasto:', error);
    }
  };

  const getFilteredGastos = () => {
    // Obtener IDs de los locales asignados al supervisor
    const localIds = locales.map(l => l.id);
    
    return gastos.filter(gasto => {
      // Solo mostrar gastos de los locales asignados al supervisor
      const belongsToSupervisorLocal = localIds.includes(gasto.localId);
      
      // Mostrar todos los gastos de sus locales (creados por el supervisor O creados por el maestro)
      // Si tiene supervisorId, debe ser del supervisor actual
      const belongsToThisSupervisor = !gasto.supervisorId || gasto.supervisorId === user.id;
      
      // Aplicar filtros adicionales
      const matchesLocal = filterState.localId === '' || gasto.localId === filterState.localId;
      const matchesEstado = filterState.estado === '' || gasto.estado === filterState.estado;
      
      return belongsToSupervisorLocal && belongsToThisSupervisor && matchesLocal && matchesEstado;
    }).sort((a, b) => b.createdAt - a.createdAt);
  };

  const getEstadoColor = (estado) => {
    switch (estado) {
      case 'en_espera': return 'warning';
      case 'aprobado': return 'success';
      case 'rechazado': return 'error';
      default: return 'default';
    }
  };

  const getEstadoLabel = (estado) => {
    switch (estado) {
      case 'en_espera': return 'En Espera';
      case 'aprobado': return 'Aprobado';
      case 'rechazado': return 'Rechazado';
      default: return estado;
    }
  };

  const getEstadoIcon = (estado) => {
    switch (estado) {
      case 'en_espera': return <Schedule fontSize="small" />;
      case 'aprobado': return <CheckCircle fontSize="small" />;
      case 'rechazado': return <Cancel fontSize="small" />;
      default: return null;
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Cargando gastos...</Typography>
      </Box>
    );
  }

  const filteredGastos = getFilteredGastos();

  return (
    <Box sx={{ p: 2 }}>
      {/* Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5" sx={{ fontWeight: 600 }}>
          Mis Gastos
        </Typography>
        <Box>
          <Button
            variant="outlined"
            startIcon={<FilterList />}
            onClick={() => setShowFilterDialog(true)}
            sx={{ mr: 1 }}
          >
            Filtros
          </Button>
          <Fab
            color="primary"
            size="medium"
            onClick={() => setShowCreateDialog(true)}
          >
            <Add />
          </Fab>
        </Box>
      </Box>

      {/* Filtros Activos */}
      <Box sx={{ mb: 2 }}>
        <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>Filtros activos:</Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          {filterState.localId && (
            <Chip
              label={`Local: ${locales.find(l => l.id === filterState.localId)?.nombre || 'Desconocido'}`}
              onDelete={() => setFilterState(prev => ({ ...prev, localId: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {filterState.estado && (
            <Chip
              label={`Estado: ${getEstadoLabel(filterState.estado)}`}
              onDelete={() => setFilterState(prev => ({ ...prev, estado: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {!filterState.localId && !filterState.estado && (
            <Typography variant="body2" color="text.secondary">Ninguno</Typography>
          )}
        </Box>
      </Box>

      {/* Lista de Gastos */}
      {filteredGastos.length === 0 ? (
        <Card sx={{ textAlign: 'center', py: 4 }}>
          <CardContent>
            <Typography variant="h6" color="text.secondary">
              No hay gastos que coincidan con los filtros.
            </Typography>
            <Button
              variant="contained"
              startIcon={<Add />}
              onClick={() => setShowCreateDialog(true)}
              sx={{ mt: 2 }}
            >
              Crear Nuevo Gasto
            </Button>
          </CardContent>
        </Card>
      ) : (
        <Grid container spacing={2}>
          {filteredGastos.map((gasto) => (
            <Grid item xs={12} sm={6} md={4} key={gasto.id}>
              <GastoCard
                gasto={gasto}
                onDelete={() => handleDeleteGasto(gasto.id)}
                getEstadoColor={getEstadoColor}
                getEstadoLabel={getEstadoLabel}
                getEstadoIcon={getEstadoIcon}
              />
            </Grid>
          ))}
        </Grid>
      )}

      {/* Dialog para Crear Gasto */}
      <CreateGastoDialog
        open={showCreateDialog}
        onClose={() => setShowCreateDialog(false)}
        onSubmit={handleCreateGasto}
        locales={locales}
      />

      {/* Dialog para Filtros */}
      <FilterGastosDialog
        open={showFilterDialog}
        onClose={() => setShowFilterDialog(false)}
        filterState={filterState}
        onFilterChange={setFilterState}
        locales={locales}
      />
    </Box>
  );
};

const GastoCard = ({ gasto, onDelete, getEstadoColor, getEstadoLabel, getEstadoIcon }) => {
  return (
    <Card sx={{ '&:hover': { boxShadow: 4 }, height: '100%', display: 'flex', flexDirection: 'column' }}>
      <CardContent sx={{ flexGrow: 1 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 2 }}>
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            {gasto.motivo}
          </Typography>
          <Chip
            label={getEstadoLabel(gasto.estado)}
            color={getEstadoColor(gasto.estado)}
            size="small"
            icon={getEstadoIcon(gasto.estado)}
          />
        </Box>

        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          {gasto.descripcion}
        </Typography>

        <Box sx={{ mb: 2 }}>
          <Typography variant="body2" color="text.secondary" sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
            <LocationOn fontSize="small" sx={{ mr: 0.5 }} />
            {gasto.localNombre}
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ display: 'flex', alignItems: 'center' }}>
            <AttachMoney fontSize="small" sx={{ mr: 0.5 }} />
            ${gasto.monto?.toLocaleString('es-AR', { minimumFractionDigits: 2 }) || '0.00'}
          </Typography>
        </Box>

        {gasto.observaciones && (
          <Box sx={{ mb: 2 }}>
            <Typography variant="caption" color="text.secondary">
              Observaciones: {gasto.observaciones}
            </Typography>
          </Box>
        )}

        <Divider sx={{ my: 1 }} />

        <Typography variant="caption" color="text.secondary">
          {new Date(gasto.createdAt).toLocaleDateString('es-AR')}
        </Typography>
      </CardContent>
      <CardActions>
        <Button size="small" color="error" startIcon={<Delete />} onClick={onDelete}>
          Eliminar
        </Button>
      </CardActions>
    </Card>
  );
};

const CreateGastoDialog = ({ open, onClose, onSubmit, locales }) => {
  const [formData, setFormData] = useState({
    localId: '',
    motivo: '',
    descripcion: '',
    monto: ''
  });

  useEffect(() => {
    if (!open) {
      setFormData({
        localId: '',
        motivo: '',
        descripcion: '',
        monto: ''
      });
    }
  }, [open]);

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit(formData);
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle>Crear Nuevo Gasto</DialogTitle>
      <form onSubmit={handleSubmit}>
        <DialogContent>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth required>
                <InputLabel>Local *</InputLabel>
                <Select
                  value={formData.localId}
                  onChange={(e) => setFormData(prev => ({ ...prev, localId: e.target.value }))}
                  label="Local *"
                >
                  <MenuItem value="">Seleccionar local</MenuItem>
                  {locales.map(local => (
                    <MenuItem key={local.id} value={local.id}>{local.nombre}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Motivo *"
                value={formData.motivo}
                onChange={(e) => setFormData(prev => ({ ...prev, motivo: e.target.value }))}
                required
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Descripción"
                multiline
                rows={3}
                value={formData.descripcion}
                onChange={(e) => setFormData(prev => ({ ...prev, descripcion: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Monto *"
                type="number"
                value={formData.monto}
                onChange={(e) => setFormData(prev => ({ ...prev, monto: e.target.value }))}
                required
                inputProps={{ min: 0, step: 0.01 }}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancelar</Button>
          <Button type="submit" variant="contained">
            Crear Gasto
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  );
};

const FilterGastosDialog = ({ open, onClose, filterState, onFilterChange, locales }) => {
  const [currentFilters, setCurrentFilters] = useState(filterState);

  useEffect(() => {
    setCurrentFilters(filterState);
  }, [filterState]);

  const handleFilterChange = (field) => (event) => {
    setCurrentFilters(prev => ({ ...prev, [field]: event.target.value }));
  };

  const handleApplyFilters = () => {
    onFilterChange(currentFilters);
    onClose();
  };

  const handleClearFilters = () => {
    setCurrentFilters({ localId: '', estado: '' });
    onFilterChange({ localId: '', estado: '' });
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>Filtrar Gastos</DialogTitle>
      <DialogContent>
        <Grid container spacing={2}>
          <Grid item xs={12}>
            <FormControl fullWidth>
              <InputLabel>Local</InputLabel>
              <Select
                value={currentFilters.localId}
                onChange={handleFilterChange('localId')}
                label="Local"
              >
                <MenuItem value="">Todos los locales</MenuItem>
                {locales.map(local => (
                  <MenuItem key={local.id} value={local.id}>{local.nombre}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12}>
            <FormControl fullWidth>
              <InputLabel>Estado</InputLabel>
              <Select
                value={currentFilters.estado}
                onChange={handleFilterChange('estado')}
                label="Estado"
              >
                <MenuItem value="">Todos los estados</MenuItem>
                <MenuItem value="en_espera">En Espera</MenuItem>
                <MenuItem value="aprobado">Aprobado</MenuItem>
                <MenuItem value="rechazado">Rechazado</MenuItem>
              </Select>
            </FormControl>
          </Grid>
        </Grid>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClearFilters}>Limpiar Filtros</Button>
        <Button onClick={handleApplyFilters} variant="contained">Aplicar Filtros</Button>
      </DialogActions>
    </Dialog>
  );
};

export default GastosTab;
