// Modelo Gasto - Exactamente igual que la app Android
class Gasto {
  constructor({
    id = '',
    localId = '',
    localNombre = '',
    motivo = '',
    descripcion = '',
    monto = 0.0,
    imagenUrl = '',
    estado = 'en_espera',
    observaciones = '',
    supervisorId = '',
    supervisorNombre = '',
    createdAt = Date.now(),
    updatedAt = Date.now()
  } = {}) {
    this.id = id;
    this.localId = localId;
    this.localNombre = localNombre;
    this.motivo = motivo;
    this.descripcion = descripcion;
    this.monto = monto;
    this.imagenUrl = imagenUrl;
    this.estado = estado;
    this.observaciones = observaciones;
    this.supervisorId = supervisorId;
    this.supervisorNombre = supervisorNombre;
    this.createdAt = createdAt;
    this.updatedAt = updatedAt;
  }

  toMap() {
    return {
      id: this.id,
      localId: this.localId,
      localNombre: this.localNombre,
      motivo: this.motivo,
      descripcion: this.descripcion,
      monto: this.monto,
      imagenUrl: this.imagenUrl,
      estado: this.estado,
      observaciones: this.observaciones,
      supervisorId: this.supervisorId,
      supervisorNombre: this.supervisorNombre,
      createdAt: this.createdAt,
      updatedAt: this.updatedAt
    };
  }

  static fromMap(map) {
    return new Gasto({
      id: map.id || '',
      localId: map.localId || '',
      localNombre: map.localNombre || '',
      motivo: map.motivo || '',
      descripcion: map.descripcion || '',
      monto: map.monto || 0.0,
      imagenUrl: map.imagenUrl || '',
      estado: map.estado || 'en_espera',
      observaciones: map.observaciones || '',
      supervisorId: map.supervisorId || '',
      supervisorNombre: map.supervisorNombre || '',
      createdAt: map.createdAt || Date.now(),
      updatedAt: map.updatedAt || Date.now()
    });
  }
}

export default Gasto;