// Repositorio de Usuarios - Conecta con Firebase real
import { db } from '../services/firebase';
import { collection, doc, getDoc, setDoc, updateDoc, deleteDoc, getDocs, query, where, onSnapshot } from 'firebase/firestore';
import User from '../models/User';

class UserRepository {
  // Crear usuario
  async createUser(user, password) {
    try {
      // Usar el username como ID del documento
      const userId = user.username;
      
      // Verificar si el documento ya existe
      const userDocRef = doc(db, 'users', userId);
      const existingDoc = await getDoc(userDocRef);

      if (existingDoc.exists()) {
        throw new Error('El nombre de usuario ya existe');
      }

      // Si es un objeto plano, usarlo directamente; si tiene toMap, convertirlo
      const userData = typeof user.toMap === 'function' 
        ? user.toMap() 
        : user;
      
      userData.password = password;

      await setDoc(userDocRef, userData);
      return { success: true, id: userId };
    } catch (error) {
      console.error('Error creando usuario:', error);
      return { success: false, error: error.message };
    }
  }

  // Actualizar usuario
  async updateUser(userId, user, password = null) {
    try {
      // Si es un objeto plano, usarlo directamente; si tiene toMap, convertirlo
      const userData = typeof user.toMap === 'function' 
        ? user.toMap() 
        : user;
      
      if (password && password.length > 0) {
        userData.password = password;
      }

      const userDocRef = doc(db, 'users', userId);
      await updateDoc(userDocRef, userData);
      return { success: true };
    } catch (error) {
      console.error('Error actualizando usuario:', error);
      return { success: false, error: error.message };
    }
  }

  // Eliminar usuario
  async deleteUser(userId) {
    try {
      const userDocRef = doc(db, 'users', userId);
      await deleteDoc(userDocRef);
      return { success: true };
    } catch (error) {
      console.error('Error eliminando usuario:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener usuario por ID
  async getUserById(userId) {
    try {
      const userDocRef = doc(db, 'users', userId);
      const userDoc = await getDoc(userDocRef);

      if (!userDoc.exists()) {
        return { success: false, error: 'Usuario no encontrado' };
      }

      const userData = userDoc.data();
      const user = User.fromMap(userData);
      return { success: true, user };
    } catch (error) {
      console.error('Error obteniendo usuario:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener todos los usuarios
  async getAllUsers() {
    try {
      const usersCollection = collection(db, 'users');
      const usersSnapshot = await getDocs(usersCollection);
      
      const users = [];
      usersSnapshot.forEach(doc => {
        const userData = doc.data();
        const user = User.fromMap({ ...userData, id: doc.id });
        users.push(user);
      });

      return { success: true, users };
    } catch (error) {
      console.error('Error obteniendo usuarios:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener usuarios por rol
  async getUsersByRole(role) {
    try {
      const usersCollection = collection(db, 'users');
      const q = query(usersCollection, where('rol', '==', role));
      const usersSnapshot = await getDocs(q);
      
      const users = [];
      usersSnapshot.forEach(doc => {
        const userData = doc.data();
        const user = User.fromMap({ ...userData, id: doc.id });
        users.push(user);
      });

      return { success: true, users };
    } catch (error) {
      console.error('Error obteniendo usuarios por rol:', error);
      return { success: false, error: error.message };
    }
  }

  // Crear usuario maestro si no existe
  async createMasterUser() {
    try {
      const masterUser = new User({
        id: 'admin',
        nombre: 'Admin Maestro',
        username: 'admin',
        rol: 'MAESTRO',
        localesAsignados: [],
        createdAt: Date.now()
      });

      const result = await this.createUser(masterUser, 'admin123');
      if (result.success) {
        console.log('Usuario maestro creado exitosamente');
      }
      return result;
    } catch (error) {
      console.error('Error creando usuario maestro:', error);
      return { success: false, error: error.message };
    }
  }

  // Obtener supervisores en tiempo real (igual que la app Android)
  getSupervisors() {
    return new Promise((resolve, reject) => {
      const usersCollection = collection(db, 'users');
      const q = query(usersCollection, where('rol', '==', 'SUPERVISOR'));
      
      const unsubscribe = onSnapshot(q, (snapshot) => {
        const supervisors = [];
        snapshot.forEach(doc => {
          const userData = doc.data();
          const user = User.fromMap({ ...userData, id: doc.id });
          supervisors.push(user);
        });
        resolve(supervisors);
      }, (error) => {
        console.error('Error obteniendo supervisores:', error);
        reject(error);
      });

      // Retornar función para desuscribirse
      return unsubscribe;
    });
  }

  // Suscribirse a supervisores en tiempo real
  subscribeToSupervisors(callback) {
    const usersCollection = collection(db, 'users');
    const q = query(usersCollection, where('rol', '==', 'SUPERVISOR'));
    
    return onSnapshot(q, (snapshot) => {
      const supervisors = [];
      snapshot.forEach(doc => {
        const userData = doc.data();
        const user = User.fromMap({ ...userData, id: doc.id });
        supervisors.push(user);
      });
      callback(supervisors);
    }, (error) => {
      console.error('Error suscribiéndose a supervisores:', error);
    });
  }
}

export default new UserRepository();
