import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  CardContent,
  TextField,
  Button,
  Typography,
  InputAdornment,
  IconButton,
  Alert,
  CircularProgress,
  FormControlLabel,
  Checkbox,
} from '@mui/material';
import { Visibility, VisibilityOff, Person, Lock } from '@mui/icons-material';
import { login, checkFirebaseConnection } from '../../services/auth';
import { debugUser } from '../../debug-user';

const LoginScreen = ({ onLogin }) => {
  const [formData, setFormData] = useState({
    username: '',
    password: '',
  });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [checkingConnection, setCheckingConnection] = useState(false);
  const [error, setError] = useState('');
  const [rememberCredentials, setRememberCredentials] = useState(false);

  // Cargar credenciales guardadas al inicializar
  useEffect(() => {
    const savedCredentials = localStorage.getItem('adminSE_credentials');
    const savedRemember = localStorage.getItem('adminSE_remember');
    
    if (savedCredentials && savedRemember === 'true') {
      try {
        const credentials = JSON.parse(savedCredentials);
        setFormData({
          username: credentials.username || '',
          password: credentials.password || '',
        });
        setRememberCredentials(true);
      } catch (error) {
        console.error('Error al cargar credenciales guardadas:', error);
      }
    }
  }, []);

  // Guardar credenciales en localStorage
  const saveCredentials = (username, password) => {
    if (rememberCredentials) {
      const credentials = { username, password };
      localStorage.setItem('adminSE_credentials', JSON.stringify(credentials));
      localStorage.setItem('adminSE_remember', 'true');
    } else {
      localStorage.removeItem('adminSE_credentials');
      localStorage.removeItem('adminSE_remember');
    }
  };

  const handleInputChange = (field) => (event) => {
    setFormData(prev => ({
      ...prev,
      [field]: event.target.value
    }));
    setError(''); // Limpiar error al escribir
  };


  const handleSubmit = async (event) => {
    event.preventDefault();
    
    if (!formData.username || !formData.password) {
      setError('Por favor completa todos los campos');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Primero verificar conexión
      setCheckingConnection(true);
      await checkFirebaseConnection();
      setCheckingConnection(false);

      // Luego hacer login
      const user = await login(formData.username, formData.password);
      
      // Guardar credenciales si está marcado recordar
      saveCredentials(formData.username, formData.password);
      
      onLogin(user);
    } catch (err) {
      setError(err.message);
      setLoading(false);
      setCheckingConnection(false);
    }
  };

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };

  return (
    <Box
      sx={{
        minHeight: '100vh',
        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 2,
      }}
    >
      <Card sx={{ maxWidth: 400, width: '100%', borderRadius: 3 }}>
        <CardContent sx={{ p: 4 }}>
          {/* Logo/Header */}
          <Box sx={{ textAlign: 'center', mb: 4 }}>
            <Box sx={{ mb: 2 }}>
              <img 
                src="./logo_sabores_real.png" 
                alt="Sabores Express" 
                style={{
                  maxWidth: '120px',
                  maxHeight: '120px',
                  objectFit: 'contain',
                  margin: '0 auto',
                  display: 'block'
                }}
              />
            </Box>
            <Typography variant="h4" component="h1" gutterBottom color="primary" sx={{ fontWeight: 600 }}>
              🚀 Administración
            </Typography>
            <Typography variant="subtitle1" color="text.secondary">
              Sistema de Gestión de Locales
            </Typography>
          </Box>

          {/* Formulario */}
          <Box component="form" onSubmit={handleSubmit}>
            <TextField
              fullWidth
              label="Usuario"
              type="text"
              value={formData.username}
              onChange={handleInputChange('username')}
              margin="normal"
              required
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Person color="action" />
                  </InputAdornment>
                ),
              }}
              disabled={loading || checkingConnection}
            />

            <TextField
              fullWidth
              label="Contraseña"
              type={showPassword ? 'text' : 'password'}
              value={formData.password}
              onChange={handleInputChange('password')}
              margin="normal"
              required
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Lock color="action" />
                  </InputAdornment>
                ),
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      onClick={togglePasswordVisibility}
                      edge="end"
                      disabled={loading || checkingConnection}
                    >
                      {showPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />

            {/* Checkbox para recordar credenciales */}
            <FormControlLabel
              control={
                <Checkbox
                  checked={rememberCredentials}
                  onChange={(e) => setRememberCredentials(e.target.checked)}
                  disabled={loading || checkingConnection}
                  color="primary"
                />
              }
              label="Recordar credenciales"
              sx={{ mt: 1, mb: 1 }}
            />

            {/* Error Alert */}
            {error && (
              <Alert severity="error" sx={{ mt: 2, borderRadius: 2 }}>
                {error}
              </Alert>
            )}

            {/* Login Button */}
            <Button
              type="submit"
              fullWidth
              variant="contained"
              size="large"
              disabled={loading || checkingConnection}
              sx={{ 
                mt: 3, 
                mb: 2, 
                py: 1.5,
                fontSize: '1.1rem',
                fontWeight: 500,
              }}
            >
              {checkingConnection ? (
                <>
                  <CircularProgress size={20} sx={{ mr: 1, color: 'white' }} />
                  Conectando...
                </>
              ) : loading ? (
                <>
                  <CircularProgress size={20} sx={{ mr: 1, color: 'white' }} />
                  Iniciando sesión...
                </>
              ) : (
                'Iniciar Sesión'
              )}
            </Button>

            {/* Botón ir a Product Mix */}
            <Button
              fullWidth
              variant="contained"
              size="medium"
              onClick={() => window.location.href = '/Product-Mix/'}
              sx={{ 
                mb: 2, 
                py: 1.2,
                fontSize: '0.95rem',
                fontWeight: 500,
                backgroundColor: '#FFD700',
                color: '#000000',
                border: '2px solid #FFD700',
                '&:hover': {
                  backgroundColor: '#FFC107',
                  borderColor: '#FFC107',
                },
              }}
            >
              🛒 Ir a Product Mix
            </Button>
          </Box>

          {/* Información de derechos */}
          <Box sx={{ mt: 3, p: 2, bgcolor: 'grey.50', borderRadius: 2 }}>
            <Typography variant="body2" color="text.secondary" sx={{ fontWeight: 500, mb: 1 }}>
              📄 Información del Sistema
            </Typography>
            <Typography variant="caption" display="block" sx={{ mb: 0.5 }}>
              <strong>Versión:</strong> 1.0.0
            </Typography>
            <Typography variant="caption" display="block" sx={{ mb: 0.5 }}>
              <strong>Desarrollado:</strong> Lucas Gonzalez
            </Typography>
            <Typography variant="caption" display="block" sx={{ mb: 1 }}>
              <strong>Licencia:</strong> Prototipo/Demo - Fines educativos
            </Typography>
            
            <Typography variant="caption" color="text.secondary" sx={{ fontStyle: 'italic' }}>
              Desarrollado con ❤️ usando React y Material-UI
            </Typography>
          </Box>
        </CardContent>
      </Card>
    </Box>
  );
};

export default LoginScreen;
