import React, { useState, useEffect, useMemo } from 'react';
import { useTheme } from '@mui/material/styles';
import { useMediaQuery } from '@mui/material';
import {
  Box, Typography, Card, CardContent, CardActions, Button, Chip, Fab, Dialog, DialogTitle, DialogContent, DialogActions,
  TextField, FormControl, InputLabel, Select, MenuItem, Switch, FormControlLabel, Grid, CircularProgress,
  Avatar, Divider, List, ListItem, ListItemText, ListItemAvatar, IconButton, Badge, Menu
} from '@mui/material';
import {
  Add, FilterList, Edit, Delete, Assignment, Schedule, Person, LocationOn, Warning, CheckCircle, Cancel, Chat, Send, Image as ImageIcon, AttachFile
} from '@mui/icons-material';
import PendienteRepository from '../../repositories/PendienteRepository';
import LocalRepository from '../../repositories/LocalRepository';
import UserRepository from '../../repositories/UserRepository';
import { getCurrentUser } from '../../services/auth';
import ImageUploadDialog from '../Common/ImageUploadDialog';
import ImageGallery from '../Common/ImageGallery';
import { useToast } from '../../hooks/useToast';

const PendientesTab = ({ user }) => {
  const [pendientes, setPendientes] = useState([]);
  const [locales, setLocales] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [editingPendiente, setEditingPendiente] = useState(null);
  const [showFilterDialog, setShowFilterDialog] = useState(false);
  const [filterState, setFilterState] = useState({
    supervisorId: '',
    localId: '',
    area: '',
    urgencia: '',
    estado: ''
  });
  const [showCompletedPendientes, setShowCompletedPendientes] = useState(false);
  const [showImageUpload, setShowImageUpload] = useState(false);
  const [selectedPendienteForImages, setSelectedPendienteForImages] = useState(null);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const currentUser = getCurrentUser();
  const toast = useToast();

  // Cargar datos desde Firebase en tiempo real (igual que la app Android)
  useEffect(() => {
    setLoading(true);

    // Suscribirse a pendientes en tiempo real
    const unsubscribePendientes = PendienteRepository.subscribeToPendientes((pendientes) => {
      console.log('Pendientes recibidos de Firebase:', pendientes);
      setPendientes(pendientes);
    });

    // Suscribirse a locales en tiempo real
    const unsubscribeLocales = LocalRepository.subscribeToLocales((locales) => {
      console.log('Locales recibidos de Firebase:', locales);
      setLocales(locales);
    });

    // Suscribirse a supervisores en tiempo real
    const unsubscribeSupervisors = UserRepository.subscribeToSupervisors((supervisors) => {
      console.log('Supervisores recibidos de Firebase:', supervisors);
      setSupervisors(supervisors);
    });

    setLoading(false);

    return () => {
      unsubscribePendientes();
      unsubscribeLocales();
      unsubscribeSupervisors();
    };
  }, []);

  const handleCreatePendiente = async (formData) => {
    try {
      const local = locales.find(l => l.id === formData.localId);
      const supervisor = supervisors.find(s => s.id === formData.supervisorId);

      // Si hay observación inicial, se convierte en la primera observación (igual que la app Android)
      const observacionesIniciales = formData.observacionInicial ? [{
        id: `initial_${Date.now()}`,
        mensaje: formData.observacionInicial,
        enviadoPor: currentUser.id,
        enviadoPorNombre: currentUser.nombre,
        rol: "MAESTRO",
        timestamp: Date.now()
      }] : [];

      // Convertir fechaLimite correctamente a timestamp en zona horaria local
      let fechaLimiteTimestamp = 0;
      if (formData.fechaLimite) {
        const [year, month, day] = formData.fechaLimite.split('-').map(Number);
        const fecha = new Date(year, month - 1, day, 23, 59, 59, 999);
        fechaLimiteTimestamp = fecha.getTime();
      }

      const pendienteData = {
        localId: formData.localId,
        localNombre: local?.nombre || 'Desconocido',
        supervisorId: formData.supervisorId,
        supervisorNombre: supervisor?.nombre || 'Desconocido',
        creadoPor: currentUser.id,
        creadoPorNombre: currentUser.nombre,
        descripcion: formData.descripcion, // El título va en descripción
        estado: "asignado",
        prioridad: "media",
        area: formData.area,
        urgencia: formData.urgencia === 'true',
        fechaLimite: fechaLimiteTimestamp,
        observaciones: observacionesIniciales,
        createdAt: Date.now(),
        updatedAt: Date.now()
      };

      const result = await PendienteRepository.createPendiente(pendienteData);
      if (result.success) {
        setShowCreateDialog(false);
        // Data will update via real-time subscription
      } else {
        console.error('Error creando pendiente:', result.error);
      }
    } catch (error) {
      console.error('Error creando pendiente:', error);
    }
  };

  const handleUpdatePendiente = async (id, formData) => {
    try {
      const local = locales.find(l => l.id === formData.localId);
      const supervisor = supervisors.find(s => s.id === formData.supervisorId);

      // Convertir fechaLimite correctamente a timestamp en zona horaria local
      let fechaLimiteTimestamp = 0;
      if (formData.fechaLimite) {
        const [year, month, day] = formData.fechaLimite.split('-').map(Number);
        const fecha = new Date(year, month - 1, day, 23, 59, 59, 999);
        fechaLimiteTimestamp = fecha.getTime();
      }

      const updatedData = {
        descripcion: formData.descripcion,
        localId: formData.localId,
        localNombre: local?.nombre || 'Desconocido',
        supervisorId: formData.supervisorId,
        supervisorNombre: supervisor?.nombre || 'Desconocido',
        area: formData.area,
        urgencia: formData.urgencia === 'true',
        estado: formData.estado,
        fechaLimite: fechaLimiteTimestamp,
        updatedAt: Date.now()
      };

      const result = await PendienteRepository.updatePendiente(id, updatedData);
      if (result.success) {
        setEditingPendiente(null);
        // Data will update via real-time subscription
      } else {
        console.error('Error actualizando pendiente:', result.error);
      }
    } catch (error) {
      console.error('Error actualizando pendiente:', error);
    }
  };

  const handleDeletePendiente = async (id) => {
    try {
      const result = await PendienteRepository.deletePendiente(id);
      if (result.success) {
        // Data will update via real-time subscription
      } else {
        console.error('Error eliminando pendiente:', result.error);
      }
    } catch (error) {
      console.error('Error eliminando pendiente:', error);
    }
  };

  const handleAddObservation = async (pendienteId, message) => {
    try {
      const result = await PendienteRepository.addObservation(pendienteId, {
        id: Date.now().toString(),
        enviadoPor: currentUser.id,
        enviadoPorNombre: currentUser.nombre,
        rol: currentUser.rol,
        timestamp: Date.now(),
        mensaje: message,
        tipo: 'texto'
      });
      if (result.success) {
        // Data will update via real-time subscription
      } else {
        console.error('Error añadiendo observación:', result.error);
      }
    } catch (error) {
      console.error('Error añadiendo observación:', error);
    }
  };

  const handleOpenImageUpload = (pendiente) => {
    setSelectedPendienteForImages(pendiente);
    setShowImageUpload(true);
  };

  const handleCloseImageUpload = () => {
    setShowImageUpload(false);
    setSelectedPendienteForImages(null);
  };

  const handleImageUploadComplete = async (uploadedImages) => {
    if (!selectedPendienteForImages) return;

    try {
      console.log('🟢 MAESTRO - Imágenes recibidas:', uploadedImages);
      
      const imageObservation = {
        id: Date.now().toString(),
        enviadoPor: currentUser.id,
        enviadoPorNombre: currentUser.nombre,
        rol: currentUser.rol,
        timestamp: Date.now(),
        mensaje: '',
        tipo: 'imagenes',
        imagenes: uploadedImages
      };

      console.log('🟢 MAESTRO - Observación a guardar:', imageObservation);
      const result = await PendienteRepository.addObservation(selectedPendienteForImages.id, imageObservation);
      
      if (result.success) {
        toast.showSuccess(`${uploadedImages.length} imagen(es) agregada(s) al chat`);
        handleCloseImageUpload();
      } else {
        console.error('Error agregando imágenes:', result.error);
        toast.showError('Error al agregar las imágenes al chat');
      }
    } catch (error) {
      console.error('Error agregando imágenes:', error);
      toast.showError('Error al agregar las imágenes al chat');
    }
  };

  const handleUpdateEstado = async (pendienteId, nuevoEstado) => {
    try {
      const result = await PendienteRepository.updatePendiente(pendienteId, {
        estado: nuevoEstado,
        updatedAt: Date.now()
      });
      if (result.success) {
        // Data will update via real-time subscription
      } else {
        console.error('Error actualizando estado:', result.error);
      }
    } catch (error) {
      console.error('Error actualizando estado:', error);
    }
  };

  const getFilteredPendientes = useMemo(() => {
    let currentPendientes = pendientes;

    // Filtrar pendientes completados y cancelados si el switch está desactivado
    if (!showCompletedPendientes) {
      currentPendientes = currentPendientes.filter(p => p.estado !== 'realizado' && p.estado !== 'cancelado');
    }

    return currentPendientes.filter(pendiente => {
      const matchesSupervisor = filterState.supervisorId === '' || pendiente.supervisorId === filterState.supervisorId;
      const matchesLocal = filterState.localId === '' || pendiente.localId === filterState.localId;
      const matchesArea = filterState.area === '' || pendiente.area === filterState.area;
      const matchesUrgencia = filterState.urgencia === '' || pendiente.urgencia.toString() === filterState.urgencia;
      const matchesEstado = filterState.estado === '' || pendiente.estado === filterState.estado;

      return matchesSupervisor && matchesLocal && matchesArea && matchesUrgencia && matchesEstado;
    }).sort((a, b) => {
      // Sort by urgency (urgent first)
      if (a.urgencia && !b.urgencia) return -1;
      if (!a.urgencia && b.urgencia) return 1;

      // Then by creation date (newest first)
      return b.createdAt - a.createdAt;
    });
  }, [pendientes, filterState, showCompletedPendientes]);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Cargando pendientes...</Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ p: { xs: 1.5, sm: 2 } }}>
      {/* Header y Botones */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: { xs: 2, sm: 3 } }}>
        <Typography 
          variant="h5" 
          sx={{ 
            fontWeight: 600,
            fontSize: { xs: '1.25rem', sm: '1.5rem' }
          }}
        >
          Pendientes
        </Typography>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: { xs: 0.5, sm: 1 } }}>
          <Button
            variant="outlined"
            size={isMobile ? 'small' : 'medium'}
            startIcon={<FilterList />}
            onClick={() => setShowFilterDialog(true)}
            sx={{ display: 'inline-flex' }}
          >
            Filtros
          </Button>
          <Fab
            color="primary"
            size={isMobile ? 'small' : 'medium'}
            onClick={() => setShowCreateDialog(true)}
            sx={{ position: 'fixed', bottom: { xs: 88, sm: 16 }, right: 16 }}
          >
            <Add />
          </Fab>
        </Box>
      </Box>

      {/* Filtros Activos */}
      <Box sx={{ mb: 2 }}>
        <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>Filtros activos:</Typography>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          {filterState.supervisorId && (
            <Chip
              label={`Supervisor: ${supervisors.find(s => s.id === filterState.supervisorId)?.nombre || 'Desconocido'}`}
              onDelete={() => setFilterState(prev => ({ ...prev, supervisorId: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {filterState.localId && (
            <Chip
              label={`Local: ${locales.find(l => l.id === filterState.localId)?.nombre || 'Desconocido'}`}
              onDelete={() => setFilterState(prev => ({ ...prev, localId: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {filterState.area && (
            <Chip
              label={`Área: ${filterState.area}`}
              onDelete={() => setFilterState(prev => ({ ...prev, area: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {filterState.urgencia !== '' && (
            <Chip
              label={`Urgencia: ${filterState.urgencia === 'true' ? 'Sí' : 'No'}`}
              onDelete={() => setFilterState(prev => ({ ...prev, urgencia: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {filterState.estado && (
            <Chip
              label={`Estado: ${filterState.estado}`}
              onDelete={() => setFilterState(prev => ({ ...prev, estado: '' }))}
              color="primary"
              variant="outlined"
            />
          )}
          {!filterState.supervisorId && !filterState.localId && !filterState.area && filterState.urgencia === '' && !filterState.estado && (
            <Typography variant="body2" color="text.secondary">Ninguno</Typography>
          )}
        </Box>
      </Box>

      {/* Toggle para Pendientes Completados */}
      <FormControlLabel
        control={
          <Switch
            checked={showCompletedPendientes}
            onChange={(e) => setShowCompletedPendientes(e.target.checked)}
          />
        }
        label="Mostrar pendientes completados"
        sx={{ mb: 2 }}
      />

      {/* Lista de Pendientes */}
      {getFilteredPendientes.length === 0 ? (
        <Card sx={{ textAlign: 'center', py: 4 }}>
          <CardContent>
            <Typography variant="h6" color="text.secondary">
              No hay pendientes que coincidan con los filtros.
            </Typography>
            <Button
              variant="contained"
              startIcon={<Add />}
              onClick={() => setShowCreateDialog(true)}
              sx={{ mt: 2 }}
            >
              Crear Nuevo Pendiente
            </Button>
          </CardContent>
        </Card>
      ) : (
        <Grid container spacing={2}>
          {getFilteredPendientes.map((pendiente) => (
            <Grid item xs={12} sm={6} md={4} key={pendiente.id}>
              <PendienteCard
                pendiente={pendiente}
                onEdit={() => setEditingPendiente(pendiente)}
                onDelete={() => handleDeletePendiente(pendiente.id)}
                onAddObservation={handleAddObservation}
                onUpdateEstado={handleUpdateEstado}
                onOpenImageUpload={() => handleOpenImageUpload(pendiente)}
                currentUser={currentUser}
              />
            </Grid>
          ))}
        </Grid>
      )}

      {/* Dialog para Crear/Editar Pendiente */}
      <CreateEditPendienteDialog
        open={showCreateDialog || !!editingPendiente}
        onClose={() => {
          setShowCreateDialog(false);
          setEditingPendiente(null);
        }}
        onSubmit={editingPendiente ? (data) => handleUpdatePendiente(editingPendiente.id, data) : handleCreatePendiente}
        pendiente={editingPendiente}
        locales={locales}
        supervisors={supervisors}
      />

      {/* Dialog para Filtros */}
      <FilterPendientesDialog
        open={showFilterDialog}
        onClose={() => setShowFilterDialog(false)}
        filterState={filterState}
        onFilterChange={setFilterState}
        locales={locales}
        supervisors={supervisors}
      />

      {/* Diálogo de subida de imágenes */}
      <ImageUploadDialog
        open={showImageUpload}
        onClose={handleCloseImageUpload}
        onUploadComplete={handleImageUploadComplete}
        pendienteId={selectedPendienteForImages?.id}
        existingImages={selectedPendienteForImages?.observaciones?.flatMap(obs => obs.imagenes || []) || []}
      />
    </Box>
  );
};

const PendienteCard = ({ pendiente, onEdit, onDelete, onAddObservation, onUpdateEstado, onOpenImageUpload, currentUser }) => {
  const [newObservation, setNewObservation] = useState('');
  const [anchorEl, setAnchorEl] = useState(null);
  const open = Boolean(anchorEl);

  const getEstadoLabel = (estado) => {
    switch (estado) {
      case 'asignado': return 'Asignado';
      case 'en_proceso': return 'En Proceso';
      case 'realizado': return 'Realizado';
      case 'cancelado': return 'Cancelado';
      default: return estado;
    }
  };

  const getEstadoColor = (estado) => {
    switch (estado) {
      case 'asignado': return 'secondary';
      case 'en_proceso': return 'info';
      case 'realizado': return 'success';
      case 'cancelado': return 'error';
      default: return 'default';
    }
  };

  const getUrgenciaColor = (urgencia) => (urgencia ? 'error' : 'default');

  const getStatusIcon = (estado) => {
    switch (estado) {
      case 'asignado': return <Warning fontSize="small" />;
      case 'en_proceso': return <Schedule fontSize="small" />;
      case 'realizado': return <CheckCircle fontSize="small" />;
      case 'cancelado': return <Cancel fontSize="small" />;
      default: return <Warning fontSize="small" />;
    }
  };

  const handleEstadoClick = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleEstadoClose = (nuevoEstado) => {
    setAnchorEl(null);
    if (nuevoEstado) {
      onUpdateEstado(pendiente.id, nuevoEstado);
    }
  };

  const handleAddObservationClick = () => {
    if (newObservation.trim()) {
      onAddObservation(pendiente.id, newObservation);
      setNewObservation('');
    }
  };

  // Determinar si el pendiente fue creado (no es una actualización)
  const isCreatedPendiente = pendiente.estado === 'asignado' && 
                             pendiente.createdAt && 
                             pendiente.updatedAt && 
                             pendiente.createdAt === pendiente.updatedAt;

  return (
    <Card sx={{ '&:hover': { boxShadow: 4 }, height: '100%', display: 'flex', flexDirection: 'column' }}>
      <CardContent sx={{ flexGrow: 1 }}>
        {/* Título grande como en la app Android */}
        <Typography variant="h6" sx={{ fontWeight: 600, mb: 2, fontSize: '1.2rem' }}>
          {pendiente.descripcion}
        </Typography>

        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 1 }}>
          <Box>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 0.5 }}>
              <LocationOn fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
              {pendiente.localNombre}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 0.5 }}>
              <Person fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
              Creado por: {pendiente.creadoPorNombre || 'Desconocido'}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 0.5 }}>
              <Person fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
              Asignado a: {pendiente.supervisorNombre || 'Desconocido'}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
              <Assignment fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
              Área: {pendiente.area}
            </Typography>
            {pendiente.fechaLimite && (
              <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                <Schedule fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
                Límite: {new Date(pendiente.fechaLimite).toLocaleDateString()}
              </Typography>
            )}
          </Box>
          <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 0.5 }}>
            <Chip
              label={getEstadoLabel(pendiente.estado)}
              color={getEstadoColor(pendiente.estado)}
              size="small"
              icon={getStatusIcon(pendiente.estado)}
              onClick={handleEstadoClick}
              sx={{ cursor: 'pointer', '&:hover': { opacity: 0.8 } }}
              title="Clic para cambiar estado"
            />
            {pendiente.urgencia && (
              <Chip
                label="URGENTE"
                color={getUrgenciaColor(pendiente.urgencia)}
                size="small"
                icon={<Warning fontSize="small" />}
              />
            )}
          </Box>
        </Box>

        {/* Menú de estados */}
        <Menu
          anchorEl={anchorEl}
          open={open}
          onClose={() => handleEstadoClose(null)}
        >
          <MenuItem onClick={() => handleEstadoClose('asignado')}>
            Asignado
          </MenuItem>
          <MenuItem onClick={() => handleEstadoClose('en_proceso')}>
            En Proceso
          </MenuItem>
          <MenuItem onClick={() => handleEstadoClose('realizado')}>
            Realizado
          </MenuItem>
          <MenuItem onClick={() => handleEstadoClose('cancelado')}>
            Cancelado
          </MenuItem>
        </Menu>

        <Divider sx={{ my: 1 }} />

        {/* Chat de observaciones siempre visible */}
        <Box sx={{ mb: 1 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
            <Chat fontSize="small" sx={{ mr: 0.5 }} />
            <Typography variant="body2" color="text.secondary">
              Chat ({pendiente.observaciones?.length || 0})
            </Typography>
          </Box>
          
          {pendiente.observaciones && pendiente.observaciones.length > 0 ? (
            <Box sx={{ maxHeight: 150, overflowY: 'auto', p: 1, bgcolor: 'grey.50', borderRadius: 1, mb: 1 }}>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                {pendiente.observaciones.map((obs, index) => {
                  const isCurrentUser = obs.enviadoPor === currentUser.id;
                  
                  return (
                    <Box
                      key={obs.id || index}
                      sx={{
                        display: 'flex',
                        justifyContent: isCurrentUser ? 'flex-end' : 'flex-start',
                        width: '100%',
                      }}
                    >
                      <Card
                        variant="outlined"
                        sx={{
                          maxWidth: obs.tipo === 'imagenes' ? '95%' : '85%',
                          bgcolor: isCurrentUser ? 'primary.main' : 'background.paper',
                          color: isCurrentUser ? 'white' : 'text.primary',
                          p: 1,
                          borderRadius: 2,
                          boxShadow: 1,
                        }}
                      >
                        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 0.5, gap: 1 }}>
                          <Typography variant="caption" sx={{ fontWeight: 'bold', fontSize: '0.7rem' }}>
                            {obs.enviadoPorNombre}
                          </Typography>
                          <Typography variant="caption" sx={{ fontSize: '0.65rem', opacity: 0.8 }}>
                            {new Date(obs.timestamp).toLocaleDateString('es-AR', {
                              day: '2-digit',
                              month: '2-digit',
                              hour: '2-digit',
                              minute: '2-digit'
                            })}
                          </Typography>
                        </Box>
                        {obs.tipo === 'imagenes' && obs.imagenes && obs.imagenes.length > 0 ? (
                          <Box>
                            <ImageGallery 
                              images={obs.imagenes}
                              pendienteId={pendiente.id}
                              canDelete={false}
                            />
                          </Box>
                        ) : (
                          <Typography variant="body2" sx={{ fontSize: '0.8rem' }}>
                            {obs.mensaje}
                          </Typography>
                        )}
                      </Card>
                    </Box>
                  );
                })}
              </Box>
            </Box>
          ) : (
            <Box sx={{ p: 1, bgcolor: 'grey.50', borderRadius: 1, mb: 1 }}>
              <Typography variant="caption" color="text.secondary" sx={{ fontStyle: 'italic' }}>
                No hay observaciones aún
              </Typography>
            </Box>
          )}
          
          <Box sx={{ display: 'flex', gap: 0.5 }}>
            <IconButton 
              size="small" 
              onClick={onOpenImageUpload}
              color="primary"
              title="Subir imagen"
            >
              <AttachFile fontSize="small" />
            </IconButton>
            <TextField
              fullWidth
              size="small"
              placeholder="Escribir observación..."
              value={newObservation}
              onChange={(e) => setNewObservation(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === 'Enter') {
                  handleAddObservationClick();
                }
              }}
            />
            <Button onClick={handleAddObservationClick} variant="contained" size="small" disabled={!newObservation.trim()}>
              <Send fontSize="small" />
            </Button>
          </Box>
        </Box>
      </CardContent>
      <CardActions sx={{ justifyContent: 'flex-end' }}>
        {!isCreatedPendiente && (
          <Button size="small" startIcon={<Edit />} onClick={onEdit}>
            Gestionar
          </Button>
        )}
        <Button size="small" color="error" startIcon={<Delete />} onClick={onDelete}>
          Eliminar
        </Button>
      </CardActions>
    </Card>
  );
};

const CreateEditPendienteDialog = ({ open, onClose, onSubmit, pendiente, locales, supervisors }) => {
  const [formData, setFormData] = useState({
    descripcion: '',
    observacionInicial: '',
    localId: '',
    supervisorId: '',
    area: '',
    urgencia: 'false',
    estado: 'asignado',
    fechaLimite: '',
  });

  useEffect(() => {
    if (pendiente) {
      setFormData({
        descripcion: pendiente.descripcion,
        observacionInicial: pendiente.observaciones?.[0]?.mensaje || '', // Assuming first observation is initial description
        localId: pendiente.localId,
        supervisorId: pendiente.supervisorId,
        area: pendiente.area,
        urgencia: pendiente.urgencia.toString(),
        estado: pendiente.estado,
        fechaLimite: pendiente.fechaLimite ? new Date(pendiente.fechaLimite).toISOString().split('T')[0] : '',
      });
    } else {
      setFormData({
        descripcion: '',
        observacionInicial: '',
        localId: '',
        supervisorId: '',
        area: '',
        urgencia: 'false',
        estado: 'asignado',
        fechaLimite: '',
      });
    }
  }, [pendiente]);

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit(formData);
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle>{pendiente ? 'Gestionar Pendiente' : 'Crear Nuevo Pendiente'}</DialogTitle>
      <form onSubmit={handleSubmit}>
        <DialogContent>
          <Grid container spacing={2}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Descripción del Pendiente *"
                value={formData.descripcion}
                onChange={(e) => setFormData(prev => ({ ...prev, descripcion: e.target.value }))}
                required
              />
            </Grid>
            {!pendiente && ( // Only show initial observation for new pendings
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label="Observación Inicial (Opcional)"
                  multiline
                  rows={3}
                  value={formData.observacionInicial}
                  onChange={(e) => setFormData(prev => ({ ...prev, observacionInicial: e.target.value }))}
                />
              </Grid>
            )}
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth required>
                <InputLabel>Local *</InputLabel>
                <Select
                  value={formData.localId}
                  onChange={(e) => setFormData(prev => ({ ...prev, localId: e.target.value }))}
                  label="Local *"
                >
                  <MenuItem value="">Seleccionar local</MenuItem>
                  {locales.map(local => (
                    <MenuItem key={local.id} value={local.id}>{local.nombre}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth required>
                <InputLabel>Supervisor *</InputLabel>
                <Select
                  value={formData.supervisorId}
                  onChange={(e) => setFormData(prev => ({ ...prev, supervisorId: e.target.value }))}
                  label="Supervisor *"
                >
                  <MenuItem value="">Seleccionar supervisor</MenuItem>
                  {supervisors.map(supervisor => (
                    <MenuItem key={supervisor.id} value={supervisor.id}>{supervisor.nombre}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth required>
                <InputLabel>Área *</InputLabel>
                         <Select
                           value={formData.area}
                           onChange={(e) => setFormData(prev => ({ ...prev, area: e.target.value }))}
                           label="Área *"
                         >
                           <MenuItem value="">Seleccionar área</MenuItem>
                           <MenuItem value="Mantenimiento">Mantenimiento</MenuItem>
                           <MenuItem value="Fabrica">Fabrica</MenuItem>
                           <MenuItem value="R.R.H.H">R.R.H.H</MenuItem>
                           <MenuItem value="Papelera">Papelera</MenuItem>
                           <MenuItem value="Marketing">Marketing</MenuItem>
                           <MenuItem value="Obras">Obras</MenuItem>
                           <MenuItem value="Sistemas">Sistemas</MenuItem>
                           <MenuItem value="Capacitaciones">Capacitaciones</MenuItem>
                           <MenuItem value="Personal">Personal</MenuItem>
                           <MenuItem value="Zonal">Zonal</MenuItem>
                         </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth required>
                <InputLabel>Urgencia *</InputLabel>
                <Select
                  value={formData.urgencia}
                  onChange={(e) => setFormData(prev => ({ ...prev, urgencia: e.target.value }))}
                  label="Urgencia *"
                >
                  <MenuItem value="true">Sí</MenuItem>
                  <MenuItem value="false">No</MenuItem>
                </Select>
              </FormControl>
            </Grid>
                         {pendiente && ( // Only show status for existing pendings
               <Grid item xs={12} sm={6}>
                 <FormControl fullWidth required>
                   <InputLabel>Estado *</InputLabel>
                   <Select
                     value={formData.estado}
                     onChange={(e) => setFormData(prev => ({ ...prev, estado: e.target.value }))}
                     label="Estado *"
                   >
                     <MenuItem value="asignado">Asignado</MenuItem>
                     <MenuItem value="en_proceso">En Proceso</MenuItem>
                     <MenuItem value="realizado">Realizado</MenuItem>
                     <MenuItem value="cancelado">Cancelado</MenuItem>
                   </Select>
                 </FormControl>
               </Grid>
             )}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Fecha Límite"
                type="date"
                value={formData.fechaLimite}
                onChange={(e) => setFormData(prev => ({ ...prev, fechaLimite: e.target.value }))}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancelar</Button>
          <Button type="submit" variant="contained">
            {pendiente ? 'Actualizar' : 'Crear'}
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  );
};

const FilterPendientesDialog = ({ open, onClose, filterState, onFilterChange, locales, supervisors }) => {
  const [currentFilters, setCurrentFilters] = useState(filterState);

  useEffect(() => {
    setCurrentFilters(filterState);
  }, [filterState]);

  const handleFilterChange = (field) => (event) => {
    setCurrentFilters(prev => ({ ...prev, [field]: event.target.value }));
  };

  const handleApplyFilters = () => {
    onFilterChange(currentFilters);
    onClose();
  };

  const handleClearFilters = () => {
    setCurrentFilters({
      supervisorId: '',
      localId: '',
      area: '',
      urgencia: '',
      estado: ''
    });
    onFilterChange({
      supervisorId: '',
      localId: '',
      area: '',
      urgencia: '',
      estado: ''
    });
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>Filtrar Pendientes</DialogTitle>
      <DialogContent>
        <Grid container spacing={2}>
          <Grid item xs={12}>
            <FormControl fullWidth>
              <InputLabel>Supervisor</InputLabel>
              <Select
                value={currentFilters.supervisorId}
                onChange={handleFilterChange('supervisorId')}
                label="Supervisor"
              >
                <MenuItem value="">Todos los supervisores</MenuItem>
                {supervisors.map(supervisor => (
                  <MenuItem key={supervisor.id} value={supervisor.id}>{supervisor.nombre}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12}>
            <FormControl fullWidth>
              <InputLabel>Local</InputLabel>
              <Select
                value={currentFilters.localId}
                onChange={handleFilterChange('localId')}
                label="Local"
              >
                <MenuItem value="">Todos los locales</MenuItem>
                {locales.map(local => (
                  <MenuItem key={local.id} value={local.id}>{local.nombre}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12}>
                     <FormControl fullWidth>
                       <InputLabel>Área</InputLabel>
                       <Select
                         value={currentFilters.area}
                         onChange={handleFilterChange('area')}
                         label="Área"
                       >
                         <MenuItem value="">Todas las áreas</MenuItem>
                         <MenuItem value="Mantenimiento">Mantenimiento</MenuItem>
                         <MenuItem value="Fabrica">Fabrica</MenuItem>
                         <MenuItem value="R.R.H.H">R.R.H.H</MenuItem>
                         <MenuItem value="Papelera">Papelera</MenuItem>
                         <MenuItem value="Marketing">Marketing</MenuItem>
                         <MenuItem value="Obras">Obras</MenuItem>
                         <MenuItem value="Sistemas">Sistemas</MenuItem>
                         <MenuItem value="Capacitaciones">Capacitaciones</MenuItem>
                         <MenuItem value="Personal">Personal</MenuItem>
                         <MenuItem value="Zonal">Zonal</MenuItem>
                       </Select>
                     </FormControl>
          </Grid>
          <Grid item xs={12}>
            <FormControl fullWidth>
              <InputLabel>Urgencia</InputLabel>
              <Select
                value={currentFilters.urgencia}
                onChange={handleFilterChange('urgencia')}
                label="Urgencia"
              >
                <MenuItem value="">Todas</MenuItem>
                <MenuItem value="true">Sí</MenuItem>
                <MenuItem value="false">No</MenuItem>
              </Select>
            </FormControl>
          </Grid>
                     <Grid item xs={12}>
             <FormControl fullWidth>
               <InputLabel>Estado</InputLabel>
               <Select
                 value={currentFilters.estado}
                 onChange={handleFilterChange('estado')}
                 label="Estado"
               >
                 <MenuItem value="">Todos los estados</MenuItem>
                 <MenuItem value="asignado">Asignado</MenuItem>
                 <MenuItem value="en_proceso">En Proceso</MenuItem>
                 <MenuItem value="realizado">Realizado</MenuItem>
                 <MenuItem value="cancelado">Cancelado</MenuItem>
               </Select>
             </FormControl>
           </Grid>
        </Grid>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClearFilters}>Limpiar Filtros</Button>
        <Button onClick={handleApplyFilters} variant="contained">Aplicar Filtros</Button>
      </DialogActions>
    </Dialog>
  );
};

export default PendientesTab;