import React from 'react';

// Función para exportar datos a CSV
export const exportToCSV = (data, filename = 'export.csv') => {
  if (!data || data.length === 0) {
    console.warn('No hay datos para exportar');
    return;
  }

  const headers = Object.keys(data[0]);
  const csvContent = [
    headers.join(','),
    ...data.map(row => 
      headers.map(header => {
        const value = row[header];
        // Escapar comillas y envolver en comillas si contiene comas
        if (typeof value === 'string' && (value.includes(',') || value.includes('"'))) {
          return `"${value.replace(/"/g, '""')}"`;
        }
        return value || '';
      }).join(',')
    )
  ].join('\n');

  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');
  const url = URL.createObjectURL(blob);
  
  link.setAttribute('href', url);
  link.setAttribute('download', filename);
  link.style.visibility = 'hidden';
  
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

// Función para exportar datos a JSON
export const exportToJSON = (data, filename = 'export.json') => {
  if (!data || data.length === 0) {
    console.warn('No hay datos para exportar');
    return;
  }

  const jsonContent = JSON.stringify(data, null, 2);
  const blob = new Blob([jsonContent], { type: 'application/json' });
  const link = document.createElement('a');
  const url = URL.createObjectURL(blob);
  
  link.setAttribute('href', url);
  link.setAttribute('download', filename);
  link.style.visibility = 'hidden';
  
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

// Función para exportar datos a Excel (formato simplificado)
export const exportToExcel = (data, filename = 'export.xlsx') => {
  if (!data || data.length === 0) {
    console.warn('No hay datos para exportar');
    return;
  }

  // Crear un CSV con extensión .xlsx (formato simplificado)
  const headers = Object.keys(data[0]);
  const csvContent = [
    headers.join('\t'),
    ...data.map(row => 
      headers.map(header => {
        const value = row[header];
        return value || '';
      }).join('\t')
    )
  ].join('\n');

  const blob = new Blob([csvContent], { type: 'application/vnd.ms-excel' });
  const link = document.createElement('a');
  const url = URL.createObjectURL(blob);
  
  link.setAttribute('href', url);
  link.setAttribute('download', filename);
  link.style.visibility = 'hidden';
  
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

// Función para generar reporte de pendientes
export const exportPendientesReport = (pendientes, filename = 'reporte_pendientes.csv') => {
  const reportData = pendientes.map(pendiente => ({
    'ID': pendiente.id,
    'Descripción': pendiente.descripcion,
    'Local': pendiente.localNombre,
    'Área': pendiente.area,
    'Estado': pendiente.estado,
    'Urgencia': pendiente.urgencia ? 'Sí' : 'No',
    'Creado por': pendiente.creadoPorNombre,
    'Asignado a': pendiente.supervisorNombre,
    'Fecha creación': pendiente.createdAt ? new Date(pendiente.createdAt).toLocaleDateString('es-AR') : '',
    'Fecha límite': pendiente.fechaLimite ? new Date(pendiente.fechaLimite).toLocaleDateString('es-AR') : '',
    'Observaciones': pendiente.observaciones?.length || 0
  }));

  exportToCSV(reportData, filename);
};

// Función para generar reporte de locales
export const exportLocalesReport = (locales, filename = 'reporte_locales.csv') => {
  const reportData = locales.map(local => ({
    'ID': local.id,
    'Nombre': local.nombre,
    'Dirección': local.direccion,
    'Teléfono': local.telefono,
    'Supervisor': local.supervisorNombre,
    'Estado': local.activo ? 'Activo' : 'Inactivo',
    'Vencimiento Poliza': local.vencimiento_poliza || '',
    'Vencimiento REBA': local.vencimiento_reba || '',
    'Vencimiento Agua': local.vencimiento_agua || '',
    'Vencimiento Matafuegos': local.vencimiento_matafuegos || '',
    'Vencimiento Fumigación': local.vencimiento_fumigacion || ''
  }));

  exportToCSV(reportData, filename);
};

// Función para generar reporte de gastos
export const exportGastosReport = (gastos, filename = 'reporte_gastos.csv') => {
  const reportData = gastos.map(gasto => ({
    'ID': gasto.id,
    'Local': gasto.localNombre,
    'Categoría': gasto.categoria,
    'Descripción': gasto.descripcion,
    'Monto': gasto.monto,
    'Fecha': gasto.fecha ? new Date(gasto.fecha).toLocaleDateString('es-AR') : '',
    'Creado por': gasto.creadoPorNombre,
    'Estado': gasto.aprobado ? 'Aprobado' : 'Pendiente'
  }));

  exportToCSV(reportData, filename);
};

// Hook para manejar exportaciones
export const useExport = () => {
  const exportData = (data, format = 'csv', filename) => {
    const timestamp = new Date().toISOString().split('T')[0];
    const defaultFilename = `export_${timestamp}.${format}`;
    
    switch (format.toLowerCase()) {
      case 'csv':
        exportToCSV(data, filename || defaultFilename);
        break;
      case 'json':
        exportToJSON(data, filename || defaultFilename);
        break;
      case 'excel':
      case 'xlsx':
        exportToExcel(data, filename || defaultFilename);
        break;
      default:
        console.warn('Formato de exportación no soportado:', format);
    }
  };

  return { exportData };
};
