// Repositorio de Imagenes - Guarda imágenes en colección separada
import { db } from '../services/firebase';
import { collection, doc, addDoc, getDoc, deleteDoc, getDocs, query, where } from 'firebase/firestore';

class ImagenRepository {
  /**
   * Guarda una imagen en la colección 'imagenes' y retorna su ID
   * @param {Object} imagen - Datos de la imagen
   * @returns {Promise<{success: boolean, id?: string, error?: string}>}
   */
  async saveImagen(imagen) {
    try {
      const imagenesCollection = collection(db, 'imagenes');
      const docRef = await addDoc(imagenesCollection, imagen);
      return { success: true, id: docRef.id };
    } catch (error) {
      console.error('Error guardando imagen:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Obtiene una imagen por su ID
   * @param {string} imagenId - ID de la imagen
   * @returns {Promise<{success: boolean, imagen?: Object, error?: string}>}
   */
  async getImagenById(imagenId) {
    try {
      const imagenDocRef = doc(db, 'imagenes', imagenId);
      const imagenDoc = await getDoc(imagenDocRef);
      
      if (!imagenDoc.exists()) {
        return { success: false, error: 'Imagen no encontrada' };
      }
      
      return { success: true, imagen: { id: imagenDoc.id, ...imagenDoc.data() } };
    } catch (error) {
      console.error('Error obteniendo imagen:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Elimina una imagen por su ID
   * @param {string} imagenId - ID de la imagen
   * @returns {Promise<{success: boolean, error?: string}>}
   */
  async deleteImagen(imagenId) {
    try {
      const imagenDocRef = doc(db, 'imagenes', imagenId);
      await deleteDoc(imagenDocRef);
      return { success: true };
    } catch (error) {
      console.error('Error eliminando imagen:', error);
      return { success: false, error: error.message };
    }
  }

  /**
   * Obtiene todas las imágenes de un pendiente
   * @param {string} pendienteId - ID del pendiente
   * @returns {Promise<{success: boolean, imagenes?: Array<string>, error?: string}>}
   */
  async getImagenesByPendiente(pendienteId) {
    try {
      const imagenesCollection = collection(db, 'imagenes');
      const q = query(imagenesCollection, where('pendienteId', '==', pendienteId));
      const snapshot = await getDocs(q);
      
      const ids = snapshot.docs.map(doc => doc.id);
      return { success: true, imagenes: ids };
    } catch (error) {
      console.error('Error obteniendo imágenes por pendiente:', error);
      return { success: false, error: error.message };
    }
  }
}

export default new ImagenRepository();

