import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardMedia,
  CardContent,
  IconButton,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Grid,
  Tooltip,
  Alert,
  CircularProgress,
} from '@mui/material';
import {
  Image,
  Delete,
  Download,
  Visibility,
  Close,
  CloudDone,
  Error,
} from '@mui/icons-material';
import { useToast } from '../../hooks/useToast';
import ImagenRepository from '../../repositories/ImagenRepository';

const ImageGallery = ({ images = [], onDeleteImage, pendienteId, canDelete = false }) => {
  const [selectedImage, setSelectedImage] = useState(null);
  const [imageErrors, setImageErrors] = useState({});
  const [loadedImages, setLoadedImages] = useState({}); // Cache de imágenes cargadas
  const [loadingImages, setLoadingImages] = useState({}); // Estado de carga
  const { showSuccess, showError } = useToast();

  const handleImageError = (imageId) => {
    setImageErrors(prev => ({ ...prev, [imageId]: true }));
  };

  // Función auxiliar para obtener imagen completa para descarga (se define temprano)
  const getFullImageData = (image) => {
    if (loadedImages[image.id]) {
      return loadedImages[image.id];
    }
    return image;
  };

  const handleDeleteImage = async (image) => {
    try {
      // Las imágenes se eliminan directamente desde Firestore
      // Solo llamamos al callback del componente padre
      showSuccess('Imagen eliminada correctamente');
      onDeleteImage(image.id);
    } catch (error) {
      console.error('Error eliminando imagen:', error);
      showError('Error eliminando imagen: ' + error.message);
    }
  };

  const handleDownloadImage = async (image) => {
    try {
      // Obtener datos completos de la imagen
      const imageData = getFullImageData(image);
      const url = imageData.url || imageData.thumbnailUrl;
      
      if (!url) {
        showError('Imagen no disponible');
        return;
      }
      
      // Crear enlace de descarga
      const link = document.createElement('a');
      link.href = url;
      link.download = imageData.nombre || imageData.name || image.nombre || image.name || 'imagen.jpg';
      link.target = '_blank';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (error) {
      console.error('Error descargando imagen:', error);
      showError('Error descargando imagen');
    }
  };

  const formatFileSize = (bytes) => {
    if (!bytes) return 'N/A';
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    try {
      return new Date(dateString).toLocaleString('es-ES', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch (error) {
      return 'N/A';
    }
  };

  // Cargar imágenes que no tengan URL (nuevo sistema)
  useEffect(() => {
    const loadImages = async () => {
      for (const image of images) {
        // Si la imagen no tiene URL pero tiene ID, cargarla desde Firestore
        if (!image.url && !image.thumbnailUrl && image.id) {
          // Verificar si ya está cargada o en proceso
          if (loadedImages[image.id] || loadingImages[image.id]) {
            continue;
          }
          
          setLoadingImages(prev => ({ ...prev, [image.id]: true }));
          
          try {
            const result = await ImagenRepository.getImagenById(image.id);
            if (result.success && result.imagen) {
              // Construir data URL para mostrar la imagen
              const dataUrl = `data:${result.imagen.mimeType};base64,${result.imagen.dataBase64}`;
              const thumbnailUrl = result.imagen.thumbnailUrl 
                ? `data:${result.imagen.mimeType};base64,${result.imagen.thumbnailUrl}`
                : dataUrl;
              
              setLoadedImages(prev => ({ 
                ...prev, 
                [image.id]: { 
                  url: dataUrl,
                  thumbnailUrl: thumbnailUrl,
                  nombre: result.imagen.nombre || image.nombre || image.name,
                  sizeBytes: result.imagen.sizeBytes || image.sizeBytes || image.size,
                  mimeType: result.imagen.mimeType || image.mimeType
                }
              }));
            }
          } catch (error) {
            console.error(`Error cargando imagen ${image.id}:`, error);
            setImageErrors(prev => ({ ...prev, [image.id]: true }));
          } finally {
            setLoadingImages(prev => {
              const newState = { ...prev };
              delete newState[image.id];
              return newState;
            });
          }
        }
      }
    };
    
    loadImages();
  }, [images]);

  // Función auxiliar para obtener la URL de una imagen
  const getImageUrl = (image) => {
    // Si ya está cargada en cache, usar eso
    if (loadedImages[image.id]) {
      return loadedImages[image.id].thumbnailUrl || loadedImages[image.id].url;
    }
    // Si tiene URL directamente, usar eso (imágenes antiguas)
    if (image.thumbnailUrl || image.url) {
      return image.thumbnailUrl || image.url;
    }
    // Si no, retornar null para mostrar loading
    return null;
  };

  if (images.length === 0) {
    return (
      <Box sx={{ textAlign: 'center', py: 2 }}>
        <Image sx={{ fontSize: 48, color: 'text.secondary', mb: 1 }} />
        <Typography variant="body2" color="text.secondary">
          No hay imágenes en este chat
        </Typography>
      </Box>
    );
  }

  return (
    <Box>
      {/* Título removido - se muestra en el mensaje de la observación */}
      <Grid container spacing={1}>
        {images.map((image, index) => (
          <Grid item xs={4} sm={3} md={2} key={image.id || index}>
            <Card 
              sx={{ 
                cursor: 'pointer',
                transition: 'transform 0.2s',
                '&:hover': {
                  transform: 'scale(1.02)',
                  boxShadow: 2
                }
              }}
              onClick={() => setSelectedImage(image)}
            >
              {imageErrors[image.id] ? (
                <Box 
                  sx={{ 
                    height: 100, 
                    display: 'flex', 
                    alignItems: 'center', 
                    justifyContent: 'center',
                    bgcolor: 'grey.100'
                  }}
                >
                  <Error color="error" />
                </Box>
              ) : loadingImages[image.id] ? (
                <Box 
                  sx={{ 
                    height: 100, 
                    display: 'flex', 
                    alignItems: 'center', 
                    justifyContent: 'center',
                    bgcolor: 'grey.50'
                  }}
                >
                  <CircularProgress size={24} />
                </Box>
              ) : (
                <CardMedia
                  component="img"
                  height="100"
                  image={getImageUrl(image)}
                  alt={image.name}
                  sx={{ 
                    objectFit: 'contain',
                    bgcolor: 'grey.50',
                    p: 0.5
                  }}
                  onError={() => handleImageError(image.id)}
                />
              )}
              
              <CardContent sx={{ p: 1 }}>
                <Typography 
                  variant="caption" 
                  noWrap 
                  sx={{ 
                    display: 'block',
                    fontWeight: 500
                  }}
                >
                  {image.nombre || image.name || 'imagen.jpg'}
                </Typography>
                
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mt: 0.5 }}>
                  <Chip 
                    label={formatFileSize(image.sizeBytes || image.size)} 
                    size="small" 
                    variant="outlined"
                    sx={{ fontSize: '0.7rem', height: 20 }}
                  />
                  
                  <Box sx={{ display: 'flex', gap: 0.5 }}>
                    <Tooltip title="Ver">
                      <IconButton 
                        size="small"
                        onClick={(e) => {
                          e.stopPropagation();
                          setSelectedImage(image);
                        }}
                      >
                        <Visibility fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    
                    <Tooltip title="Descargar">
                      <IconButton 
                        size="small"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDownloadImage(image);
                        }}
                      >
                        <Download fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    
                    {canDelete && (
                      <Tooltip title="Eliminar">
                        <IconButton 
                          size="small"
                          color="error"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleDeleteImage(image.id);
                          }}
                        >
                          <Delete fontSize="small" />
                        </IconButton>
                      </Tooltip>
                    )}
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {/* Diálogo para ver imagen completa */}
      <Dialog
        open={!!selectedImage}
        onClose={() => setSelectedImage(null)}
        maxWidth="md"
        fullWidth
        fullScreen={window.innerWidth < 768}
      >
        {selectedImage && (
          <>
            <DialogTitle sx={{ 
              display: 'flex', 
              justifyContent: 'space-between', 
              alignItems: 'center',
              pb: 1
            }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Image color="primary" />
                <Typography variant="h6">
                  {selectedImage.nombre || selectedImage.name || 'Imagen'}
                </Typography>
              </Box>
              <IconButton onClick={() => setSelectedImage(null)} size="small">
                <Close />
              </IconButton>
            </DialogTitle>

            <DialogContent sx={{ pt: 1 }}>
              <Box sx={{ textAlign: 'center', mb: 2 }}>
                <img
                  src={selectedImage.url}
                  alt={selectedImage.name}
                  style={{
                    maxWidth: '100%',
                    maxHeight: '60vh',
                    objectFit: 'contain',
                    borderRadius: 8
                  }}
                  onError={() => handleImageError(selectedImage.id)}
                />
              </Box>

              <Grid container spacing={2}>
                <Grid item xs={12} sm={6}>
                  <Typography variant="subtitle2" gutterBottom>
                    Información del archivo
                  </Typography>
                  <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                    <Typography variant="body2">
                      <strong>Nombre:</strong> {selectedImage.nombre || selectedImage.name}
                    </Typography>
                    <Typography variant="body2">
                      <strong>Tamaño:</strong> {formatFileSize(selectedImage.sizeBytes || selectedImage.size)}
                    </Typography>
                    <Typography variant="body2">
                      <strong>Tipo:</strong> {selectedImage.mimeType}
                    </Typography>
                    <Typography variant="body2">
                      <strong>Subido:</strong> {formatDate(selectedImage.createdAt || selectedImage.createdTime)}
                    </Typography>
                  </Box>
                </Grid>
                
                <Grid item xs={12} sm={6}>
                  <Typography variant="subtitle2" gutterBottom>
                    Acciones
                  </Typography>
                  <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                    <Button
                      variant="outlined"
                      startIcon={<Download />}
                      onClick={() => handleDownloadImage(selectedImage)}
                      fullWidth
                    >
                      Descargar
                    </Button>
                    
                    <Button
                      variant="outlined"
                      startIcon={<Visibility />}
                      onClick={() => {
                        const newWindow = window.open();
                        newWindow.document.write(`<img src="${selectedImage.url}" style="max-width:100%" />`);
                      }}
                      fullWidth
                    >
                      Ver en nueva ventana
                    </Button>
                    
                    {canDelete && (
                      <Button
                        variant="outlined"
                        color="error"
                        startIcon={<Delete />}
                        onClick={() => {
                          handleDeleteImage(selectedImage.id);
                          setSelectedImage(null);
                        }}
                        fullWidth
                      >
                        Eliminar
                      </Button>
                    )}
                  </Box>
                </Grid>
              </Grid>
            </DialogContent>

            <DialogActions>
              <Button onClick={() => setSelectedImage(null)}>
                Cerrar
              </Button>
            </DialogActions>
          </>
        )}
      </Dialog>
    </Box>
  );
};

export default ImageGallery;
