import React, { useState, useEffect } from 'react';
import {
  Box,
  AppBar,
  Toolbar,
  Typography,
  IconButton,
  Badge,
  BottomNavigation,
  BottomNavigationAction,
  Paper,
  Alert,
  CircularProgress,
  Fade,
} from '@mui/material';
import {
  Home,
  Assignment,
  Notifications,
  Logout,
  Receipt,
  Inventory,
  CalendarToday,
} from '@mui/icons-material';
import LocalesTab from '../Supervisor/LocalesTab';
import PendientesTab from '../Supervisor/PendientesTab';
import GastosTab from '../Supervisor/GastosTab';
import ArqueosTab from '../Supervisor/ArqueosTab';
import AgendaTab from '../Supervisor/AgendaTab';
import NotificacionesTab from '../Supervisor/NotificacionesTab';
import NotificationRepository from '../../repositories/NotificationRepository';
import { NotificationSettingsButton } from '../NotificationSettings/NotificationSettingsDialog';
import pushNotificationService from '../../services/pushNotifications';
import ToastContainer from '../Common/ToastContainer';
import useToast from '../../hooks/useToast';

const SupervisorDashboard = ({ user, onLogout }) => {
  const [currentTab, setCurrentTab] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const toast = useToast();

  // Cargar datos iniciales
  useEffect(() => {
    if (!user || !user.id) return;

    const loadData = async () => {
      try {
        setLoading(true);
        
        // Inicializar servicio de notificaciones push
        await pushNotificationService.initialize();
        
        // Suscribirse a notificaciones del supervisor
        const unsubscribeNotifications = NotificationRepository.subscribeToNotificationsByUser(user.id, (notifications) => {
          console.log('Notificaciones del supervisor recibidas:', notifications);
          setNotifications(notifications);
        });

        setLoading(false);

        return () => {
          unsubscribeNotifications();
        };
      } catch (err) {
        setError('Error al cargar los datos');
        setLoading(false);
      }
    };

    loadData();
  }, [user]);

  const tabs = [
    { label: 'Locales', icon: <Home />, component: LocalesTab },
    { label: 'Pendientes', icon: <Assignment />, component: PendientesTab },
    { label: 'Gastos', icon: <Receipt />, component: GastosTab },
    { label: 'Arqueos', icon: <Inventory />, component: ArqueosTab },
    { label: 'Agenda', icon: <CalendarToday />, component: AgendaTab },
    { label: 'Notificaciones', icon: <Notifications />, component: NotificacionesTab },
  ];

  const handleLogout = () => {
    if (window.confirm('¿Estás seguro de que quieres cerrar sesión?')) {
      onLogout();
    }
  };

  if (loading) {
    return (
      <Box
        sx={{
          minHeight: '100vh',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        }}
      >
        <Box sx={{ textAlign: 'center', color: 'white' }}>
          <CircularProgress size={60} sx={{ color: 'white', mb: 2 }} />
          <Typography variant="h6" sx={{ fontWeight: 500 }}>
            Cargando panel de supervisor...
          </Typography>
        </Box>
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="error" sx={{ borderRadius: 2 }}>
          {error}
        </Alert>
      </Box>
    );
  }

  const CurrentComponent = tabs[currentTab].component;
  const unreadNotifications = notifications.filter(n => !n.leida).length;

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
      {/* App Bar - Optimizado para móviles */}
      <AppBar position="static" elevation={2}>
        <Toolbar sx={{ 
          minHeight: { xs: 56, sm: 64 },
          px: { xs: 1, sm: 2 }
        }}>
          <Typography 
            variant="h6" 
            component="div" 
            sx={{ 
              flexGrow: 1, 
              fontWeight: 600,
              fontSize: { xs: '1rem', sm: '1.25rem' },
              display: { xs: 'none', sm: 'block' }
            }}
          >
            🚀 Administración SE - Supervisor
          </Typography>
          
          {/* Título más corto para móviles */}
          <Typography 
            variant="h6" 
            component="div" 
            sx={{ 
              flexGrow: 1, 
              fontWeight: 600,
              fontSize: '1rem',
              display: { xs: 'block', sm: 'none' }
            }}
          >
            🚀 Admin SE
          </Typography>
          
          <Typography 
            variant="body2" 
            sx={{ 
              mr: { xs: 1, sm: 2 }, 
              opacity: 0.9,
              fontSize: { xs: '0.75rem', sm: '0.875rem' },
              display: { xs: 'none', sm: 'block' }
            }}
          >
            {user.nombre}
          </Typography>
          
          <NotificationSettingsButton sx={{ mr: { xs: 0.5, sm: 1 } }} />
          
          <IconButton 
            color="inherit" 
            onClick={handleLogout} 
            title="Cerrar sesión"
            size={window.innerWidth < 600 ? 'small' : 'medium'}
          >
            <Logout />
          </IconButton>
        </Toolbar>
      </AppBar>

      {/* Contenido Principal - Optimizado para móviles */}
      <Box sx={{ 
        flexGrow: 1, 
        pb: { xs: 8, sm: 7 }, // Más espacio en móviles para la navegación
        px: { xs: 1, sm: 2 }, // Padding lateral en móviles
        pt: { xs: 1, sm: 2 }  // Padding superior
      }}>
        <CurrentComponent user={user} />
      </Box>

      {/* Bottom Navigation - Optimizado para móviles */}
      <Paper 
        sx={{ 
          position: 'fixed', 
          bottom: 0, 
          left: 0, 
          right: 0, 
          zIndex: 1000,
          borderTop: '1px solid',
          borderColor: 'divider',
          height: { xs: 64, sm: 56 } // Más alto en móviles para mejor usabilidad
        }} 
        elevation={3}
      >
        <BottomNavigation
          value={currentTab}
          onChange={(event, newValue) => setCurrentTab(newValue)}
          showLabels
          sx={{
            height: '100%',
            '& .MuiBottomNavigationAction-label': {
              fontSize: { xs: '0.7rem', sm: '0.75rem' },
              mt: 0.5
            },
            '& .MuiBottomNavigationAction-root': {
              minWidth: { xs: 60, sm: 80 }
            }
          }}
        >
          {tabs.map((tab, index) => (
            <BottomNavigationAction
              key={index}
              label={tab.label}
              icon={
                tab.label === 'Notificaciones' && unreadNotifications > 0 ? (
                  <Badge 
                    badgeContent={unreadNotifications} 
                    color="error"
                    sx={{
                      '& .MuiBadge-badge': {
                        fontSize: { xs: '0.6rem', sm: '0.75rem' },
                        height: { xs: 16, sm: 18 },
                        minWidth: { xs: 16, sm: 18 }
                      }
                    }}
                  >
                    {tab.icon}
                  </Badge>
                ) : (
                  tab.icon
                )
              }
            />
          ))}
        </BottomNavigation>
      </Paper>
      
      {/* Toast Container */}
      <ToastContainer 
        toasts={toast.toasts} 
        onRemove={toast.removeToast} 
      />
    </Box>
  );
};

export default SupervisorDashboard;
