import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CardActions,
  Button,
  Grid,
  Chip,
  Fab,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Checkbox,
  FormControlLabel,
  CircularProgress,
  Divider,
  IconButton,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  ListItemButton,
} from '@mui/material';
import {
  Add,
  CheckCircle,
  RadioButtonUnchecked,
  Delete,
  Edit,
  CalendarToday,
  EventAvailable,
  DateRange,
  Close,
} from '@mui/icons-material';
import AgendaRepository from '../../repositories/AgendaRepository';
import { getCurrentUser } from '../../services/auth';

// Funciones auxiliares para manejar fechas correctamente (sin zona horaria)
const obtenerComponentesFecha = (timestamp) => {
  const fecha = new Date(timestamp);
  // Obtener componentes usando UTC para evitar problemas de zona horaria
  return {
    año: fecha.getUTCFullYear(),
    mes: fecha.getUTCMonth(),
    dia: fecha.getUTCDate()
  };
};

const normalizarFecha = (timestamp) => {
  const comp = obtenerComponentesFecha(timestamp);
  // Crear fecha en UTC a las 00:00:00
  return new Date(Date.UTC(comp.año, comp.mes, comp.dia));
};

const formatearFecha = (timestamp) => {
  const comp = obtenerComponentesFecha(timestamp);
  const dia = String(comp.dia).padStart(2, '0');
  const mes = String(comp.mes + 1).padStart(2, '0');
  return `${dia}/${mes}/${comp.año}`;
};

// Función para convertir fecha del input (YYYY-MM-DD) a timestamp en zona horaria local
const dateInputToTimestamp = (dateString) => {
  // Separar la fecha en componentes
  const [year, month, day] = dateString.split('-').map(Number);
  // Crear fecha en zona horaria local (medianoche del día seleccionado)
  const fecha = new Date(year, month - 1, day, 0, 0, 0, 0);
  return fecha.getTime();
};

const AgendaTab = ({ user }) => {
  const [actividades, setActividades] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [showEditDialog, setShowEditDialog] = useState(false);
  const [selectedActividad, setSelectedActividad] = useState(null);
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [viewMode, setViewMode] = useState('calendar'); // 'calendar' o 'list'
  const [filtroSeleccionado, setFiltroSeleccionado] = useState(null); // null, 'hoy', 'proximas', 'completadas'
  const currentUser = getCurrentUser();

  // Cargar actividades del supervisor
  useEffect(() => {
    if (!user || !user.id) return;

    setLoading(true);

    const unsubscribe = AgendaRepository.subscribeToActividadesBySupervisor(user.id, (actividades) => {
      console.log('Actividades de agenda recibidas:', actividades);
      setActividades(actividades);
      setLoading(false);
    });

    return () => {
      unsubscribe();
    };
  }, [user]);

  const handleCreateActividad = async (formData) => {
    try {
      const actividadData = {
        supervisorId: user.id,
        supervisorNombre: user.nombre,
        titulo: formData.titulo,
        descripcion: formData.descripcion,
        fecha: formData.fecha,
        completada: false,
        fechaCompletada: null,
        createdAt: Date.now(),
        updatedAt: Date.now()
      };

      const result = await AgendaRepository.createActividad(actividadData);
      if (result.success) {
        setShowCreateDialog(false);
      } else {
        alert('Error al crear actividad: ' + result.error);
      }
    } catch (error) {
      console.error('Error creando actividad:', error);
      alert('Error al crear actividad');
    }
  };

  const handleToggleCompletada = async (actividad) => {
    try {
      const result = await AgendaRepository.marcarCompletada(actividad.id, !actividad.completada);
      if (!result.success) {
        alert('Error al actualizar actividad');
      }
    } catch (error) {
      console.error('Error actualizando actividad:', error);
    }
  };

  const handleCambiarFecha = async (actividadId, nuevaFecha) => {
    try {
      const result = await AgendaRepository.cambiarFecha(actividadId, nuevaFecha);
      if (!result.success) {
        alert('Error al cambiar fecha');
      }
    } catch (error) {
      console.error('Error cambiando fecha:', error);
    }
  };

  const handleDeleteActividad = async (id) => {
    if (!window.confirm('¿Estás seguro de que quieres eliminar esta actividad?')) {
      return;
    }
    
    try {
      const result = await AgendaRepository.deleteActividad(id);
      if (!result.success) {
        alert('Error al eliminar actividad');
      }
    } catch (error) {
      console.error('Error eliminando actividad:', error);
    }
  };

  // Obtener actividades del mes actual
  const getActividadesDelMes = () => {
    const comp = obtenerComponentesFecha(selectedDate.getTime());
    
    return actividades.filter(act => {
      const actComp = obtenerComponentesFecha(act.fecha);
      return actComp.año === comp.año && actComp.mes === comp.mes;
    });
  };

  // Obtener actividades de un día específico
  const getActividadesDelDia = (fecha) => {
    const fechaNormalizada = normalizarFecha(fecha);
    
    return actividades.filter(act => {
      const actFecha = normalizarFecha(act.fecha);
      return actFecha.getTime() === fechaNormalizada.getTime();
    });
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Cargando agenda...</Typography>
      </Box>
    );
  }

  const actividadesDelMes = getActividadesDelMes();
  const actividadesPendientes = actividades.filter(a => !a.completada).length;
  const actividadesCompletadas = actividades.filter(a => a.completada).length;

  // Calcular actividades por categoría para los filtros
  const hoy = normalizarFecha(new Date());
  const actividadesHoy = actividades.filter(a => {
    const fecha = normalizarFecha(a.fecha);
    return fecha.getTime() === hoy.getTime() && !a.completada;
  });
  const actividadesProximas = actividades.filter(a => {
    const fecha = normalizarFecha(a.fecha);
    return fecha.getTime() > hoy.getTime() && !a.completada;
  });
  const actividadesCompletadasList = actividades.filter(a => a.completada);

  return (
    <Box sx={{ p: 2 }}>
      {/* Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h5" sx={{ fontWeight: 600 }}>
          Mi Agenda
        </Typography>
        <Box>
          <Button
            variant={viewMode === 'calendar' ? 'contained' : 'outlined'}
            startIcon={<CalendarToday />}
            onClick={() => setViewMode('calendar')}
            sx={{ mr: 1 }}
            size="small"
          >
            Calendario
          </Button>
          <Button
            variant={viewMode === 'list' ? 'contained' : 'outlined'}
            startIcon={<DateRange />}
            onClick={() => setViewMode('list')}
            sx={{ mr: 1 }}
            size="small"
          >
            Lista
          </Button>
          <Fab
            color="primary"
            size="medium"
            onClick={() => setShowCreateDialog(true)}
          >
            <Add />
          </Fab>
        </Box>
      </Box>

      {/* Chips de filtro */}
      <Box sx={{ mb: 2, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
        <Chip
          label={`${actividadesHoy.length} hoy`}
          onClick={() => setFiltroSeleccionado(filtroSeleccionado === 'hoy' ? null : 'hoy')}
          color={filtroSeleccionado === 'hoy' ? 'primary' : 'default'}
          variant={filtroSeleccionado === 'hoy' ? 'filled' : 'outlined'}
          icon={filtroSeleccionado === 'hoy' ? <CheckCircle /> : undefined}
        />
        <Chip
          label={`${actividadesProximas.length} próximas`}
          onClick={() => setFiltroSeleccionado(filtroSeleccionado === 'proximas' ? null : 'proximas')}
          color={filtroSeleccionado === 'proximas' ? 'primary' : 'default'}
          variant={filtroSeleccionado === 'proximas' ? 'filled' : 'outlined'}
          icon={filtroSeleccionado === 'proximas' ? <CheckCircle /> : undefined}
        />
        <Chip
          label={`${actividadesCompletadasList.length} completadas`}
          onClick={() => setFiltroSeleccionado(filtroSeleccionado === 'completadas' ? null : 'completadas')}
          color={filtroSeleccionado === 'completadas' ? 'primary' : 'default'}
          variant={filtroSeleccionado === 'completadas' ? 'filled' : 'outlined'}
          icon={filtroSeleccionado === 'completadas' ? <CheckCircle /> : undefined}
        />
      </Box>

      {/* Estadísticas */}
      <Grid container spacing={2} sx={{ mb: 3 }}>
        <Grid item xs={6} sm={4}>
          <Card sx={{ bgcolor: 'primary.light' }}>
            <CardContent>
              <Typography variant="h4" color="primary.contrastText">{actividadesPendientes}</Typography>
              <Typography variant="body2" color="primary.contrastText">Pendientes</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={6} sm={4}>
          <Card sx={{ bgcolor: 'success.light' }}>
            <CardContent>
              <Typography variant="h4" color="success.contrastText">{actividadesCompletadas}</Typography>
              <Typography variant="body2" color="success.contrastText">Completadas</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Card sx={{ bgcolor: 'info.light' }}>
            <CardContent>
              <Typography variant="h4" color="info.contrastText">{actividadesDelMes.length}</Typography>
              <Typography variant="body2" color="info.contrastText">Este Mes</Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {viewMode === 'calendar' ? (
        <CalendarioVista
          selectedDate={selectedDate}
          onDateChange={setSelectedDate}
          actividades={actividades}
          onActividadClick={(act) => {
            setSelectedActividad(act);
            setShowEditDialog(true);
          }}
          onToggleCompletada={handleToggleCompletada}
        />
      ) : (
        <ListaVista
          actividades={actividades}
          actividadesHoy={actividadesHoy}
          actividadesProximas={actividadesProximas}
          actividadesCompletadas={actividadesCompletadasList}
          filtroSeleccionado={filtroSeleccionado}
          onActividadClick={(act) => {
            setSelectedActividad(act);
            setShowEditDialog(true);
          }}
          onToggleCompletada={handleToggleCompletada}
          onDelete={handleDeleteActividad}
          onClearFilter={() => setFiltroSeleccionado(null)}
        />
      )}

      {/* Dialog para Crear Actividad */}
      <CreateActividadDialog
        open={showCreateDialog}
        onClose={() => setShowCreateDialog(false)}
        onSubmit={handleCreateActividad}
        fechaInicial={selectedDate.getTime()}
      />

      {/* Dialog para Editar/Gestionar Actividad */}
      {selectedActividad && (
        <EditActividadDialog
          open={showEditDialog}
          actividad={selectedActividad}
          onClose={() => {
            setShowEditDialog(false);
            setSelectedActividad(null);
          }}
          onToggleCompletada={() => handleToggleCompletada(selectedActividad)}
          onCambiarFecha={(nuevaFecha) => handleCambiarFecha(selectedActividad.id, nuevaFecha)}
          onDelete={() => {
            handleDeleteActividad(selectedActividad.id);
            setShowEditDialog(false);
            setSelectedActividad(null);
          }}
        />
      )}
    </Box>
  );
};

const CalendarioVista = ({ selectedDate, onDateChange, actividades, onActividadClick, onToggleCompletada }) => {
  const año = selectedDate.getFullYear();
  const mes = selectedDate.getMonth();
  
  // Obtener días del mes
  const primerDia = new Date(año, mes, 1);
  const ultimoDia = new Date(año, mes + 1, 0);
  const diasEnMes = ultimoDia.getDate();
  const diaSemanaInicio = primerDia.getDay(); // 0 = Domingo
  
  const meses = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 
                 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];

  const cambiarMes = (delta) => {
    const nuevaFecha = new Date(año, mes + delta, 1);
    onDateChange(nuevaFecha);
  };

  const getActividadesDelDia = (dia) => {
    return actividades.filter(act => {
      const actComp = obtenerComponentesFecha(act.fecha);
      return actComp.año === año &&
             actComp.mes === mes &&
             actComp.dia === dia;
    });
  };

  return (
    <Box>
      {/* Navegación de mes */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <IconButton onClick={() => cambiarMes(-1)}>
          <Typography>{"<"}</Typography>
        </IconButton>
        <Typography variant="h6">{meses[mes]} {año}</Typography>
        <IconButton onClick={() => cambiarMes(1)}>
          <Typography>{">"}</Typography>
        </IconButton>
      </Box>

      {/* Calendario */}
      <Card>
        <CardContent>
          {/* Encabezados de días */}
          <Grid container spacing={1}>
            {['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'].map(dia => (
              <Grid item xs={12/7} key={dia}>
                <Typography variant="caption" align="center" display="block" fontWeight="bold">
                  {dia}
                </Typography>
              </Grid>
            ))}
            
            {/* Espacios en blanco antes del primer día */}
            {Array.from({ length: diaSemanaInicio }).map((_, i) => (
              <Grid item xs={12/7} key={`empty-${i}`}>
                <Box sx={{ height: 80 }} />
              </Grid>
            ))}
            
            {/* Días del mes */}
            {Array.from({ length: diasEnMes }).map((_, i) => {
              const dia = i + 1;
              const actividadesDia = getActividadesDelDia(dia);
              const hoy = normalizarFecha(new Date());
              const fechaDia = normalizarFecha(new Date(año, mes, dia));
              const esHoy = hoy.getTime() === fechaDia.getTime();
              
              return (
                <Grid item xs={12/7} key={dia}>
                  <Card 
                    variant="outlined"
                    sx={{ 
                      height: 80, 
                      cursor: 'pointer',
                      bgcolor: esHoy ? 'primary.light' : 'background.paper',
                      '&:hover': { bgcolor: esHoy ? 'primary.main' : 'action.hover' }
                    }}
                    onClick={() => onDateChange(new Date(año, mes, dia))}
                  >
                    <CardContent sx={{ p: 1, '&:last-child': { pb: 1 } }}>
                      <Typography variant="body2" color={esHoy ? 'primary.contrastText' : 'text.primary'}>
                        {dia}
                      </Typography>
                      {actividadesDia.length > 0 && (
                        <Box sx={{ mt: 0.5 }}>
                          {actividadesDia.slice(0, 2).map(act => (
                            <Typography 
                              key={act.id} 
                              variant="caption" 
                              display="block"
                              sx={{ 
                                textDecoration: act.completada ? 'line-through' : 'none',
                                opacity: act.completada ? 0.6 : 1,
                                color: esHoy ? 'primary.contrastText' : 'text.secondary',
                                overflow: 'hidden',
                                textOverflow: 'ellipsis',
                                whiteSpace: 'nowrap'
                              }}
                            >
                              {act.completada ? '✓' : '•'} {act.titulo}
                            </Typography>
                          ))}
                          {actividadesDia.length > 2 && (
                            <Typography variant="caption" color={esHoy ? 'primary.contrastText' : 'text.secondary'}>
                              +{actividadesDia.length - 2} más
                            </Typography>
                          )}
                        </Box>
                      )}
                    </CardContent>
                  </Card>
                </Grid>
              );
            })}
          </Grid>
        </CardContent>
      </Card>

      {/* Actividades del día seleccionado */}
      <Box sx={{ mt: 3 }}>
        <Typography variant="h6" sx={{ mb: 2 }}>
          Actividades del {formatearFecha(selectedDate.getTime())}
        </Typography>
        
        {getActividadesDelDia(selectedDate.getDate()).length === 0 ? (
          <Card>
            <CardContent sx={{ textAlign: 'center', py: 3 }}>
              <Typography color="text.secondary">
                No hay actividades para este día
              </Typography>
            </CardContent>
          </Card>
        ) : (
          <List>
            {getActividadesDelDia(selectedDate.getDate()).map(act => (
              <Card key={act.id} sx={{ mb: 1 }}>
                <ListItemButton onClick={() => onActividadClick(act)}>
                  <ListItemIcon>
                    <Checkbox
                      edge="start"
                      checked={act.completada}
                      onClick={(e) => {
                        e.stopPropagation();
                        onToggleCompletada(act);
                      }}
                      icon={<RadioButtonUnchecked />}
                      checkedIcon={<CheckCircle color="success" />}
                    />
                  </ListItemIcon>
                  <ListItemText
                    primary={act.titulo}
                    secondary={act.descripcion}
                    sx={{
                      textDecoration: act.completada ? 'line-through' : 'none',
                      opacity: act.completada ? 0.7 : 1
                    }}
                  />
                </ListItemButton>
              </Card>
            ))}
          </List>
        )}
      </Box>
    </Box>
  );
};

const ListaVista = ({ 
  actividades, 
  actividadesHoy: actividadesHoyProps,
  actividadesProximas: actividadesProximasProps,
  actividadesCompletadas: actividadesCompletadasProps,
  filtroSeleccionado,
  onActividadClick, 
  onToggleCompletada, 
  onDelete,
  onClearFilter
}) => {
  // Usar las listas filtradas o las calculadas localmente
  const actividadesHoy = actividadesHoyProps;
  const actividadesProximas = actividadesProximasProps;
  const actividadesCompletadas = actividadesCompletadasProps;

  // Determinar qué mostrar según el filtro
  const actividadesFiltradas = filtroSeleccionado === 'hoy' ? actividadesHoy :
                                filtroSeleccionado === 'proximas' ? actividadesProximas :
                                filtroSeleccionado === 'completadas' ? actividadesCompletadas :
                                null;

  const renderActividades = (lista, titulo, showClearButton = false) => (
    <Box sx={{ mb: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6">{titulo}</Typography>
        {showClearButton && (
          <Button 
            size="small" 
            onClick={onClearFilter}
            startIcon={<Close />}
          >
            Ver todas
          </Button>
        )}
      </Box>
      {lista.length === 0 ? (
        <Typography color="text.secondary" sx={{ ml: 2 }}>Sin actividades</Typography>
      ) : (
        <List>
          {lista.map(act => (
            <Card key={act.id} sx={{ mb: 1 }}>
              <ListItem
                secondaryAction={
                  <IconButton edge="end" onClick={() => onDelete(act.id)}>
                    <Delete />
                  </IconButton>
                }
              >
                <ListItemIcon>
                  <Checkbox
                    checked={act.completada}
                    onChange={() => onToggleCompletada(act)}
                    icon={<RadioButtonUnchecked />}
                    checkedIcon={<CheckCircle color="success" />}
                  />
                </ListItemIcon>
                <ListItemButton onClick={() => onActividadClick(act)}>
                  <ListItemText
                    primary={act.titulo}
                    secondary={
                      <>
                        {act.descripcion}
                        <br />
                        <Chip 
                          label={formatearFecha(act.fecha)} 
                          size="small" 
                          sx={{ mt: 0.5 }}
                        />
                        {act.completada && <Chip label="Completada" color="success" size="small" sx={{ ml: 1 }} />}
                      </>
                    }
                    sx={{
                      textDecoration: act.completada ? 'line-through' : 'none',
                      opacity: act.completada ? 0.7 : 1
                    }}
                  />
                </ListItemButton>
              </ListItem>
            </Card>
          ))}
        </List>
      )}
    </Box>
  );

  // Si hay filtro activo, mostrar solo esa categoría
  if (actividadesFiltradas !== null) {
    const titulo = filtroSeleccionado === 'hoy' ? '📅 Hoy' :
                   filtroSeleccionado === 'proximas' ? '📆 Próximas' :
                   '✅ Completadas';
    return (
      <Box>
        {renderActividades(actividadesFiltradas, titulo, true)}
      </Box>
    );
  }

  // Sin filtro - mostrar todas organizadas
  return (
    <Box>
      {renderActividades(actividadesHoy, '📅 Hoy')}
      {renderActividades(actividadesProximas, '📆 Próximas')}
      {renderActividades(actividadesCompletadas, '✅ Completadas')}
    </Box>
  );
};

const CreateActividadDialog = ({ open, onClose, onSubmit, fechaInicial }) => {
  const [formData, setFormData] = useState({
    titulo: '',
    descripcion: '',
    fecha: new Date(fechaInicial).toISOString().split('T')[0]
  });

  useEffect(() => {
    if (open) {
      setFormData({
        titulo: '',
        descripcion: '',
        fecha: new Date(fechaInicial).toISOString().split('T')[0]
      });
    }
  }, [open, fechaInicial]);

  const handleSubmit = (e) => {
    e.preventDefault();
    const fechaTimestamp = dateInputToTimestamp(formData.fecha);
    onSubmit({ ...formData, fecha: fechaTimestamp });
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>Nueva Actividad</DialogTitle>
      <form onSubmit={handleSubmit}>
        <DialogContent>
          <Grid container spacing={2}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Título *"
                value={formData.titulo}
                onChange={(e) => setFormData(prev => ({ ...prev, titulo: e.target.value }))}
                required
                autoFocus
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Descripción"
                multiline
                rows={3}
                value={formData.descripcion}
                onChange={(e) => setFormData(prev => ({ ...prev, descripcion: e.target.value }))}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Fecha *"
                type="date"
                value={formData.fecha}
                onChange={(e) => setFormData(prev => ({ ...prev, fecha: e.target.value }))}
                required
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancelar</Button>
          <Button type="submit" variant="contained">Crear Actividad</Button>
        </DialogActions>
      </form>
    </Dialog>
  );
};

const EditActividadDialog = ({ open, actividad, onClose, onToggleCompletada, onCambiarFecha, onDelete }) => {
  const [showDatePicker, setShowDatePicker] = useState(false);
  const [nuevaFecha, setNuevaFecha] = useState('');

  return (
    <>
      <Dialog open={open && !showDatePicker} onClose={onClose} maxWidth="sm" fullWidth>
        <DialogTitle>
          {actividad.titulo}
          {actividad.completada && <Chip label="Completada" color="success" size="small" sx={{ ml: 1 }} />}
        </DialogTitle>
        <DialogContent>
          <Box sx={{ mb: 2 }}>
            <Typography variant="body2" color="text.secondary">
              {actividad.descripcion || 'Sin descripción'}
            </Typography>
          </Box>
          <Divider sx={{ my: 2 }} />
          <Box sx={{ mb: 1 }}>
            <Typography variant="body2">
              <strong>Fecha:</strong> {formatearFecha(actividad.fecha)}
            </Typography>
          </Box>
          {actividad.completada && actividad.fechaCompletada && (
            <Box>
              <Typography variant="body2">
                <strong>Completada:</strong> {formatearFecha(actividad.fechaCompletada)}
              </Typography>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={onDelete} color="error" startIcon={<Delete />}>
            Eliminar
          </Button>
          <Button onClick={() => setShowDatePicker(true)} startIcon={<DateRange />}>
            Cambiar Fecha
          </Button>
          <Button 
            onClick={onToggleCompletada} 
            variant="contained"
            color={actividad.completada ? 'warning' : 'success'}
            startIcon={actividad.completada ? <RadioButtonUnchecked /> : <CheckCircle />}
          >
            {actividad.completada ? 'Marcar Pendiente' : 'Marcar Completada'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Dialog para cambiar fecha */}
      <Dialog open={showDatePicker} onClose={() => setShowDatePicker(false)} maxWidth="xs" fullWidth>
        <DialogTitle>Cambiar Fecha</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            label="Nueva Fecha"
            type="date"
            value={nuevaFecha}
            onChange={(e) => setNuevaFecha(e.target.value)}
            InputLabelProps={{ shrink: true }}
            sx={{ mt: 1 }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setShowDatePicker(false)}>Cancelar</Button>
          <Button 
            onClick={() => {
              if (nuevaFecha) {
                const timestamp = dateInputToTimestamp(nuevaFecha);
                onCambiarFecha(timestamp);
                setShowDatePicker(false);
                onClose();
              }
            }}
            variant="contained"
            disabled={!nuevaFecha}
          >
            Guardar
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default AgendaTab;

