import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CardActions,
  Button,
  Grid,
  Chip,
  Alert,
  CircularProgress,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  ListItemAvatar,
  Avatar,
  Divider,
  Badge,
  IconButton,
  Tooltip,
} from '@mui/material';
import {
  Notifications,
  NotificationsActive,
  Warning,
  Error,
  Info,
  Assignment,
  LocationOn,
  Schedule,
  CheckCircle,
  Close,
  Refresh,
} from '@mui/icons-material';
import LocalRepository from '../../repositories/LocalRepository';
import PendienteRepository from '../../repositories/PendienteRepository';
import NotificationRepository from '../../repositories/NotificationRepository';
import pushNotificationService from '../../services/pushNotifications';

const NotificacionesTab = ({ user }) => {
  const [notifications, setNotifications] = useState([]);
  const [locales, setLocales] = useState([]);
  const [pendientes, setPendientes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Cargar datos desde Firebase en tiempo real
  useEffect(() => {
    if (!user || !user.id) return;

    setLoading(true);

    // Suscribirse a notificaciones del supervisor
    const unsubscribeNotifications = NotificationRepository.subscribeToNotificationsByUser(user.id, (notifications) => {
      console.log('Notificaciones del supervisor recibidas:', notifications);
      setNotifications(notifications);
      setLoading(false);
    });

    // Suscribirse a locales del supervisor
    const unsubscribeLocales = LocalRepository.subscribeToLocalesBySupervisor(user.id, (locales) => {
      console.log('Locales del supervisor recibidos:', locales);
      setLocales(locales);
    });

    // Suscribirse a pendientes del supervisor
    const unsubscribePendientes = PendienteRepository.subscribeToPendientesBySupervisor(user.id, (pendientes) => {
      console.log('Pendientes del supervisor recibidos:', pendientes);
      setPendientes(pendientes);
    });

    return () => {
      unsubscribeNotifications();
      unsubscribeLocales();
      unsubscribePendientes();
    };
  }, [user]);

  // Generar notificaciones automáticas basadas en vencimientos
  useEffect(() => {
    if (locales.length === 0) return;

    const generateVencimientoNotifications = async () => {
      const today = new Date();
      const notificationsToCreate = [];

      locales.forEach(local => {
        // Verificar vencimientos administrativos
        const vencimientos = [
          { campo: 'vencimiento_poliza', nombre: 'Póliza de Seguro' },
          { campo: 'vencimiento_reba', nombre: 'REBA' },
          { campo: 'vencimiento_agua', nombre: 'Agua' },
          { campo: 'vencimiento_matafuegos', nombre: 'Matafuegos' },
          { campo: 'vencimiento_fumigacion', nombre: 'Fumigación' },
        ];

        vencimientos.forEach(vencimiento => {
          const fechaVencimiento = local[vencimiento.campo];
          if (!fechaVencimiento) return;

          // Convertir fecha dd/MM/yyyy a Date
          const [day, month, year] = fechaVencimiento.split('/');
          const vencimientoDate = new Date(year, month - 1, day);
          
          // Calcular días hasta vencimiento
          const diffTime = vencimientoDate.getTime() - today.getTime();
          const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

          // Generar notificaciones según los días restantes
          if (diffDays === 30 || diffDays === 15 || diffDays === 7 || diffDays === 0) {
            let tipo = 'info';
            let mensaje = '';
            let urgencia = 'normal';

            if (diffDays === 0) {
              tipo = 'error';
              mensaje = `¡VENCIDO! ${vencimiento.nombre} del local ${local.nombre}`;
              urgencia = 'urgente';
            } else if (diffDays === 7) {
              tipo = 'warning';
              mensaje = `⚠️ Quedan 7 días para el vencimiento de ${vencimiento.nombre} del local ${local.nombre}`;
              urgencia = 'alta';
            } else if (diffDays === 15) {
              tipo = 'warning';
              mensaje = `⚠️ Quedan 15 días para el vencimiento de ${vencimiento.nombre} del local ${local.nombre}`;
              urgencia = 'media';
            } else if (diffDays === 30) {
              tipo = 'info';
              mensaje = `ℹ️ Quedan 30 días para el vencimiento de ${vencimiento.nombre} del local ${local.nombre}`;
              urgencia = 'normal';
            }

            notificationsToCreate.push(new Notification({
              id: `venc_admin_${local.nombre.replace(/\s/g, '_')}_${vencimiento.nombre.replace(/\s/g, '_')}_${diffDays}dias`,
              userId: user.id,
              tipo,
              titulo: `Vencimiento ${vencimiento.nombre}`,
              mensaje,
              referenceId: `${local.nombre}_${vencimiento.nombre}_${diffDays}`,
              localId: local.id,
              localNombre: local.nombre,
              urgencia,
              createdAt: Date.now(),
              fechaCreacion: Date.now(),
              fechaVencimiento: vencimientoDate.getTime(),
              diasRestantes: diffDays,
              leida: false,
              categoria: 'vencimiento_administrativo'
            }));
          }
        });
      });

      // Crear/actualizar idempotente
      notificationsToCreate.forEach(async (notification) => {
        const exists = notifications.find(n => n.id === notification.id);
        if (!exists) {
          await NotificationRepository.createNotification(notification);
          
          // Enviar notificación push si está habilitada
          if (pushNotificationService.isEnabled() && pushNotificationService.isNotificationTypeEnabled('vencimientos')) {
            pushNotificationService.showVencimiento({
              tipoVencimiento: notification.titulo.replace('Vencimiento ', ''),
              localNombre: notification.localNombre,
              diasRestantes: notification.diasRestantes,
              localId: notification.localId
            });
          }
        }
      });
    };

    generateVencimientoNotifications();
  }, [locales, notifications, user.id]);

  // Generar notificaciones de pendientes recibidos
  useEffect(() => {
    if (pendientes.length === 0) return;

    const generatePendienteNotifications = async () => {
      const notificationsToCreate = [];

      pendientes.forEach(pendiente => {
        // Solo crear notificación si el pendiente fue asignado al supervisor recientemente
        if (pendiente.estado === 'asignado' && pendiente.supervisorId === user.id) {
          const notificationId = `pendiente_${pendiente.id}_asignado`;
          const exists = notifications.find(n => n.id === notificationId);
          
          if (!exists) {
            notificationsToCreate.push(new Notification({
              id: notificationId,
              userId: user.id,
              tipo: 'info',
              titulo: 'Nuevo Pendiente Asignado',
              mensaje: `Se te asignó un nuevo pendiente: "${pendiente.titulo}" en el local ${pendiente.localNombre}`,
              referenceId: pendiente.id,
              localId: pendiente.localId,
              localNombre: pendiente.localNombre,
              pendienteId: pendiente.id,
              urgencia: pendiente.urgencia === 'urgente' ? 'alta' : 'normal',
              createdAt: Date.now(),
              fechaCreacion: Date.now(),
              leida: false,
              categoria: 'pendiente_asignado'
            }));
          }
        }
      });

      // Crear notificaciones
      notificationsToCreate.forEach(async (notification) => {
        await NotificationRepository.createNotification(notification);
        
        // Enviar notificación push si está habilitada
        if (pushNotificationService.isEnabled() && pushNotificationService.isNotificationTypeEnabled('pendientes')) {
          pushNotificationService.showPendienteAsignado({
            id: notification.pendienteId,
            titulo: notification.mensaje.split('"')[1] || 'Nuevo pendiente',
            localNombre: notification.localNombre,
            localId: notification.localId
          });
        }
      });
    };

    generatePendienteNotifications();
  }, [pendientes, notifications, user.id]);

  const handleMarkAsRead = async (notificationId) => {
    try {
      await NotificationRepository.markAsRead(notificationId);
    } catch (error) {
      console.error('Error marcando notificación como leída:', error);
    }
  };

  const handleMarkAllAsRead = async () => {
    try {
      const unreadNotifications = notifications.filter(n => !n.leida);
      await Promise.all(unreadNotifications.map(n => NotificationRepository.markAsRead(n.id)));
    } catch (error) {
      console.error('Error marcando todas las notificaciones como leídas:', error);
    }
  };

  const handleDeleteNotification = async (notificationId) => {
    try {
      await NotificationRepository.deleteNotification(notificationId);
    } catch (error) {
      console.error('Error eliminando notificación:', error);
    }
  };

  const getNotificationIcon = (tipo, urgencia) => {
    if (tipo === 'error' || urgencia === 'urgente') {
      return <Error color="error" />;
    } else if (tipo === 'warning' || urgencia === 'alta') {
      return <Warning color="warning" />;
    } else if (tipo === 'info') {
      return <Info color="info" />;
    }
    return <Notifications color="action" />;
  };

  const getUrgenciaColor = (urgencia) => {
    switch (urgencia) {
      case 'urgente': return 'error';
      case 'alta': return 'warning';
      case 'media': return 'info';
      default: return 'default';
    }
  };

  const getUrgenciaChip = (urgencia) => {
    const color = getUrgenciaColor(urgencia);
    const label = urgencia.charAt(0).toUpperCase() + urgencia.slice(1);
    return <Chip label={label} color={color} size="small" />;
  };

  const unreadCount = notifications.filter(n => !n.leida).length;

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Cargando notificaciones...</Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="error" sx={{ borderRadius: 2 }}>
          {error}
        </Alert>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 2 }}>
      {/* Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Box sx={{ display: 'flex', alignItems: 'center' }}>
          <NotificationsActive sx={{ mr: 1, color: 'primary.main' }} />
          <Typography variant="h6" sx={{ fontWeight: 600 }}>
            Notificaciones
          </Typography>
          {unreadCount > 0 && (
            <Badge badgeContent={unreadCount} color="error" sx={{ ml: 2 }}>
              <Notifications />
            </Badge>
          )}
        </Box>
        
        <Box>
          {unreadCount > 0 && (
            <Button
              variant="outlined"
              size="small"
              onClick={handleMarkAllAsRead}
              sx={{ mr: 1 }}
            >
              Marcar todas como leídas
            </Button>
          )}
          <IconButton onClick={() => window.location.reload()}>
            <Refresh />
          </IconButton>
        </Box>
      </Box>

      {/* Lista de notificaciones */}
      {notifications.length === 0 ? (
        <Card sx={{ textAlign: 'center', p: 4 }}>
          <Notifications sx={{ fontSize: 64, color: 'grey.400', mb: 2 }} />
          <Typography variant="h6" color="text.secondary" gutterBottom>
            No hay notificaciones
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Las notificaciones aparecerán aquí cuando tengas pendientes asignados o vencimientos próximos.
          </Typography>
        </Card>
      ) : (
        <List>
          {notifications
            .sort((a, b) => b.fechaCreacion - a.fechaCreacion)
            .map((notification, index) => (
            <React.Fragment key={notification.id}>
              <ListItem
                sx={{
                  bgcolor: notification.leida ? 'transparent' : 'action.hover',
                  borderRadius: 1,
                  mb: 1,
                }}
              >
                <ListItemAvatar>
                  <Avatar sx={{ bgcolor: `${getUrgenciaColor(notification.urgencia)}.light` }}>
                    {getNotificationIcon(notification.tipo, notification.urgencia)}
                  </Avatar>
                </ListItemAvatar>
                
                <ListItemText
                  primary={
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <Typography variant="subtitle1" sx={{ fontWeight: notification.leida ? 400 : 600 }}>
                        {notification.titulo}
                      </Typography>
                      {getUrgenciaChip(notification.urgencia)}
                      {!notification.leida && (
                        <Chip label="Nueva" color="primary" size="small" />
                      )}
                    </Box>
                  }
                  secondary={
                    <Box>
                      <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                        {notification.mensaje}
                      </Typography>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <LocationOn fontSize="small" color="action" />
                        <Typography variant="caption" color="text.secondary">
                          {notification.localNombre}
                        </Typography>
                        <Schedule fontSize="small" color="action" />
                        <Typography variant="caption" color="text.secondary">
                          {new Date(notification.fechaCreacion).toLocaleDateString('es-ES', {
                            day: '2-digit',
                            month: '2-digit',
                            year: 'numeric',
                            hour: '2-digit',
                            minute: '2-digit'
                          })}
                        </Typography>
                        {notification.diasRestantes !== undefined && (
                          <>
                            <Typography variant="caption" color="text.secondary">
                              •
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                              {notification.diasRestantes === 0 ? 'Vencido' : `${notification.diasRestantes} días restantes`}
                            </Typography>
                          </>
                        )}
                      </Box>
                    </Box>
                  }
                />
                
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                  {!notification.leida && (
                    <Tooltip title="Marcar como leída">
                      <IconButton
                        size="small"
                        onClick={() => handleMarkAsRead(notification.id)}
                      >
                        <CheckCircle color="success" />
                      </IconButton>
                    </Tooltip>
                  )}
                  <Tooltip title="Eliminar">
                    <IconButton
                      size="small"
                      onClick={() => handleDeleteNotification(notification.id)}
                    >
                      <Close color="error" />
                    </IconButton>
                  </Tooltip>
                </Box>
              </ListItem>
              {index < notifications.length - 1 && <Divider />}
            </React.Fragment>
          ))}
        </List>
      )}
    </Box>
  );
};

export default NotificacionesTab;
