import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  TextField,
  Button,
  Tab,
  Tabs,
  Grid,
  CircularProgress,
  Alert,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Autocomplete,
} from '@mui/material';
import {
  Assignment,
  Receipt,
  Description,
  Save,
  CalendarToday,
  ArrowBack,
} from '@mui/icons-material';
import LocalRepository from '../../repositories/LocalRepository';
import PendienteRepository from '../../repositories/PendienteRepository';
import GastoRepository from '../../repositories/GastoRepository';

function TabPanel({ children, value, index, ...other }) {
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`local-tabpanel-${index}`}
      aria-labelledby={`local-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}

// Función para convertir dd/MM/yyyy a YYYY-MM-DD
const convertToDateInput = (dateString) => {
  if (!dateString) return '';
  
  // Si ya está en formato YYYY-MM-DD, devolverlo tal cual
  if (/^\d{4}-\d{2}-\d{2}$/.test(dateString)) {
    return dateString;
  }
  
  // Convertir de dd/MM/yyyy a YYYY-MM-DD
  const parts = dateString.split('/');
  if (parts.length === 3) {
    const [day, month, year] = parts;
    return `${year}-${month}-${day}`;
  }
  
  return '';
};

// Función para convertir YYYY-MM-DD a dd/MM/yyyy
const convertFromDateInput = (dateString) => {
  if (!dateString) return '';
  
  // Si ya está en formato dd/MM/yyyy, devolverlo tal cual
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(dateString)) {
    return dateString;
  }
  
  // Convertir de YYYY-MM-DD a dd/MM/yyyy
  const parts = dateString.split('-');
  if (parts.length === 3) {
    const [year, month, day] = parts;
    return `${day}/${month}/${year}`;
  }
  
  return '';
};

const LocalDetailScreen = ({ localId, onBack }) => {
  const [tabValue, setTabValue] = useState(0);
  const [local, setLocal] = useState(null);
  const [pendientes, setPendientes] = useState([]);
  const [gastos, setGastos] = useState([]);
  const [loading, setLoading] = useState(true);
  
  // Campos administrativos
  const [nombreGerente, setNombreGerente] = useState('');
  const [razonSocial, setRazonSocial] = useState('');
  const [cuit, setCuit] = useState('');
  const [vencimientoPoliza, setVencimientoPoliza] = useState('');
  const [vencimientoReba, setVencimientoReba] = useState('');
  const [vencimientoAgua, setVencimientoAgua] = useState('');
  const [vencimientoMatafuegos, setVencimientoMatafuegos] = useState('');
  const [vencimientoFumigacion, setVencimientoFumigacion] = useState('');
  const [observacionesGenerales, setObservacionesGenerales] = useState('');
  
  const [saving, setSaving] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');
  const [errorMessage, setErrorMessage] = useState('');

  useEffect(() => {
    if (!localId) return;

    setLoading(true);

    // Suscribirse al local
    const unsubscribeLocal = LocalRepository.subscribeToLocal(localId, (localData) => {
      if (localData) {
        setLocal(localData);
        
        // Inicializar campos con datos del local
        const datos = localData.datosAdministrativos || {};
        setNombreGerente(datos.nombre_gerente || '');
        setRazonSocial(datos.razon_social || '');
        setCuit(datos.cuit || '');
        // Convertir fechas de dd/MM/yyyy a YYYY-MM-DD para el input date
        setVencimientoPoliza(convertToDateInput(datos.vencimiento_poliza || ''));
        setVencimientoReba(convertToDateInput(datos.vencimiento_reba || ''));
        setVencimientoAgua(convertToDateInput(datos.vencimiento_agua || ''));
        setVencimientoMatafuegos(convertToDateInput(datos.vencimiento_matafuegos || ''));
        setVencimientoFumigacion(convertToDateInput(datos.vencimiento_fumigacion || ''));
        setObservacionesGenerales(datos.observaciones_generales || '');
        setLoading(false);
      }
    });

    // Suscribirse a pendientes del local
    const unsubscribePendientes = PendienteRepository.subscribeToPendientesByLocal(localId, (pendientesData) => {
      setPendientes(pendientesData);
    });

    // Suscribirse a gastos del local
    const unsubscribeGastos = GastoRepository.subscribeToGastosByLocal(localId, (gastosData) => {
      setGastos(gastosData);
    });

    return () => {
      unsubscribeLocal();
      unsubscribePendientes();
      unsubscribeGastos();
    };
  }, [localId]);

  const handleSave = async () => {
    try {
      setSaving(true);
      setErrorMessage('');
      
      const datosAdministrativos = {
        nombre_gerente: nombreGerente,
        razon_social: razonSocial,
        cuit: cuit,
        // Convertir fechas de YYYY-MM-DD de vuelta a dd/MM/yyyy para Firebase
        vencimiento_poliza: convertFromDateInput(vencimientoPoliza),
        vencimiento_reba: convertFromDateInput(vencimientoReba),
        vencimiento_agua: convertFromDateInput(vencimientoAgua),
        vencimiento_matafuegos: convertFromDateInput(vencimientoMatafuegos),
        vencimiento_fumigacion: convertFromDateInput(vencimientoFumigacion),
        observaciones_generales: observacionesGenerales
      };

      const result = await LocalRepository.updateDatosAdministrativos(localId, datosAdministrativos);
      
      if (result.success) {
        setSuccessMessage('Datos guardados exitosamente');
        setTimeout(() => setSuccessMessage(''), 3000);
      } else {
        setErrorMessage('Error al guardar los datos');
      }
    } catch (error) {
      setErrorMessage('Error al guardar los datos');
      console.error('Error guardando datos administrativos:', error);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Cargando local...</Typography>
      </Box>
    );
  }

  if (!local) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="error">Local no encontrado</Alert>
      </Box>
    );
  }

  return (
    <Box sx={{ width: '100%' }}>
      {/* Header */}
      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 2 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', p: 2 }}>
          <Button
            startIcon={<ArrowBack />}
            onClick={onBack}
            sx={{ mr: 2 }}
          >
            Volver
          </Button>
          <Typography variant="h4" sx={{ flexGrow: 1 }}>
            {local.nombre}
          </Typography>
        </Box>
      </Box>

      {/* Tabs */}
      <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
        <Tabs value={tabValue} onChange={(e, newValue) => setTabValue(newValue)}>
          <Tab icon={<Description />} label="Datos Administrativos" iconPosition="start" />
          <Tab icon={<Assignment />} label={`Pendientes (${pendientes.length})`} iconPosition="start" />
          <Tab icon={<Receipt />} label={`Gastos (${gastos.length})`} iconPosition="start" />
        </Tabs>
      </Box>

      {/* Tab Panels */}
      
      {/* Tab Datos Administrativos */}
      <TabPanel value={tabValue} index={0}>
        {successMessage && (
          <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccessMessage('')}>
            {successMessage}
          </Alert>
        )}
        {errorMessage && (
          <Alert severity="error" sx={{ mb: 2 }} onClose={() => setErrorMessage('')}>
            {errorMessage}
          </Alert>
        )}

        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
          {/* Gerente de Local */}
          <Card>
            <CardContent>
              <Typography variant="h6" sx={{ mb: 2, fontWeight: 'bold', color: 'primary.main' }}>
                Gerente de Local
              </Typography>
              <TextField
                fullWidth
                label="Nombre del Gerente"
                value={nombreGerente}
                onChange={(e) => setNombreGerente(e.target.value)}
              />
            </CardContent>
          </Card>

          {/* Razón Social */}
          <Box>
            <Typography variant="h6" sx={{ mb: 2, fontWeight: 'bold' }}>
              Razón Social
            </Typography>
            <Card>
              <CardContent>
                <Grid container spacing={2}>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Nombre"
                      value={razonSocial}
                      onChange={(e) => setRazonSocial(e.target.value)}
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="CUIT"
                      value={cuit}
                      onChange={(e) => setCuit(e.target.value)}
                      type="number"
                    />
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Box>

          {/* Vencimientos */}
          <Card>
            <CardContent>
              <Typography variant="h6" sx={{ mb: 2, fontWeight: 'bold' }}>
                VENCIMIENTOS
              </Typography>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                <TextField
                  fullWidth
                  label="Póliza de Seguro"
                  type="date"
                  value={vencimientoPoliza}
                  onChange={(e) => setVencimientoPoliza(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                  InputProps={{
                    startAdornment: <CalendarToday sx={{ mr: 1 }} />
                  }}
                />
                <TextField
                  fullWidth
                  label="REBA"
                  type="date"
                  value={vencimientoReba}
                  onChange={(e) => setVencimientoReba(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                  InputProps={{
                    startAdornment: <CalendarToday sx={{ mr: 1 }} />
                  }}
                />
                <TextField
                  fullWidth
                  label="Análisis de Agua"
                  type="date"
                  value={vencimientoAgua}
                  onChange={(e) => setVencimientoAgua(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                  InputProps={{
                    startAdornment: <CalendarToday sx={{ mr: 1 }} />
                  }}
                />
                <TextField
                  fullWidth
                  label="Matafuegos"
                  type="date"
                  value={vencimientoMatafuegos}
                  onChange={(e) => setVencimientoMatafuegos(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                  InputProps={{
                    startAdornment: <CalendarToday sx={{ mr: 1 }} />
                  }}
                />
                <TextField
                  fullWidth
                  label="Fumigación"
                  type="date"
                  value={vencimientoFumigacion}
                  onChange={(e) => setVencimientoFumigacion(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                  InputProps={{
                    startAdornment: <CalendarToday sx={{ mr: 1 }} />
                  }}
                />
              </Box>
            </CardContent>
          </Card>

          {/* Observaciones Generales */}
          <Card>
            <CardContent>
              <Typography variant="h6" sx={{ mb: 2, fontWeight: 'bold' }}>
                Observaciones Generales
              </Typography>
              <TextField
                fullWidth
                multiline
                rows={4}
                label="Observaciones"
                value={observacionesGenerales}
                onChange={(e) => setObservacionesGenerales(e.target.value)}
              />
            </CardContent>
          </Card>

          {/* Botón Guardar */}
          <Button
            variant="contained"
            size="large"
            startIcon={<Save />}
            onClick={handleSave}
            disabled={saving}
            fullWidth
          >
            {saving ? 'Guardando...' : 'Guardar Cambios'}
          </Button>
        </Box>
      </TabPanel>

      {/* Tab Pendientes */}
      <TabPanel value={tabValue} index={1}>
        <Typography>Pendientes del local</Typography>
      </TabPanel>

      {/* Tab Gastos */}
      <TabPanel value={tabValue} index={2}>
        <Typography>Gastos del local</Typography>
      </TabPanel>
    </Box>
  );
};

export default LocalDetailScreen;
