import React, { useState, useEffect } from 'react';
import {
  Box,
  AppBar,
  Toolbar,
  Typography,
  IconButton,
  Badge,
  BottomNavigation,
  BottomNavigationAction,
  Paper,
  Alert,
  CircularProgress,
} from '@mui/material';
import {
  Home,
  Assignment,
  Receipt,
  SupervisorAccount,
  Notifications,
  Logout,
  Inventory,
  Close,
  CalendarToday,
} from '@mui/icons-material';
import { Dialog, DialogTitle, DialogContent, IconButton as MuiIconButton } from '@mui/material';
import LocalesTab from '../Maestro/LocalesTab';
import PendientesTab from '../Maestro/PendientesTab';
import GastosTab from '../Maestro/GastosTab';
import ArqueosTab from '../Maestro/ArqueosTab';
import AgendaTab from '../Maestro/AgendaTab';
import SupervisoresTab from '../Maestro/SupervisoresTab';
import NotificacionesTab from '../Maestro/NotificacionesTab';
import NotificationRepository from '../../repositories/NotificationRepository';

const MaestroDashboard = ({ user, onLogout }) => {
  const [currentTab, setCurrentTab] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [notifications, setNotifications] = useState([]);
  const [showNotifications, setShowNotifications] = useState(false);

  // Cargar datos iniciales y notificaciones
  useEffect(() => {
    const loadData = async () => {
      try {
        // Simular delay de carga
        await new Promise(resolve => setTimeout(resolve, 1000));
        setLoading(false);
      } catch (err) {
        setError('Error al cargar los datos');
        setLoading(false);
      }
    };

    loadData();
    
    // Suscribirse a notificaciones si hay usuario
    if (user && user.id) {
      const unsubscribe = NotificationRepository.subscribeToNotificationsByUser(user.id, (notifs) => {
        setNotifications(notifs);
      });
      
      return () => {
        unsubscribe();
      };
    }
  }, [user]);

  const tabs = [
    { label: 'Locales', icon: <Home />, component: LocalesTab },
    { label: 'Pendientes', icon: <Assignment />, component: PendientesTab },
    { label: 'Gastos', icon: <Receipt />, component: GastosTab },
    { label: 'Arqueos', icon: <Inventory />, component: ArqueosTab },
    { label: 'Agenda', icon: <CalendarToday />, component: AgendaTab },
    { label: 'Supervisores', icon: <SupervisorAccount />, component: SupervisoresTab },
  ];

  const handleLogout = () => {
    if (window.confirm('¿Estás seguro de que quieres cerrar sesión?')) {
      onLogout();
    }
  };

  if (loading) {
    return (
      <Box
        sx={{
          minHeight: '100vh',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        }}
      >
        <Box sx={{ textAlign: 'center', color: 'white' }}>
          <CircularProgress size={60} sx={{ color: 'white', mb: 2 }} />
          <Typography variant="h6" sx={{ fontWeight: 500 }}>
            Cargando panel de administración...
          </Typography>
        </Box>
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="error" sx={{ borderRadius: 2 }}>
          {error}
        </Alert>
      </Box>
    );
  }

  const CurrentComponent = tabs[currentTab].component;
  const unreadNotifications = notifications.filter(n => !n.leida).length;

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
      {/* App Bar */}
      <AppBar position="static" elevation={2}>
        <Toolbar sx={{ minHeight: { xs: 56, sm: 64 }, px: { xs: 1, sm: 2 } }}>
          <Typography 
            variant="h6" 
            component="div" 
            sx={{ 
              flexGrow: 1, 
              fontWeight: 600,
              fontSize: { xs: '1rem', sm: '1.25rem' },
              display: { xs: 'none', sm: 'block' }
            }}
          >
            🚀 Administración SE - Maestro
          </Typography>
          
          {/* Título más corto para móviles */}
          <Typography 
            variant="h6" 
            component="div" 
            sx={{ 
              flexGrow: 1, 
              fontWeight: 600,
              fontSize: '1rem',
              display: { xs: 'block', sm: 'none' }
            }}
          >
            🚀 Admin SE
          </Typography>
          
          <Typography 
            variant="body2" 
            sx={{ 
              mr: { xs: 1, sm: 2 }, 
              opacity: 0.9,
              fontSize: { xs: '0.75rem', sm: '0.875rem' },
              display: { xs: 'none', sm: 'block' }
            }}
          >
            {user.nombre}
          </Typography>
          
          {/* Icono de Notificaciones */}
          <IconButton 
            color="inherit" 
            onClick={() => setShowNotifications(true)} 
            title="Notificaciones"
            size={window.innerWidth < 600 ? 'small' : 'medium'}
          >
            <Badge badgeContent={unreadNotifications} color="error">
              <Notifications />
            </Badge>
          </IconButton>
          
          {/* Icono de Logout */}
          <IconButton 
            color="inherit" 
            onClick={handleLogout} 
            title="Cerrar sesión"
            size={window.innerWidth < 600 ? 'small' : 'medium'}
          >
            <Logout />
          </IconButton>
        </Toolbar>
      </AppBar>

      {/* Contenido Principal */}
      <Box sx={{ flexGrow: 1, pb: 7 }}>
        <CurrentComponent user={user} />
      </Box>

      {/* Bottom Navigation */}
      <Paper 
        sx={{ 
          position: 'fixed', 
          bottom: 0, 
          left: 0, 
          right: 0, 
          zIndex: 1000,
          borderTop: '1px solid',
          borderColor: 'divider'
        }} 
        elevation={3}
      >
        <BottomNavigation
          value={currentTab}
          onChange={(event, newValue) => setCurrentTab(newValue)}
          showLabels
        >
          {tabs.map((tab, index) => (
            <BottomNavigationAction
              key={index}
              label={tab.label}
              icon={tab.icon}
            />
          ))}
        </BottomNavigation>
      </Paper>

      {/* Dialog de Notificaciones */}
      <Dialog 
        open={showNotifications} 
        onClose={() => setShowNotifications(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          Notificaciones
          <MuiIconButton
            onClick={() => setShowNotifications(false)}
            sx={{ position: 'absolute', right: 8, top: 8 }}
          >
            <Close />
          </MuiIconButton>
        </DialogTitle>
        <DialogContent>
          <NotificacionesTab user={user} />
        </DialogContent>
      </Dialog>
    </Box>
  );
};

export default MaestroDashboard;
