import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CardActions,
  Button,
  Grid,
  Chip,
  Alert,
  CircularProgress,
  Avatar,
  Divider,
  List,
  ListItem,
  ListItemText,
  ListItemAvatar,
  Badge,
} from '@mui/material';
import {
  Notifications,
  Schedule,
  Warning,
  Info,
  CheckCircle,
  Cancel,
} from '@mui/icons-material';
import NotificationRepository from '../../repositories/NotificationRepository';
import { getCurrentUser } from '../../services/auth';

const NotificacionesTab = ({ user }) => {
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const currentUser = getCurrentUser();

  // Cargar datos desde Firebase en tiempo real (igual que la app Android)
  useEffect(() => {
    if (user && user.id) {
      setLoading(true);

      // Suscribirse a notificaciones del usuario en tiempo real
      const unsubscribe = NotificationRepository.subscribeToNotificationsByUser(user.id, (fetchedNotifications) => {
        console.log('Notificaciones del usuario recibidas de Firebase:', fetchedNotifications);
        setNotifications(fetchedNotifications);
      });

      setLoading(false);

      return () => {
        unsubscribe();
      };
    }
  }, [user]);

  const handleMarkAsRead = async (notificationId) => {
    try {
      const result = await NotificationRepository.markAsRead(notificationId);
      if (result.success) {
        // Data will update via real-time subscription
      } else {
        console.error('Error marcando notificación como leída:', result.error);
      }
    } catch (error) {
      console.error('Error marcando notificación como leída:', error);
    }
  };

  const getNotificationIcon = (tipo) => {
    switch (tipo) {
      case 'pendiente_creado': return <Schedule />;
      case 'pendiente_actualizado': return <Info />;
      case 'gasto_creado': return <Warning />;
      case 'gasto_aprobado': return <CheckCircle />;
      case 'gasto_rechazado': return <Cancel />;
      default: return <Notifications />;
    }
  };

  const getNotificationColor = (tipo) => {
    switch (tipo) {
      case 'pendiente_creado': return 'primary';
      case 'pendiente_actualizado': return 'info';
      case 'gasto_creado': return 'warning';
      case 'gasto_aprobado': return 'success';
      case 'gasto_rechazado': return 'error';
      default: return 'default';
    }
  };

  const getNotificationSeverity = (tipo) => {
    switch (tipo) {
      case 'pendiente_creado': return 'info';
      case 'pendiente_actualizado': return 'info';
      case 'gasto_creado': return 'warning';
      case 'gasto_aprobado': return 'success';
      case 'gasto_rechazado': return 'error';
      default: return 'info';
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Cargando notificaciones...</Typography>
      </Box>
    );
  }

  const notificacionesNoLeidas = notifications.filter(n => !n.leida);
  const notificacionesLeidas = notifications.filter(n => n.leida);

  return (
    <Box sx={{ p: 2 }}>
      {/* Header */}
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center', 
        mb: 3,
        p: 2,
        bgcolor: 'grey.50',
        borderRadius: 2
      }}>
        <Typography variant="h5" sx={{ fontWeight: 600 }}>
          Notificaciones
        </Typography>
        <Chip
          label={`${notificacionesNoLeidas.length} nuevas`}
          color="primary"
          variant="outlined"
        />
      </Box>

      {/* Lista de Notificaciones */}
      {notifications.length === 0 ? (
        <Card sx={{ textAlign: 'center', py: 4 }}>
          <CardContent>
            <Notifications sx={{ fontSize: 64, color: 'primary.main', mb: 2 }} />
            <Typography variant="h6" color="text.secondary">
              No hay notificaciones
            </Typography>
          </CardContent>
        </Card>
      ) : (
        <Box>
          {/* Notificaciones No Leídas */}
          {notificacionesNoLeidas.length > 0 && (
            <Box sx={{ mb: 3 }}>
              <Typography variant="h6" sx={{ mb: 2, fontWeight: 600 }}>
                Nuevas ({notificacionesNoLeidas.length})
              </Typography>
              <Grid container spacing={2}>
                {notificacionesNoLeidas.map((notification) => (
                  <Grid item xs={12} key={notification.id}>
                    <NotificationCard
                      notification={notification}
                      onMarkAsRead={() => handleMarkAsRead(notification.id)}
                      getNotificationIcon={getNotificationIcon}
                      getNotificationColor={getNotificationColor}
                      getNotificationSeverity={getNotificationSeverity}
                    />
                  </Grid>
                ))}
              </Grid>
            </Box>
          )}

          {/* Notificaciones Leídas */}
          {notificacionesLeidas.length > 0 && (
            <Box>
              <Typography variant="h6" sx={{ mb: 2, fontWeight: 600 }}>
                Anteriores ({notificacionesLeidas.length})
              </Typography>
              <Grid container spacing={2}>
                {notificacionesLeidas.map((notification) => (
                  <Grid item xs={12} key={notification.id}>
                    <NotificationCard
                      notification={notification}
                      onMarkAsRead={() => handleMarkAsRead(notification.id)}
                      getNotificationIcon={getNotificationIcon}
                      getNotificationColor={getNotificationColor}
                      getNotificationSeverity={getNotificationSeverity}
                    />
                  </Grid>
                ))}
              </Grid>
            </Box>
          )}
        </Box>
      )}
    </Box>
  );
};

const NotificationCard = ({ 
  notification, 
  onMarkAsRead, 
  getNotificationIcon, 
  getNotificationColor, 
  getNotificationSeverity 
}) => {
  const formatDate = (timestamp) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diff = now - date;
    
    if (diff < 60000) { // Menos de 1 minuto
      return 'Hace un momento';
    } else if (diff < 3600000) { // Menos de 1 hora
      const minutes = Math.floor(diff / 60000);
      return `Hace ${minutes} minuto${minutes > 1 ? 's' : ''}`;
    } else if (diff < 86400000) { // Menos de 1 día
      const hours = Math.floor(diff / 3600000);
      return `Hace ${hours} hora${hours > 1 ? 's' : ''}`;
    } else {
      return date.toLocaleDateString('es-AR', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    }
  };

  return (
    <Card sx={{ 
      '&:hover': { boxShadow: 4 }, 
      opacity: notification.leida ? 0.7 : 1,
      border: notification.leida ? 'none' : '2px solid',
      borderColor: notification.leida ? 'transparent' : 'primary.main'
    }}>
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'flex-start', mb: 1 }}>
          <Avatar sx={{ 
            mr: 2, 
            bgcolor: getNotificationColor(notification.tipo) + '.main',
            width: 40,
            height: 40
          }}>
            {getNotificationIcon(notification.tipo)}
          </Avatar>
          <Box sx={{ flexGrow: 1 }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 1 }}>
              <Typography variant="h6" sx={{ fontWeight: 600 }}>
                {notification.titulo}
              </Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Chip
                  label={notification.tipo.replace('_', ' ').toUpperCase()}
                  size="small"
                  color={getNotificationColor(notification.tipo)}
                  variant="outlined"
                />
                {!notification.leida && (
                  <Chip
                    label="NUEVA"
                    size="small"
                    color="primary"
                    variant="filled"
                  />
                )}
              </Box>
            </Box>
            
            <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
              {notification.mensaje}
            </Typography>
            
            <Typography variant="caption" color="text.secondary">
              {formatDate(notification.createdAt)}
            </Typography>
          </Box>
        </Box>
      </CardContent>
      
      {!notification.leida && (
        <CardActions>
          <Button 
            size="small" 
            onClick={onMarkAsRead}
            variant="outlined"
          >
            Marcar como leída
          </Button>
        </CardActions>
      )}
    </Card>
  );
};

export default NotificacionesTab;