import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  FormControlLabel,
  Switch,
  Typography,
  Box,
  Alert,
  Divider,
  IconButton,
  Tooltip,
} from '@mui/material';
import {
  Notifications,
  NotificationsOff,
  Settings,
  VolumeUp,
  VolumeOff,
  Vibration,
} from '@mui/icons-material';
import pushNotificationService from '../../services/pushNotifications';

const NotificationSettingsDialog = ({ open, onClose }) => {
  const [settings, setSettings] = useState({
    pendientes: true,
    vencimientos: true,
    gastos: true,
    sonido: true,
    vibrar: true,
  });
  const [isEnabled, setIsEnabled] = useState(false);
  const [permissionStatus, setPermissionStatus] = useState('default');

  useEffect(() => {
    if (open) {
      // Cargar configuración actual
      const currentSettings = pushNotificationService.getNotificationSettings();
      setSettings(currentSettings);
      
      // Verificar estado de permisos
      setIsEnabled(pushNotificationService.isEnabled());
      setPermissionStatus(pushNotificationService.permission);
    }
  }, [open]);

  const handleSettingChange = (setting) => (event) => {
    const newSettings = {
      ...settings,
      [setting]: event.target.checked
    };
    setSettings(newSettings);
    pushNotificationService.saveNotificationSettings(newSettings);
  };

  const handleRequestPermission = async () => {
    const granted = await pushNotificationService.requestPermission();
    setIsEnabled(granted);
    setPermissionStatus(pushNotificationService.permission);
    
    if (granted) {
      // Mostrar notificación de prueba
      pushNotificationService.showCustomNotification(
        '🔔 Notificaciones Habilitadas',
        'Ahora recibirás notificaciones importantes del sistema',
        { type: 'test' }
      );
    }
  };

  const handleDisableAll = () => {
    pushNotificationService.disable();
    setSettings({
      pendientes: false,
      vencimientos: false,
      gastos: false,
      sonido: false,
      vibrar: false,
    });
  };

  const handleEnableAll = () => {
    pushNotificationService.enableAll();
    setSettings({
      pendientes: true,
      vencimientos: true,
      gastos: true,
      sonido: true,
      vibrar: true,
    });
  };

  const getPermissionStatusText = () => {
    switch (permissionStatus) {
      case 'granted': return 'Permisos concedidos';
      case 'denied': return 'Permisos denegados';
      default: return 'Permisos no solicitados';
    }
  };

  const getPermissionStatusColor = () => {
    switch (permissionStatus) {
      case 'granted': return 'success';
      case 'denied': return 'error';
      default: return 'warning';
    }
  };

  return (
    <Dialog 
      open={open} 
      onClose={onClose} 
      maxWidth="sm" 
      fullWidth
      fullScreen={window.innerWidth < 600}
      sx={{
        '& .MuiDialog-paper': {
          m: { xs: 0, sm: 2 },
          borderRadius: { xs: 0, sm: 2 }
        }
      }}
    >
      <DialogTitle sx={{ 
        display: 'flex', 
        alignItems: 'center', 
        gap: 1,
        fontSize: { xs: '1.1rem', sm: '1.25rem' },
        px: { xs: 2, sm: 3 },
        py: { xs: 2, sm: 3 }
      }}>
        <Notifications color="primary" />
        Configuración de Notificaciones
      </DialogTitle>
      
      <DialogContent sx={{ px: { xs: 2, sm: 3 }, py: { xs: 1, sm: 2 } }}>
        {/* Estado de permisos */}
        <Box sx={{ mb: 3 }}>
          <Typography 
            variant="h6" 
            gutterBottom
            sx={{ fontSize: { xs: '1rem', sm: '1.25rem' } }}
          >
            Estado de Permisos
          </Typography>
          
          <Alert 
            severity={getPermissionStatusColor()} 
            sx={{ mb: 2 }}
            action={
              permissionStatus !== 'granted' && (
                <Button 
                  color="inherit" 
                  size="small" 
                  onClick={handleRequestPermission}
                >
                  Solicitar Permisos
                </Button>
              )
            }
          >
            {getPermissionStatusText()}
          </Alert>
          
          {!isEnabled && (
            <Alert severity="info" sx={{ mb: 2 }}>
              Para recibir notificaciones, necesitas conceder permisos al navegador.
            </Alert>
          )}
        </Box>

        <Divider sx={{ mb: 3 }} />

        {/* Configuraciones de notificaciones */}
        <Typography variant="h6" gutterBottom>
          Tipos de Notificaciones
        </Typography>
        
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          <FormControlLabel
            control={
              <Switch
                checked={settings.pendientes}
                onChange={handleSettingChange('pendientes')}
                disabled={!isEnabled}
              />
            }
            label={
              <Box>
                <Typography variant="body1">Nuevos Pendientes</Typography>
                <Typography variant="caption" color="text.secondary">
                  Notificar cuando se te asignen nuevos pendientes
                </Typography>
              </Box>
            }
          />
          
          <FormControlLabel
            control={
              <Switch
                checked={settings.vencimientos}
                onChange={handleSettingChange('vencimientos')}
                disabled={!isEnabled}
              />
            }
            label={
              <Box>
                <Typography variant="body1">Vencimientos</Typography>
                <Typography variant="caption" color="text.secondary">
                  Alertar sobre vencimientos próximos (30, 15, 7 días y día exacto)
                </Typography>
              </Box>
            }
          />
          
          <FormControlLabel
            control={
              <Switch
                checked={settings.gastos}
                onChange={handleSettingChange('gastos')}
                disabled={!isEnabled}
              />
            }
            label={
              <Box>
                <Typography variant="body1">Estado de Gastos</Typography>
                <Typography variant="caption" color="text.secondary">
                  Notificar cuando tus gastos sean aprobados o rechazados
                </Typography>
              </Box>
            }
          />
        </Box>

        <Divider sx={{ my: 3 }} />

        {/* Configuraciones adicionales */}
        <Typography variant="h6" gutterBottom>
          Configuraciones Adicionales
        </Typography>
        
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          <FormControlLabel
            control={
              <Switch
                checked={settings.sonido}
                onChange={handleSettingChange('sonido')}
                disabled={!isEnabled}
              />
            }
            label={
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                {settings.sonido ? <VolumeUp /> : <VolumeOff />}
                <Typography variant="body1">Sonido</Typography>
              </Box>
            }
          />
          
          <FormControlLabel
            control={
              <Switch
                checked={settings.vibrar}
                onChange={handleSettingChange('vibrar')}
                disabled={!isEnabled}
              />
            }
            label={
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Vibration />
                <Typography variant="body1">Vibración</Typography>
              </Box>
            }
          />
        </Box>

        <Divider sx={{ my: 3 }} />

        {/* Acciones rápidas */}
        <Typography variant="h6" gutterBottom>
          Acciones Rápidas
        </Typography>
        
        <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
          <Button
            variant="outlined"
            onClick={handleEnableAll}
            disabled={!isEnabled}
            startIcon={<Notifications />}
          >
            Habilitar Todas
          </Button>
          
          <Button
            variant="outlined"
            color="error"
            onClick={handleDisableAll}
            startIcon={<NotificationsOff />}
          >
            Deshabilitar Todas
          </Button>
        </Box>
      </DialogContent>
      
      <DialogActions>
        <Button onClick={onClose}>
          Cerrar
        </Button>
      </DialogActions>
    </Dialog>
  );
};

// Componente de botón para abrir configuración
export const NotificationSettingsButton = ({ sx = {} }) => {
  const [open, setOpen] = useState(false);
  const [isEnabled, setIsEnabled] = useState(false);

  useEffect(() => {
    setIsEnabled(pushNotificationService.isEnabled());
  }, []);

  return (
    <>
      <Tooltip title="Configurar Notificaciones">
        <IconButton
          onClick={() => setOpen(true)}
          sx={{
            color: isEnabled ? 'primary.main' : 'text.secondary',
            ...sx
          }}
        >
          {isEnabled ? <Notifications /> : <NotificationsOff />}
        </IconButton>
      </Tooltip>
      
      <NotificationSettingsDialog 
        open={open} 
        onClose={() => setOpen(false)} 
      />
    </>
  );
};

export default NotificationSettingsDialog;
