import React, { useState, useRef } from 'react';
import {
  Box,
  Button,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Typography,
  LinearProgress,
  Alert,
  Grid,
  Card,
  CardMedia,
  CardContent,
  CardActions,
  Chip,
  Tooltip,
  Fab,
  Badge,
} from '@mui/material';
import {
  CloudUpload,
  Image,
  Delete,
  Close,
  CheckCircle,
  Error,
  AttachFile,
  PhotoCamera,
} from '@mui/icons-material';
import { useToast } from '../../hooks/useToast';
import imageUploadService from '../../services/imageUploadService';
import ImagenRepository from '../../repositories/ImagenRepository';
import CameraCapture from './CameraCapture';

const ImageUploadDialog = ({ 
  open, 
  onClose, 
  onUploadComplete, 
  pendienteId,
  existingImages = [] 
}) => {
  const [selectedFiles, setSelectedFiles] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [showCamera, setShowCamera] = useState(false);
  const fileInputRef = useRef(null);
  const { showSuccess, showError, showWarning } = useToast();

  // El servicio de imágenes no requiere configuración

  const handleFileSelect = (event) => {
    const files = Array.from(event.target.files);
    const validFiles = files.filter(file => {
      if (file.size > 5 * 1024 * 1024) {
        showWarning(`El archivo ${file.name} es demasiado grande (máximo 5MB). Selecciona una imagen más pequeña.`);
        return false;
      }
      if (!file.type.startsWith('image/')) {
        showWarning(`El archivo ${file.name} no es una imagen válida`);
        return false;
      }
      return true;
    });

    setSelectedFiles(prev => [...prev, ...validFiles]);
  };

  const removeFile = (index) => {
    setSelectedFiles(prev => prev.filter((_, i) => i !== index));
  };

  const handleUpload = async () => {
    if (selectedFiles.length === 0) {
      showWarning('Selecciona al menos una imagen');
      return;
    }

    setUploading(true);
    setUploadProgress(0);

    try {
      const uploadedImages = [];
      
      for (let i = 0; i < selectedFiles.length; i++) {
        const file = selectedFiles[i];
        const progress = ((i + 1) / selectedFiles.length) * 100;
        setUploadProgress(progress);

        try {
          // Obtener datos base64 del servicio de upload
          const imageData = await imageUploadService.uploadImage(file, pendienteId);
          
          // Extraer solo la parte base64 del data URL
          const base64String = imageData.url.includes(',') 
            ? imageData.url.split(',')[1] 
            : imageData.url;
          
          // Guardar en colección 'imagenes' usando ImagenRepository
          const imagenDocument = {
            nombre: imageData.name,
            mimeType: imageData.mimeType,
            sizeBytes: imageData.size,
            dataBase64: base64String, // Guardar solo la parte base64
            thumbnailUrl: imageData.thumbnailUrl || '',
            url: '', // Sin Firebase Storage
            createdAt: Date.now()
          };
          
          const saveResult = await ImagenRepository.saveImagen(imagenDocument);
          
          if (saveResult.success) {
            // Retornar solo la referencia con ID (SIN url ni thumbnailUrl con base64)
            const imagenRef = {
              id: saveResult.id,
              nombre: imageData.name,
              mimeType: imageData.mimeType,
              sizeBytes: imageData.size,
              pendienteId: pendienteId,
              createdAt: Date.now()
            };
            
            console.log('✅ Imagen guardada en colección "imagenes", enviando solo ID:', imagenRef);
            uploadedImages.push(imagenRef);
          } else {
            console.error(`Error guardando ${file.name}:`, saveResult.error);
            showError(`Error guardando ${file.name}: ${saveResult.error}`);
          }
        } catch (error) {
          console.error(`Error subiendo ${file.name}:`, error);
          showError(`Error subiendo ${file.name}: ${error.message}`);
        }
      }

      if (uploadedImages.length > 0) {
        console.log('📤 ENVIANDO AL PENDIENTE:', uploadedImages);
        console.log('⚠️ Si ves "url" o "thumbnailUrl" con base64, hay un problema!');
        showSuccess(`${uploadedImages.length} imagen(es) subida(s) correctamente`);
        onUploadComplete(uploadedImages);
        handleClose();
      } else {
        showError('No se pudo subir ninguna imagen');
      }
    } catch (error) {
      console.error('Error en upload:', error);
      showError('Error subiendo imágenes: ' + error.message);
    } finally {
      setUploading(false);
      setUploadProgress(0);
    }
  };

  const handleClose = () => {
    setSelectedFiles([]);
    setUploading(false);
    setUploadProgress(0);
    onClose();
  };

  const handleCameraCapture = (file) => {
    // Agregar el archivo capturado a la lista de archivos seleccionados
    setSelectedFiles(prev => [...prev, file]);
    setShowCamera(false);
  };

  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <>
    <Dialog 
      open={open} 
      onClose={handleClose}
      maxWidth="md"
      fullWidth
      fullScreen={window.innerWidth < 768}
    >
      <DialogTitle sx={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        pb: 1
      }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Image color="primary" />
          <Typography variant="h6">
            Subir Imágenes al Chat
          </Typography>
        </Box>
        <IconButton onClick={handleClose} size="small">
          <Close />
        </IconButton>
      </DialogTitle>

      <DialogContent sx={{ pt: 1 }}>
        <Box>

            {/* Imágenes existentes */}
            {existingImages.length > 0 && (
              <Box sx={{ mb: 3 }}>
                <Typography variant="subtitle2" gutterBottom>
                  Imágenes actuales ({existingImages.length})
                </Typography>
                <Grid container spacing={1}>
                  {existingImages.map((img, index) => (
                    <Grid item xs={6} sm={4} md={3} key={index}>
                      <Card sx={{ maxWidth: 120 }}>
                        <CardMedia
                          component="img"
                          height="80"
                          image={img.thumbnailUrl || img.url}
                          alt={img.name}
                          sx={{ objectFit: 'cover' }}
                        />
                        <CardContent sx={{ p: 1 }}>
                          <Typography variant="caption" noWrap>
                            {img.name}
                          </Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                  ))}
                </Grid>
              </Box>
            )}

            {/* Selección de archivos */}
            <Box sx={{ mb: 2 }}>
              <input
                ref={fileInputRef}
                type="file"
                multiple
                accept="image/*"
                onChange={handleFileSelect}
                style={{ display: 'none' }}
              />
              
              <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
                <Button
                  variant="contained"
                  startIcon={<PhotoCamera />}
                  onClick={() => setShowCamera(true)}
                  fullWidth
                >
                  Tomar Foto
                </Button>
                
                <Button
                  variant="outlined"
                  startIcon={<AttachFile />}
                  onClick={() => fileInputRef.current?.click()}
                  fullWidth
                >
                  Seleccionar de Galería
                </Button>
              </Box>

              <Typography variant="caption" color="text.secondary">
                Máximo 5MB por imagen (se comprime automáticamente). Formatos: JPG, PNG, GIF, WebP
              </Typography>
            </Box>

            {/* Archivos seleccionados */}
            {selectedFiles.length > 0 && (
              <Box sx={{ mb: 2 }}>
                <Typography variant="subtitle2" gutterBottom>
                  Archivos seleccionados ({selectedFiles.length})
                </Typography>
                <Grid container spacing={1}>
                  {selectedFiles.map((file, index) => (
                    <Grid item xs={12} sm={6} key={index}>
                      <Card variant="outlined">
                        <CardContent sx={{ p: 2 }}>
                          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <Box sx={{ flex: 1, minWidth: 0 }}>
                              <Typography variant="body2" noWrap>
                                {file.name}
                              </Typography>
                              <Typography variant="caption" color="text.secondary">
                                {formatFileSize(file.size)}
                              </Typography>
                            </Box>
                            <IconButton
                              size="small"
                              onClick={() => removeFile(index)}
                              color="error"
                            >
                              <Delete fontSize="small" />
                            </IconButton>
                          </Box>
                        </CardContent>
                      </Card>
                    </Grid>
                  ))}
                </Grid>
              </Box>
            )}

            {/* Progreso de subida */}
            {uploading && (
              <Box sx={{ mb: 2 }}>
                <Typography variant="body2" gutterBottom>
                  Subiendo imágenes...
                </Typography>
                <LinearProgress 
                  variant="determinate" 
                  value={uploadProgress} 
                  sx={{ height: 8, borderRadius: 4 }}
                />
                <Typography variant="caption" color="text.secondary">
                  {Math.round(uploadProgress)}% completado
                </Typography>
              </Box>
            )}
          </Box>
      </DialogContent>

      <DialogActions sx={{ p: 2 }}>
        <Button onClick={handleClose} disabled={uploading}>
          Cancelar
        </Button>
        <Button
          onClick={handleUpload}
          variant="contained"
          disabled={selectedFiles.length === 0 || uploading}
          startIcon={uploading ? <LinearProgress size={16} /> : <CloudUpload />}
        >
          {uploading ? 'Subiendo...' : `Subir ${selectedFiles.length} imagen(es)`}
        </Button>
      </DialogActions>
    </Dialog>

    {/* Dialog de cámara */}
    <CameraCapture
      open={showCamera}
      onClose={() => setShowCamera(false)}
      onCapture={handleCameraCapture}
    />
    </>
  );
};

export default ImageUploadDialog;
