import React, { useState, useMemo } from 'react';
import {
  Box,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Chip,
  Button,
  Typography,
  Card,
  CardContent,
  Grid,
  IconButton,
  Tooltip,
  Collapse,
} from '@mui/material';
import {
  Search,
  FilterList,
  Clear,
  ExpandMore,
  ExpandLess,
  Download,
  Refresh,
} from '@mui/icons-material';

const AdvancedSearch = ({ 
  items = [], 
  onSearch, 
  onExport,
  searchFields = [],
  filterOptions = {},
  placeholder = "Buscar...",
  showFilters = true,
  showExport = true
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filters, setFilters] = useState({});
  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);

  const filteredItems = useMemo(() => {
    let result = items;

    // Aplicar búsqueda de texto
    if (searchTerm) {
      const lowerSearchTerm = searchTerm.toLowerCase();
      result = result.filter(item => {
        return searchFields.some(field => {
          const fieldValue = item[field];
          if (typeof fieldValue === 'string') {
            return fieldValue.toLowerCase().includes(lowerSearchTerm);
          }
          return false;
        });
      });
    }

    // Aplicar filtros
    Object.entries(filters).forEach(([key, value]) => {
      if (value && value !== '') {
        result = result.filter(item => {
          const itemValue = item[key];
          
          if (typeof value === 'boolean') {
            return itemValue === value;
          }
          
          if (typeof value === 'string') {
            return itemValue?.toLowerCase().includes(value.toLowerCase());
          }
          
          return itemValue === value;
        });
      }
    });

    return result;
  }, [items, searchTerm, filters, searchFields]);

  const handleSearchChange = (event) => {
    const value = event.target.value;
    setSearchTerm(value);
    onSearch?.(value, filters);
  };

  const handleFilterChange = (key, value) => {
    const newFilters = { ...filters, [key]: value };
    setFilters(newFilters);
    onSearch?.(searchTerm, newFilters);
  };

  const clearFilters = () => {
    setSearchTerm('');
    setFilters({});
    onSearch?.('', {});
  };

  const handleExport = () => {
    onExport?.(filteredItems);
  };

  const activeFiltersCount = Object.values(filters).filter(value => 
    value && value !== ''
  ).length;

  return (
    <Card sx={{ mb: 3 }}>
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
          <TextField
            fullWidth
            placeholder={placeholder}
            value={searchTerm}
            onChange={handleSearchChange}
            InputProps={{
              startAdornment: <Search sx={{ mr: 1, color: 'text.secondary' }} />,
              endAdornment: searchTerm && (
                <IconButton
                  size="small"
                  onClick={() => setSearchTerm('')}
                  sx={{ mr: -1 }}
                >
                  <Clear />
                </IconButton>
              )
            }}
            sx={{ flex: 1 }}
          />
          
          {showFilters && (
            <Tooltip title="Filtros avanzados">
              <Button
                variant="outlined"
                startIcon={<FilterList />}
                onClick={() => setShowAdvancedFilters(!showAdvancedFilters)}
                sx={{ minWidth: 'auto' }}
              >
                Filtros
                {activeFiltersCount > 0 && (
                  <Chip
                    label={activeFiltersCount}
                    size="small"
                    color="primary"
                    sx={{ ml: 1, height: 20, fontSize: '0.75rem' }}
                  />
                )}
                {showAdvancedFilters ? <ExpandLess /> : <ExpandMore />}
              </Button>
            </Tooltip>
          )}

          {showExport && (
            <Tooltip title="Exportar resultados">
              <Button
                variant="outlined"
                startIcon={<Download />}
                onClick={handleExport}
                disabled={filteredItems.length === 0}
                sx={{ minWidth: 'auto' }}
              >
                Exportar
              </Button>
            </Tooltip>
          )}

          <Tooltip title="Limpiar filtros">
            <IconButton onClick={clearFilters} disabled={!searchTerm && activeFiltersCount === 0}>
              <Refresh />
            </IconButton>
          </Tooltip>
        </Box>

        <Collapse in={showAdvancedFilters}>
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle2" gutterBottom>
              Filtros Avanzados
            </Typography>
            <Grid container spacing={2}>
              {Object.entries(filterOptions).map(([key, options]) => (
                <Grid item xs={12} sm={6} md={3} key={key}>
                  <FormControl fullWidth size="small">
                    <InputLabel>{options.label}</InputLabel>
                    <Select
                      value={filters[key] || ''}
                      onChange={(e) => handleFilterChange(key, e.target.value)}
                      label={options.label}
                    >
                      <MenuItem value="">
                        <em>Todos</em>
                      </MenuItem>
                      {options.options.map((option) => (
                        <MenuItem key={option.value} value={option.value}>
                          {option.label}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>
              ))}
            </Grid>
          </Box>
        </Collapse>

        {/* Filtros activos */}
        {activeFiltersCount > 0 && (
          <Box sx={{ mt: 2 }}>
            <Typography variant="body2" color="text.secondary" gutterBottom>
              Filtros activos:
            </Typography>
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
              {Object.entries(filters).map(([key, value]) => {
                if (!value || value === '') return null;
                
                const option = filterOptions[key]?.options?.find(opt => opt.value === value);
                const label = option?.label || value;
                
                return (
                  <Chip
                    key={key}
                    label={`${filterOptions[key]?.label || key}: ${label}`}
                    onDelete={() => handleFilterChange(key, '')}
                    size="small"
                    color="primary"
                    variant="outlined"
                  />
                );
              })}
            </Box>
          </Box>
        )}

        {/* Resultados */}
        <Box sx={{ mt: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
          <Typography variant="body2" color="text.secondary">
            {filteredItems.length} resultado{filteredItems.length !== 1 ? 's' : ''}
          </Typography>
          {filteredItems.length !== items.length && (
            <Typography variant="body2" color="text.secondary">
              de {items.length} total
            </Typography>
          )}
        </Box>
      </CardContent>
    </Card>
  );
};

export default AdvancedSearch;
