// Modelo Pendiente - Exactamente igual que la app Android
import Observacion from './Observacion';

class Pendiente {
  constructor({
    id = '',
    localId = '',
    localNombre = '',
    supervisorId = '',
    supervisorNombre = '',
    creadoPor = '',
    creadoPorNombre = '',
    descripcion = '',
    estado = 'asignado',
    observaciones = [],
    prioridad = 'media',
    area = '',
    urgencia = false,
    fechaLimite = 0,
    createdAt = Date.now(),
    updatedAt = Date.now()
  } = {}) {
    this.id = id;
    this.localId = localId;
    this.localNombre = localNombre;
    this.supervisorId = supervisorId;
    this.supervisorNombre = supervisorNombre;
    this.creadoPor = creadoPor;
    this.creadoPorNombre = creadoPorNombre;
    this.descripcion = descripcion;
    this.estado = estado;
    this.observaciones = observaciones;
    this.prioridad = prioridad;
    this.area = area;
    this.urgencia = urgencia;
    this.fechaLimite = fechaLimite;
    this.createdAt = createdAt;
    this.updatedAt = updatedAt;
  }

  toMap() {
    return {
      id: this.id,
      localId: this.localId,
      localNombre: this.localNombre,
      supervisorId: this.supervisorId,
      supervisorNombre: this.supervisorNombre,
      creadoPor: this.creadoPor,
      creadoPorNombre: this.creadoPorNombre,
      descripcion: this.descripcion,
      estado: this.estado,
      observaciones: this.observaciones.map(obs => obs.toMap ? obs.toMap() : obs),
      prioridad: this.prioridad,
      area: this.area,
      urgencia: this.urgencia,
      fechaLimite: this.fechaLimite,
      createdAt: this.createdAt,
      updatedAt: this.updatedAt
    };
  }

  static fromMap(map) {
    const observacionesList = (map.observaciones || []).map(obs => {
      if (typeof obs === 'object' && obs.id) {
        return Observacion.fromMap(obs);
      }
      return obs;
    });

    return new Pendiente({
      id: map.id || '',
      localId: map.localId || '',
      localNombre: map.localNombre || '',
      supervisorId: map.supervisorId || '',
      supervisorNombre: map.supervisorNombre || '',
      creadoPor: map.creadoPor || '',
      creadoPorNombre: map.creadoPorNombre || '',
      descripcion: map.descripcion || '',
      estado: map.estado || 'asignado',
      observaciones: observacionesList,
      prioridad: map.prioridad || 'media',
      area: map.area || '',
      urgencia: map.urgencia || false,
      fechaLimite: map.fechaLimite || 0,
      createdAt: map.createdAt || Date.now(),
      updatedAt: map.updatedAt || Date.now()
    });
  }
}

export default Pendiente;