// Modelo Observacion - Extendido para soportar imágenes
class Observacion {
  constructor({
    id = '',
    mensaje = '',
    enviadoPor = '',
    enviadoPorNombre = '',
    rol = '',
    timestamp = Date.now(),
    tipo = '', // 'imagenes' o vacío para observación normal
    imagenes = [] // Array de imágenes cuando tipo === 'imagenes'
  } = {}) {
    this.id = id;
    this.mensaje = mensaje;
    this.enviadoPor = enviadoPor;
    this.enviadoPorNombre = enviadoPorNombre;
    this.rol = rol;
    this.timestamp = timestamp;
    this.tipo = tipo;
    this.imagenes = imagenes || [];
  }

  toMap() {
    const map = {
      id: this.id,
      mensaje: this.mensaje,
      enviadoPor: this.enviadoPor,
      enviadoPorNombre: this.enviadoPorNombre,
      rol: this.rol,
      timestamp: this.timestamp
    };
    
    // Incluir tipo e imágenes si existen
    if (this.tipo) {
      map.tipo = this.tipo;
    }
    if (this.imagenes && this.imagenes.length > 0) {
      map.imagenes = this.imagenes;
    }
    
    return map;
  }

  static fromMap(map) {
    return new Observacion({
      id: map.id || '',
      mensaje: map.mensaje || '',
      enviadoPor: map.enviadoPor || '',
      enviadoPorNombre: map.enviadoPorNombre || '',
      rol: map.rol || '',
      timestamp: map.timestamp || Date.now(),
      tipo: map.tipo || '',
      imagenes: map.imagenes || []
    });
  }
}

export default Observacion;